import { PagedPacking, requestPacking } from "../entities/Entities";
import http from "../../../HttpHelper";

class PackingRepository {
  /**
   * @param page {int}
   * @param rowsPerPage {int}
   * @param orderBy {string}
   * @param situation {string}
   * @param sort {string}
   * @param chipData {string}
   * @returns {Promise<PagedPacking>}
   */

  async listPacking(page, rowsPerPage, orderBy, sort, chipData) {
    try {
      const filters = `${chipData.size == 0
          ? ""
          : chipData.map(
            (data) =>
              "&filter=(" + data.columnPopover + ":" + data.valueFilter + ")"
          )
        }`;

      const response = await http.get(
        `/packing?page=${page}&size=${rowsPerPage}&orderBy=${orderBy}&sortBy=${sort}${filters == "" ? "" : filters.replaceAll(",", "")
        }`
      );
      return new PagedPacking(
        response.data.packingList,
        response.data.numberPages
      );
    } catch (e) {
      console.log(`erro: ${e}`);
    }
  }

  /**
   * @param {*} packing
   * @returns
   */
  async setPacking(packing) {
    try {
      return http.put(`/packing/${packing.packingId}/${packing.warehouseId}/${packing.date}`);
    } catch (error) {
      throw error.response;
    }
  }

  /**
   * @param packingId {int}
   * @returns {Object}
   */
  async detailingPackingProduct(packingId) {
    try {
      const response = await http.get(`/packing/${packingId}/detailed`);
      return new requestPacking(response.data.packingList);
    } catch (error) {
      return error.response;
    }
  }

  /**
   * @param packingId {int}
   * @param page {int}
   * @param rowsPerPage {int}
   * @param orderBy {string}
   * @param sort {string}
   * @returns {Promise<PagedPacking>}
   */
  async detailingPackingSummary(packingId, page, rowsPerPage, orderBy, sort) {
    try {
      const response = await http.get(
        `/packing/${packingId}/boxes/summary?page=${page}&size=${rowsPerPage}&orderBy=${orderBy}&sortBy=${sort}`
      );
      return new PagedPacking(response.data.boxes, response.data.numberPages);
    } catch (error) {
      return error.response;
    }
  }

  /**
   * @param packingId {int}
   * @param page {int}
   * @param rowsPerPage {int}
   * @param orderBy {string}
   * @param sort {string}
   * @returns {Promise<PagedPacking>}
   */
  async detailingPackingByColor(packingId, page, rowsPerPage, orderBy, sort) {
    try {
      const response = await http.get(
        `/packing/${packingId}/boxes/colors?page=${page}&size=${rowsPerPage}&orderBy=${orderBy}&sortBy=${sort}`
      );
      return new PagedPacking(response.data.boxes, response.data.numberPages);
    } catch (error) {
      return error.response;
    }
  }
}

export const packingRepository = new PackingRepository()
