import { packingRepository } from "../repositories/PackingRepositories";

class PackingUseCases {
  /**
   * @param uuid  {Number}
   * @param comex {Number}
   * @param buyer {string}
   * @param warehouse  {string}
   * @param receiveDate {Date}
   * @param sendDate {Date}
   * @param totalGrossWeight {Number}
   * @param totalNetWeight {Number}
   * @param boxTotalQuantity {Number}
   * @param totalCubeMeter {Number}
   * @param chipData {String}
   */

  async listPacking(page, rowsPerPage, orderBy, sort, chipData) {
    const response = await packingRepository.listPacking(
      page,
      rowsPerPage,
      orderBy,
      sort,
      chipData
    );
    return response;
  }

  /**
   * @param {*} packing
   * @returns
   */
  async setConfirmPacking(packing) {
    const actualDay = require("dayjs");
    const actualDataFormat = parseInt(actualDay().format("YYYYMMDD"));
    const error = new Map();

    if (packing.warehouseId === 0) {
      const errorCode = { key: "warehouseId" };
      error.set(errorCode, "You need select a Warehouse");
    }

    if (packing.packingId === "") {
      const errorCode = { key: "packingId" };
      error.set(errorCode, "This packing id is invalid");
    }

    const numericDate = parseInt(
      packing.date.trim().replaceAll("-", "").slice(0, 8)
    );

    if (numericDate > actualDataFormat) {
      const errorCode = { key: "packingDate" };
      error.set(errorCode, "This date is invalid");
    }

    if (error.size > 0) {
      console.log(`error -> `, error);
      return error;
    }

    const response = await packingRepository.setPacking(packing);
    if (response.data.error) {
      throw response.data.error;
    } else {
      return response.data;
    }
  }

  /**
   * @param packingId {Number}
   * @returns {Object}
   */
  async detailingPackingProduct(packingId) {
    const response = await packingRepository.detailingPackingProduct(packingId);
    return response;
  }

  /**
   * @param packingId {Number}
   * @returns {Object}
   */
  async detailingPackingSummary(packingId, page, rowsPerPage, orderBy, sort) {
    const response = await packingRepository.detailingPackingSummary(
      packingId,
      page,
      rowsPerPage,
      orderBy,
      sort
    );
    return response;
  }

  /**
   * @param packingId {Number}
   * @returns {Object}
   */
  async detailingPackingByColor(packingId, page, rowsPerPage, orderBy, sort) {
    const response = await packingRepository.detailingPackingByColor(
      packingId,
      page,
      rowsPerPage,
      orderBy,
      sort
    );
    return response;
  }
}

export const packingUseCases = new PackingUseCases();
