import * as React from "react";
import { useState } from "react";
import Box from "@mui/material/Box";
import Typography from "@mui/material/Typography";
import ArrowBackRoundedIcon from "@mui/icons-material/ArrowBackRounded";

import Paper from "@mui/material/Paper";
import { styled } from "@mui/material/styles";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableCell, { tableCellClasses } from "@mui/material/TableCell";
import TableContainer from "@mui/material/TableContainer";
import TableHead from "@mui/material/TableHead";
import TableRow from "@mui/material/TableRow";
import Select from "@mui/material/Select";
import MenuItem from "@mui/material/MenuItem";
import Pagination from "@mui/material/Pagination";
import Stack from "@mui/material/Stack";
import InfoIcon from "@mui/icons-material/Info";
import Input from "@mui/material/Input";
import FormControl from "@mui/material/FormControl";

import { useNavigate } from "react-router-dom";
import { InputLabel } from "@mui/material";

//STYLES
const StyledTableCell = styled(TableCell)(({ theme }) => ({
  [`&.${tableCellClasses.head}`]: {
    backgroundColor: "#15191C",
    color: theme.palette.common.white,
  },
  [`&.${tableCellClasses.body}`]: {
    fontSize: 14,
  },
}));

const StyledTableRow = styled(TableRow)(({ theme }) => ({
  "&:nth-of-type(odd)": {
    backgroundColor: theme.palette.action.hover,
  },
  "&:last-child td, &:last-child th": {
    border: 0,
  },
}));

function TechnicalInformation() {
  const [pageList, setPageList] = useState([]);
  const [page, setPage] = useState(1);
  const [rowsPerPage, setRowsPerPage] = useState(5);
  const [enteredFilter, setEnteredFilter] = useState([]);

  const navigate = useNavigate();

  const previousPage = () => {
    navigate(-1);
  };

  const handleChangePage = (event, value) => {
    setPage(value);
  };

  const handleChangeRowsPerPage = (event) => {
    setRowsPerPage(+event.target.value);
    setPage(1);
  };

  return (
    <Box sx={{ display: "flex" }}>
      {/* <ScreenSkeleton data={"Product"} /> */}
      <Box sx={{ width: "100%", marginRight: "2rem" }}>
        <Box
          sx={{
            display: "flex",
            flexDirection: "row",
            justifyContent: "space-between",
            alignItems: "center",
          }}
        >
          <Typography
            sx={{
              fontSize: "26pt",
              fontWeight: "800",
              marginLeft: "3rem",
              marginTop: "3rem",
            }}
          >
            Technical Information
          </Typography>
          <ArrowBackRoundedIcon
            titleAccess="Previous page"
            sx={{
              marginTop: "3rem",
              fontSize: 30,
              cursor: "pointer",
              "&:hover": { color: "blue" },
            }}
            onClick={previousPage}
          />
        </Box>
        <Box
          sx={{
            display: "flex",
            flexDirection: "column",
            marginLeft: "3rem",
            marginTop: "2rem",
          }}
        >
          <Box sx={{ display: "flex", flexDirection: "row" }}>
            <InputLabel sx={{ width: "7rem", textAlign: "right" }}>
              Product code
            </InputLabel>
            <InputLabel
              sx={{ marginLeft: "1rem", fontWeight: "bold", width: "5rem" }}
            >
              1CIA1
            </InputLabel>
            <InputLabel
              sx={{ width: "10rem", marginLeft: "5rem", textAlign: "right" }}
            >
              Situation
            </InputLabel>
            <InputLabel sx={{ fontWeight: "bold", marginLeft: "1rem" }}>
              Ativo
            </InputLabel>
          </Box>
          <Box sx={{ display: "flex", flexDirection: "row" }}>
            <InputLabel sx={{ width: "7rem", textAlign: "right" }}>
              Description
            </InputLabel>
            <InputLabel sx={{ marginLeft: "1rem", fontWeight: "bold" }}>
              MEIA 0001-BEBE SEM DESENHO B
            </InputLabel>
          </Box>
          <Box sx={{ display: "flex", flexDirection: "row" }}>
            <Box
              sx={{
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
              }}
            >
              <Box sx={{ display: "flex", flexDirection: "row" }}>
                <InputLabel sx={{ width: "7rem", textAlign: "right" }}>
                  Gross value
                </InputLabel>
                <InputLabel
                  sx={{ marginLeft: "1rem", fontWeight: "bold", width: "5rem" }}
                >
                  0
                </InputLabel>
              </Box>
              <Box sx={{ display: "flex", flexDirection: "row" }}>
                <InputLabel sx={{ width: "7rem", textAlign: "right" }}>
                  Net value
                </InputLabel>
                <InputLabel
                  sx={{ marginLeft: "1rem", fontWeight: "bold", width: "5rem" }}
                >
                  0,10000
                </InputLabel>
              </Box>
              <Box sx={{ display: "flex", flexDirection: "row" }}>
                <InputLabel sx={{ width: "7rem", textAlign: "right" }}>
                  Width
                </InputLabel>
                <InputLabel
                  sx={{ marginLeft: "1rem", fontWeight: "bold", width: "5rem" }}
                >
                  0
                </InputLabel>
              </Box>
              <Box sx={{ display: "flex", flexDirection: "row" }}>
                <InputLabel sx={{ width: "7rem", textAlign: "right" }}>
                  Height
                </InputLabel>
                <InputLabel
                  sx={{ marginLeft: "1rem", fontWeight: "bold", width: "5rem" }}
                >
                  0
                </InputLabel>
              </Box>
              <Box sx={{ display: "flex", flexDirection: "row" }}>
                <InputLabel sx={{ width: "7rem", textAlign: "right" }}>
                  DUN14
                </InputLabel>
                <InputLabel
                  sx={{ marginLeft: "1rem", fontWeight: "bold", width: "5rem" }}
                >
                  0
                </InputLabel>
              </Box>
            </Box>
            <Box sx={{ display: "flex", flexDirection: "column" }}>
              <Box sx={{ display: "flex", flexDirection: "row" }}>
                <InputLabel
                  sx={{
                    width: "10rem",
                    marginLeft: "5rem",
                    textAlign: "right",
                  }}
                >
                  Unit of measurement
                </InputLabel>
                <InputLabel
                  sx={{ marginLeft: "1rem", fontWeight: "bold", width: "5rem" }}
                >
                  PR - PAR
                </InputLabel>
              </Box>
              <Box sx={{ display: "flex", flexDirection: "row" }}>
                <InputLabel
                  sx={{
                    width: "10rem",
                    marginLeft: "5rem",
                    textAlign: "right",
                  }}
                >
                  Sales multiple
                </InputLabel>
                <InputLabel
                  sx={{ marginLeft: "1rem", fontWeight: "bold", width: "5rem" }}
                >
                  1
                </InputLabel>
              </Box>
              <Box sx={{ display: "flex", flexDirection: "row" }}>
                <InputLabel
                  sx={{
                    width: "10rem",
                    marginLeft: "5rem",
                    textAlign: "right",
                  }}
                >
                  Volume
                </InputLabel>
                <InputLabel
                  sx={{ marginLeft: "1rem", fontWeight: "bold", width: "5rem" }}
                >
                  0
                </InputLabel>
              </Box>
              <Box sx={{ display: "flex", flexDirection: "row" }}>
                <InputLabel
                  sx={{
                    width: "10rem",
                    marginLeft: "5rem",
                    textAlign: "right",
                  }}
                >
                  Cube
                </InputLabel>
                <InputLabel
                  sx={{ marginLeft: "1rem", fontWeight: "bold", width: "5rem" }}
                >
                  0
                </InputLabel>
              </Box>
            </Box>
          </Box>

          <Box sx={{ display: "flex" }}>
            <FormControl
              sx={{ m: 1, width: "35ch", marginLeft: "3rem" }}
              variant="standard"
            >
              <InputLabel>Search color</InputLabel>
              <Input
                value={enteredFilter}
                onChange={(event) => setEnteredFilter(event.target.value)}
                type="text"
              />
            </FormControl>
          </Box>

          <Paper
            sx={{
              justifyContent: "center",
              marginLeft: "3rem",
              marginTop: "1rem",
            }}
          >
            <TableContainer component={Paper}>
              <Table aria-label="Product Colors Table" sx={{ width: "100%" }}>
                <TableHead>
                  <TableRow>
                    <StyledTableCell sx={{ width: "20%" }} align={"right"}>
                      Code
                    </StyledTableCell>
                    <StyledTableCell sx={{ width: "50%" }} align={"left"}>
                      Description
                    </StyledTableCell>
                    <StyledTableCell sx={{ width: "20%" }} align={"right"}>
                      EAN13
                    </StyledTableCell>
                    <StyledTableCell
                      sx={{ width: "10%" }}
                      align={"left"}
                    ></StyledTableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  <StyledTableRow>
                    <StyledTableCell align={"right"}>8001</StyledTableCell>
                    <StyledTableCell align={"left"}>Branco</StyledTableCell>
                    <StyledTableCell align={"right"}>
                      7891113108010
                    </StyledTableCell>
                    <StyledTableCell align={"center"}>
                      <InfoIcon
                        titleAccess="Details"
                        sx={{ cursor: "pointer", "&:hover": { color: "blue" } }}
                      />
                    </StyledTableCell>
                  </StyledTableRow>
                </TableBody>
              </Table>
            </TableContainer>
          </Paper>
          <Box
            display={"flex"}
            justifyContent={"end"}
            justifyItems={"center"}
            sx={{ marginTop: "10px", alignItems: "center", gap: "15px" }}
          >
            <Typography sx={{ align: "center", fontSize: "11pt" }}>
              Rows Per Page
            </Typography>
            <Select
              sx={{ height: "35px" }}
              labelId="demo-simple-select-label"
              id="demo-simple-select"
              autoWidth
              defaultValue={5}
              label="Rows"
              onChange={handleChangeRowsPerPage}
            >
              <MenuItem value={5}>5</MenuItem>
              <MenuItem value={10}>10</MenuItem>
              <MenuItem value={15}>15</MenuItem>
            </Select>

            <Stack spacing={2}>
              <Pagination
                count={pageList}
                page={page}
                onChange={handleChangePage}
              />
            </Stack>
          </Box>
        </Box>
      </Box>
    </Box>
  );
}

export default TechnicalInformation;
