import { userRepository } from "../repositories/UserRepository";

class UserUseCase {
  /**
   * @param page {int}
   * @param rowsPerPage {int}
   * @param orderBy {string}
   * @param sort {string}
   * @param chipData {Filter[]}
   *
   */

  async getUsers(
    page,
    rowsPerPage,
    orderBy,
    sort,
    chipData,
    checked
  ) {
    const response = await userRepository.getUsers(
      page,
      rowsPerPage,
      orderBy,
      sort,
      chipData,
      checked
    );
    return response;
  }

  async getUserByUuid(uuid) {
    return await userRepository.getUserByUuid(uuid);
  }

  async getUserTypes() {
    return await userRepository.getUserTypes();
  }

  async postUser(user) {
    return await userRepository.postUser(user);
  }

  async generateNewPassword(authenticationRecord) {
    return await userRepository.generateNewPassword(authenticationRecord);
  }
}

export const userUseCase = new UserUseCase();
