import {
  Button,
  Chip,
  FormControlLabel,
  Grid,
  IconButton,
  ListItem,
  MenuItem,
  Pagination,
  Paper,
  Popover,
  Select,
  Table,
  TableBody,
  TableCell,
  tableCellClasses,
  TableContainer,
  TableHead,
  TableRow,
  TableSortLabel,
  TextField,
  Tooltip,
  Typography,
} from "@mui/material";
import { Box, Stack } from "@mui/system";
import { createRoot } from "react-dom/client";
import ModalVendor from "../component/ModalVendor";
import AddBusinessIcon from "@mui/icons-material/AddBusiness";
import styled from "@emotion/styled";
import { vendorUseCases } from "../usecases/VendorUseCases";
import EditIcon from "@mui/icons-material/Edit";
import FilterListRoundedIcon from "@mui/icons-material/FilterListRounded";
import { useState, useEffect } from "react";
import CallIcon from "@mui/icons-material/Call";
import EmailIcon from "@mui/icons-material/Email";
import LanguageIcon from "@mui/icons-material/Language";
import ContentCopyRoundedIcon from "@mui/icons-material/ContentCopyRounded";
import { CopyToClipboard } from "react-copy-to-clipboard";

const VendorIcon = AddBusinessIcon;

const StyledTableCell = styled(TableCell)(({ theme }) => ({
  [`&.${tableCellClasses.head}`]: {
    backgroundColor: "#15191C",
    color: "white",
  },
  [`&.${tableCellClasses.body}`]: {
    fontSize: 14,
  },
}));

const StyledTableRow = styled(TableRow)(({ theme }) => ({
  "&:nth-of-type(odd)": {
    backgroundColor: "#f3f3f3",
  },
  "&:last-child td, &:last-child th": {
    border: 0,
  },
}));

const columns = [
  {
    value: "identifier",
    label: "Identifier",
    width: "8%",
    align: "left",
    isOrder: "true",
    isFilter: "true",
    isNumber: false,
    maxLength: "9",
  },
  {
    value: "name",
    label: "Name",
    width: "8%",
    align: "left",
    isOrder: "true",
    isFilter: "true",
    isNumber: false,
    maxLength: "9",
  },
  {
    value: "address",
    label: "Address",
    width: "8%",
    align: "left",
    isOrder: "true",
    isFilter: "true",
    isNumber: false,
    maxLength: "9",
  },
  {
    value: "contact",
    label: "Contact",
    width: "8%",
    align: "left",
    isOrder: "false",
    isFilter: "false",
    isNumber: false,
    maxLength: "9",
  },
  {
    value: "situation",
    label: "Situation",
    width: "8%",
    align: "left",
    isOrder: "false",
    isFilter: "false",
    isNumber: false,
    maxLength: "9",
  },
  {
    value: "action",
    label: "Action",
    width: "1%",
    align: "center",
    isOrder: "false",
    isFilter: "false",
    isNumber: false,
    maxLength: "9",
  },
];

const Vendor = () => {
  const [vendorList, setVendorList] = useState([]);
  const [page, setPage] = useState(1);
  const [rowsPerPage, setRowsPerPage] = useState(10);
  const [orderBy, setOrderBy] = useState("receiveDate");
  const [sort, setSort] = useState("asc");
  const [chipData, setChipData] = useState([]);
  const [changed, setChanged] = useState(true);
  const [columnPopover, setColumnPopover] = useState("");
  const [valuePopover, setValuePopover] = useState("");
  const [labelFilter, setLabelFilter] = useState("");
  const [typePopover, setTypePopover] = useState("");
  const [anchorEl, setAnchorEl] = useState(null);
  const [anchorE2, setAnchorE2] = useState(null);
  const [labelPopover, setLabelPopover] = useState("");
  const [maxLegthPopover, setMaxLegthPopover] = useState(60);
  const [isNumber, setIsNumber] = useState();
  const [situation, setSituation] = useState(0);
  const [pageList, setPageList] = useState(1);
  const [contactList, setContactList] = useState([]);

  const handleOpenModalVendor = (evt, vendorIdentifier) => {
    evt.preventDefault();
    const container = document.getElementById("modal-vendor");
    const root = createRoot(container);
    return root.render(
      <ModalVendor
        vendorUUID={vendorIdentifier}
        isOpen={true}
        parentCallback={() => setChanged(!changed)}
      />
    );
  };

  /**
   * - *English* Variable to reset the filters
   * - *Português* Variável para resetar os filtros
   */

  const handClickResetList = () => {
    setChipData([]);
    setLabelFilter("");
    setValuePopover("");
    setPage(1);
    setSituation(0);
    setRowsPerPage(10);
    setOrderBy("");
  };

  const handleCopy = (value) => {
    navigator.clipboard.writeText();
  };

  const openPopoverContact = Boolean(anchorE2);

  const idContact = openPopoverContact ? "simple-popover" : undefined;

  const handleClickPopoverContact = (event, contact) => {
    const newContact = contact;

    setContactList(newContact);

    setAnchorE2(event);
  };

  const handleClosePopoverContact = () => {
    setAnchorE2(null);
  };

  /**
   * - *English* Variable to assign the Popover position
   * - *Português* Variável para atribuir a posição do Popover
   */
  const openPopover = Boolean(anchorEl);

  /**
   * - *English* Variable to assign to Popover style
   * - *Português* Variável para atribuir a estilo do Popover
   */
  const id = openPopover ? "simple-popover" : undefined;

  /**
   * - *English* Function to open and assign variables in Popover
   * - *Português* Função para abrir e atribuir variaveis no Popover
   * - @param event @param label @param column @param type
   */
  const handleClickPopover = (
    event,
    label,
    column,
    type,
    maxLength,
    number
  ) => {
    setAnchorEl(event);
    setLabelPopover(label);
    setColumnPopover(column);
    setTypePopover(type);
    setMaxLegthPopover(maxLength);
    setIsNumber(number);
  };

  /**
   * - *English* Function to assign the filter field to a state variable
   * - *Português* Função para atribuir o campo do filtro a uma variavel de estado
   * - @param event
   */
  const handleChangePopover = (event) => {
    setValuePopover(event.target.value);
  };

  const handleChangeNumberPopover = (event) => {
    event.target.value = event.target.value.replace(/[^0-9,]/g, "");
    setValuePopover(event.target.value);
  };
  /**
   * - *English* Function to assign the table column field to a state variable and close the Popover
   * - *Português* Função para atribuir o campo da columa da tabela a uma variavel de estado e fechar o Popover
   */
  const handleConfirmPopover = () => {
    setAnchorEl(null);
    setChipData((chips) =>
      chips.filter((chip) => chip.labelFilter !== labelPopover)
    );
    setChipData((prevState) => [
      ...prevState,
      {
        labelFilter: labelPopover,
        columnPopover: columnPopover,
        valueFilter: valuePopover,
      },
    ]);
    setPage(1);
    setChanged(!changed);
  };

  const keyPress = (e) => {
    if (e.keyCode === 13) {
      handleConfirmPopover();
    }
  };

  /**
   * - *English* Function to close the Popover
   * - *Português* Função para fechar o Popover
   */
  const handleClosePopover = () => {
    setAnchorEl(null);
  };

  /**
   * - *English* Function to delete chip itens
   * - *Português* Função para deletar itens no chip
   */
  const handleDelete = (chipToDelete) => () => {
    setChipData((chips) =>
      chips.filter((chip) => chip.labelFilter !== chipToDelete.labelFilter)
    );
  };

  /**
   * - *English* Function to pagination
   * - *Português* Função para paginação
   * - @param event
   */
  const handleChangeRowsPerPage = (event) => {
    setRowsPerPage(+event.target.value);
    setPage(1);
    setOrderBy("");
    setSort("asc");
  };

  /**
   * - *English* Function to pagination
   * - *Português* Função para paginação
   * - @param event @param value
   */
  const handleChangePage = (event, value) => {
    setPage(value);
    setOrderBy("");
    setSort("asc");
  };

  /**
   * - *English* Function to sort in ascending/descending order
   * - *Português* Função para ordenar de forma crescente/decrecente
   * - @param event @param isOrder
   */
  const handleOrderBy = (value, isOrder) => {
    if (isOrder === "true") {
      if (orderBy === value) {
        setOrderBy(value);
        setSort(sort === "asc" ? "desc" : "asc");
      } else {
        setOrderBy(value);
        setSort("asc");
      }
    }
    setPage(1);
  };

  useEffect(() => {
    document.title = "Lince Tech Micro ERP | Vendor";
    const getVendors = async () => {
      const PagedVendor = await vendorUseCases.vendorGet(
        page,
        rowsPerPage,
        orderBy,
        sort,
        chipData
      );
      return PagedVendor;
    };
    getVendors().then((response) => {
      setVendorList(response.vendor);
      setPageList(response.numberPages);
    });
  }, [
    page,
    rowsPerPage,
    pageList,
    changed,
    situation,
    orderBy,
    sort,
    labelFilter,
    chipData,
  ]);

  return (
    <Box
      sx={{
        display: "flex",
        marginLeft: "3rem",
        marginTop: "3rem",
        marginRight: "2rem",
      }}
    >
      <input type="hidden" id="modal-vendor" />
      <Box sx={{ width: "100%" }}>
        <Typography sx={{ fontSize: "26pt", fontWeight: "800" }}>
          Vendor
        </Typography>
        <Box
          sx={{
            minWidth: "100%",
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
            marginTop: "0.5rem",
          }}
        >
          <Box sx={{ display: "flex" }}>
            <Box
              sx={{
                display: "flex",
                justifyContent: "center",
                flexWrap: "nowrap",
                listStyle: "none",
                p: 0,
                m: 0,
                border: "none",
                height: "4rem",
                alignItems: "center",
              }}
            >
              {chipData.map((data) => {
                return (
                  <ListItem key={data.valueFilter}>
                    <Tooltip title={data.labelFilter} placement="bottom" arrow>
                      <Chip
                        sx={{
                          textOverFlow: "ellipsis",
                          overFlow: "hidden",
                          whiteSpace: "nowrap",
                          maxWidth: "145px",
                        }}
                        color="primary"
                        variant="outlined"
                        label={data.valueFilter}
                        onDelete={handleDelete(data)}
                      />
                    </Tooltip>
                  </ListItem>
                );
              })}
            </Box>
            {chipData.length === 0 ? (
              <></>
            ) : (
              <Button onClick={handClickResetList}>Clear All</Button>
            )}
          </Box>
          <Box>
            <Tooltip title="Register Vendor">
              <IconButton size="large">
                <VendorIcon
                  fontSize="large"
                  color="action"
                  onClick={(evt) => handleOpenModalVendor(evt)}
                />
              </IconButton>
            </Tooltip>
          </Box>
        </Box>

        <Paper sx={{ width: "100%", overflow: "hidden", marginTop: "0.5rem" }}>
          <TableContainer sx={{ maxHeight: "80vh" }}>
            <Table stickyHeader aria-label="sticky table">
              <TableHead>
                <StyledTableRow>
                  {columns.map((key, index) => (
                    <StyledTableCell
                      key={index}
                      align={key.align}
                      width={key.width}
                    >
                      <Grid
                        container
                        justifyContent={"space-between"}
                        flexWrap={"nowrap"}
                      >
                        {key.isOrder === "true" ? (
                          <TableSortLabel
                            sx={{
                              "&.MuiTableSortLabel-root": {
                                color: "white",
                              },
                              "&.MuiTableSortLabel-root:hover": {
                                color: "white",
                              },
                              "&.Mui-active": {
                                color: "white",
                              },
                              "& .MuiTableSortLabel-icon": {
                                color: "white !important",
                              },
                            }}
                            active={orderBy === key.value}
                            direction={sort}
                            onClick={() =>
                              handleOrderBy(key.value, key.isOrder)
                            }
                          >
                            {key.label}
                          </TableSortLabel>
                        ) : (
                          <>{key.label}</>
                        )}
                        {key.isFilter === "true" && (
                          <FilterListRoundedIcon
                            variant="contained"
                            onClick={(e) =>
                              handleClickPopover(
                                e.currentTarget,
                                key.label,
                                key.value,
                                key.type,
                                key.maxLength,
                                key.isNumber
                              )
                            }
                            sx={{
                              width: "18px",
                              justifySelf: "end",
                              cursor: "pointer",
                            }}
                          />
                        )}
                      </Grid>
                    </StyledTableCell>
                  ))}
                </StyledTableRow>
              </TableHead>
              <TableBody>
                {vendorList.map((vendor, index) => {
                  return (
                    <StyledTableRow key={index}>
                      <StyledTableCell size="small">
                        {vendor.identifier}
                      </StyledTableCell>
                      <StyledTableCell size="small">
                        {vendor.name}
                      </StyledTableCell>
                      <StyledTableCell size="small">
                        {vendor.address}
                      </StyledTableCell>
                      <StyledTableCell
                        size="small"
                        sx={{ cursor: "pointer" }}
                        onClick={(e) =>
                          vendor.contact.length > 0
                            ? handleClickPopoverContact(
                                e.currentTarget,
                                vendor.contact
                              )
                            : ""
                        }
                      >
                        {vendor.contact.length > 0
                          ? vendor.contact[0].label
                          : "-"}
                      </StyledTableCell>
                      <StyledTableCell size="small">
                        {vendor.isActive ? "Active" : "Inactive"}
                      </StyledTableCell>
                      <StyledTableCell size="small">
                        <Tooltip title="Edit vendor" placement="left">
                          <IconButton
                            color="default"
                            onClick={(evt) =>
                              handleOpenModalVendor(evt, vendor.identifier)
                            }
                          >
                            <EditIcon />
                          </IconButton>
                        </Tooltip>
                      </StyledTableCell>
                    </StyledTableRow>
                  );
                })}
              </TableBody>
            </Table>
          </TableContainer>
        </Paper>
        <Box
          display={"flex"}
          justifyContent={"flex-end"}
          sx={{ marginTop: "2vh", alignItems: "center", gap: "1vw" }}
        >
          <Typography sx={{ align: "center", fontSize: "11pt" }}>
            Rows Per Page
          </Typography>

          <Select
            sx={{ height: "4vh", align: "center" }}
            autoWidth
            value={rowsPerPage}
            onChange={handleChangeRowsPerPage}
          >
            <MenuItem value={5}>5</MenuItem>
            <MenuItem value={10}>10</MenuItem>
            <MenuItem value={15}>15</MenuItem>
          </Select>

          <Stack spacing={2}>
            <Pagination
              count={pageList}
              page={page}
              onChange={handleChangePage}
            />
          </Stack>
        </Box>
      </Box>

      {/* Contact */}

      <Popover
        id={idContact}
        open={openPopoverContact}
        onClose={handleClosePopoverContact}
        anchorEl={anchorE2}
        anchorOrigin={{
          vertical: "center",
          horizontal: "left",
        }}
        transformOrigin={{
          vertical: "top",
          horizontal: "left",
        }}
      >
        <Box sx={{ padding: "15px" }}>
          {contactList.map((contact, index) => {
            return (
              <Box
                key={index}
                sx={{
                  padding: "5px",
                  display: "flex",
                  gap: "20px",
                  justifyContent: "start",
                  alignItems: "center",
                }}
              >
                {contact.contactTypeLabel === "telephone" ? (
                  <CallIcon titleAccess="Phone" />
                ) : contact.contactTypeLabel === "email" ? (
                  <EmailIcon titleAccess="E-mail" />
                ) : (
                  <LanguageIcon titleAccess="WebSite" />
                )}
                <Box
                  sx={{
                    width: "15rem",
                    textOverflow: "ellipsis",
                    overflow: "hidden",
                  }}
                >
                  {contact.label}
                </Box>

                <CopyToClipboard text={contact.label}>
                  <IconButton color="inherit">
                    <Tooltip title="Copy">
                      <ContentCopyRoundedIcon sx={{ cursor: "pointer" }} />
                    </Tooltip>
                  </IconButton>
                </CopyToClipboard>
              </Box>
            );
          })}
        </Box>
      </Popover>

      {/* Filter */}
      <Popover
        id={id}
        open={openPopover}
        anchorEl={anchorEl}
        onClose={handleClosePopover}
        anchorOrigin={{
          vertical: "bottom",
          horizontal: "left",
        }}
      >
        <Box
          sx={{
            display: "flex",
            alignContent: "center",
            alignItems: "center",
            p: 2,
            gap: 2,
          }}
        >
          <Typography>Filter</Typography>
          <TextField
            type={typePopover}
            inputProps={{ maxLength: maxLegthPopover }}
            variant="outlined"
            placeholder={labelPopover}
            onChange={
              isNumber
                ? handleChangeNumberPopover
                : isNumber
                ? handleChangeNumberPopover
                : handleChangePopover
            }
            size="small"
            onKeyDown={keyPress}
          ></TextField>
          <Button variant="outlined" onClick={handleConfirmPopover}>
            Confirm
          </Button>
        </Box>
      </Popover>
    </Box>
  );
};

export default Vendor;
