import { requestHistoryRepository } from "../repositories/RequestHistoryRepository";

class RequestHistoryUseCases {  
  async listRequestHistory(filterList) {
    const response = await requestHistoryRepository.listRequestHistory(filterList);
    return response;
  }

  async getStockDetail(requestUUID) {
    const response = await requestHistoryRepository.getDetailingStock(
      requestUUID
    );
    return response;
  }

  async getStockHistoric(requestUUID) {
    const response = await requestHistoryRepository.getStockHistoric(
      requestUUID
    );
    return response;
  }

  async confirmRequest(uuid) {
    return await requestHistoryRepository.confirmRequest(uuid);
  }

  async deleteRequest(uuid) {
    return await requestHistoryRepository.deleteRequest(uuid);
  }

  async cancelRequest(uuid) {
    return await requestHistoryRepository.cancelRequest(uuid);
  }

  async deleteBoxRequest(stockTransferUUID, boxlistUUID){
    return await requestHistoryRepository.deleteBoxRequest(stockTransferUUID, boxlistUUID);
  }
}

export const requestHistoryUseCases = new RequestHistoryUseCases();
