import { useEffect, useState } from "react";
import {
  Box,
  Checkbox,
  IconButton,
  Paper,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Tooltip,
} from "@mui/material";
import { requestHistoryUseCases } from "../../usecases/RequestHistoryUseCases";
import DeleteIcon from "@mui/icons-material/Delete";
import Swal from "sweetalert2";

const columns = [
  {
    id: "box",
    label: "Box",
    width: "15%",
  },
  {
    id: "amount",
    label: "Amount",
    width: "10%",
  },
  {
    id: "packing",
    label: "Packing",
    width: "10%",
  },
  {
    id: "product",
    label: "Product",
    width: "40%",
  },
  {
    id: "color",
    label: "Color",
    width: "25%",
  },
];

const StockDetail = ({ stockUUID, stockTransfer }) => {
  const [detailingStock, setDetailingStock] = useState([]);
  const [loading, setLoading] = useState(false);
  const [change, setChange] = useState(false);
  const [stockUUIDList, setStockUUIDList] = useState(new Map());
  const [condition, setCondition] = useState(0);

  const handleSelectItemToDelete = (stockUUID, index) => {
    if (stockUUIDList.get(index) === stockUUID) {
      stockUUIDList.delete(index);
      setStockUUIDList(new Map(stockUUIDList));
    } else {
      setStockUUIDList(new Map(stockUUIDList).set(index, stockUUID));
    }
  };

  const deleteBoxRequest = () => {
    Swal.fire({
      title: "Delete receipt?",
      text: "You will delete this request!",
      icon: "warning",
      showCancelButton: true,
      confirmButtonColor: "#3085d6",
      cancelButtonColor: "#d33",
      confirmButtonText: "Confirm",
    }).then((result) => {
      if (result.isConfirmed) {
        submitDeleteRequest().then(() => setChange(!change));
      }
    });
  };

  const submitDeleteRequest = async () => {
    const response = await requestHistoryUseCases.deleteBoxRequest(
      stockTransfer?.uuid ?? "",
      Array.from(stockUUIDList.values())
    );
    return response;
  };

  const handleTimeOut = (response) => {
    setTimeout(() => {
      setCondition(response?.data?.stockTransfer?.condition ?? 0);
      setDetailingStock(response?.data?.stockTransfer?.boxes ?? []);
      setLoading(false);
    }, 200);
  };

  useEffect(() => {
    setLoading(true);
    const getDetailingStock = async () => {
      const response = await requestHistoryUseCases.getStockDetail(stockUUID);
      return response;
    };
    getDetailingStock().then((response) => handleTimeOut(response));
  }, [change]);

  return (
    <Paper sx={{ overflow: "hidden" }}>
      {loading ? (
        <Box
          sx={{
            width: "100%",
            justifyContent: "center",
            display: "flex",
            padding: "2%",
          }}
        >
          <Box className="loader" />
        </Box>
      ) : (
        <TableContainer component={Paper}>
          <Table stickyHeader sx={{ minWidth: "720px" }}>
            <TableHead>
              <TableRow>
                <TableCell sx={{ backgroundColor: "#ECF0F1" }} size="medium">
                  {stockUUIDList.size > 0 ? (
                    <Tooltip title="Delete box" placement="top">
                      <IconButton
                        onClick={() => deleteBoxRequest()}
                        size="small"
                        sx={{ width: '20px', height: '10px' }}
                      >
                        <DeleteIcon />
                      </IconButton>
                    </Tooltip>
                  ) : (
                    ""
                  )}
                </TableCell>
                {columns.map((column, index) => (
                  <TableCell
                    size="medium"
                    key={index}
                    sx={{
                      width: column.width,
                      fontWeight: "700",
                      backgroundColor: "#ECF0F1",
                    }}
                  >
                    {column.label}
                  </TableCell>
                ))}
              </TableRow>
            </TableHead>
            <TableBody>
              {detailingStock.map(
                (stock, index) =>
                  stock?.itens.map((item) => (
                    <TableRow key={index}>
                      <TableCell size={condition === 0 ? "medium" : "medium"}>
                        {condition === 0 ? (
                          <Tooltip title="Select" placement="top">
                            {/* <IconButton size="small"> */}
                            <Checkbox
                              onClick={() =>
                                handleSelectItemToDelete(
                                  stock?.uuid ?? "",
                                  stock?.uuid ?? ""
                                )
                              }
                              checked={stockUUIDList.has(stock.uuid)}
                              sx={{ p: 0 }}
                            />
                            {/* </IconButton> */}
                          </Tooltip>
                        ) : (
                          ""
                        )}
                      </TableCell>
                      <TableCell size={condition === 0 ? "small" : "medium"}>
                        {stock?.number ?? ""}
                      </TableCell>
                      <TableCell size={condition === 0 ? "small" : "medium"}>
                        {stock?.itens.length ?? ""}
                      </TableCell>
                      <TableCell size={condition === 0 ? "small" : "medium"}>
                        {stock?.packing?.comex ?? ""}
                      </TableCell>
                      <TableCell size={condition === 0 ? "small" : "medium"}>
                        {item?.variant?.product?.description ?? ""}
                      </TableCell>
                      <TableCell size={condition === 0 ? "small" : "medium"}>
                        {item?.variant?.color?.code ?? ""} -{" "}
                        {item?.variant?.color?.description ?? ""}
                      </TableCell>
                    </TableRow>
                  )) ?? ""
              )}
            </TableBody>
          </Table>
        </TableContainer>
      )}
    </Paper>
  );
};

export default StockDetail;
