//import AuthenticationRepository from "../../../infrastructure/repository/authentication/authentication_repository";
import AuthenticationRepository from "../repositories/authentication_repository";
import AuthenticationRules from "./authentication_rules";

class AuthenticationUseCase {
  /**
   * Log into the application
   * @param login Email or RA registered by the user.
   * @param password password.
   */
  async login(login, password) {
    const errors = [];

    const loginError = AuthenticationRules.loginIsInvalid(login);
    if (loginError) {
      errors.push(loginError);
    }

    const passwordError = AuthenticationRules.passwordIsInvalid(password);
    if (passwordError) {
      errors.push(passwordError);
    }

    if (errors.length) {
      throw errors;
    }

    return AuthenticationRepository.login(login, password);
  }

  async resetPassword(email) {
    const errors = [];

    const emailError = AuthenticationRules.emailIsInvalid(email);
    if (emailError) {
      errors.push(emailError);
    }

    if (errors.length) {
      throw errors;
    }

    await AuthenticationRepository.requestPasswordReset(email);
  }

  /**
   * This method logs out the current authenticated user.
   */
  async logout() {
    await AuthenticationRepository.logout();
  }

  async isUserLoggedIn() {
    return await AuthenticationRepository.isUserLoggedIn();
  }


}

export default new AuthenticationUseCase();
