import {
  Box,
  Button,
  Divider,
  FormControl,
  Grid,
  InputLabel,
  MenuItem,
  Modal,
  Popover,
  Select,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Typography,
} from "@mui/material";
import ShoppingBasketRoundedIcon from "@mui/icons-material/ShoppingBasketRounded";
import "./ModalProductsCart.css";
import ClearIcon from "@mui/icons-material/Clear";
import Swal from "sweetalert2";
import { warehouseRepository } from "../../warehouse/repositories/WarehouseRepositories";
import { stockUseCases } from "../usecases/StockUseCases";
import { useState } from "react";
import ProductionQuantityLimitsIcon from "@mui/icons-material/ProductionQuantityLimits";
import KeyboardArrowDownIcon from "@mui/icons-material/KeyboardArrowDown";
import { useEffect } from "react";

const ModalProductsCart = (props) => {
  const { isOpen, parentCallback } = props;
  const ITEM_HEIGHT = 60;
  const ITEM_PADDING_TOP = 10;
  const MenuProps = {
    PaperProps: {
      style: {
        maxHeight: ITEM_HEIGHT * 4.5 + ITEM_PADDING_TOP,
        width: 250,
      },
    },
  };

  const [open, setOpen] = useState(isOpen);
  const [loading, setLoading] = useState(false);
  const [update, setUpdate] = useState(true);
  const [warehouse, setWarehouse] = useState("");
  const [warehouses, setWarehouses] = useState([]);
  const [warehouseDestinyId, setWarehouseDestinyId] = useState(0);
  const [data, setData] = useState([]);
  const [error, setError] = useState([]);

  const [variants, setVariants] = useState();

  const [anchorE2, setAnchorE2] = useState(null);

  const [boxNumber, setBoxNumber] = useState(0);

  const Toast = Swal.mixin({
    toast: true,
    position: "top-end",
    showConfirmButton: false,
    timer: 3000,
    timerProgressBar: true,
    didOpen: (toast) => {
      toast.addEventListener("mouseenter", Swal.stopTimer);
      toast.addEventListener("mouseleave", Swal.resumeTimer);
    },
  });

  const handleClose = () => {
    parentCallback();
    setOpen(false);
  };

  function handleConfirmCart() {
    try {
      setLoading(true);
      const confirmCart = async () => {
        const response = await stockUseCases.confirmCartUseCase(
          data,
          warehouseDestinyId
        );
        return response;
      };
      confirmCart().then((response) => {        
        if (response instanceof Error) {
          setLoading(false)
          return Swal.fire({
            icon: "warning",
            confirmButtonText: "OK",
            text: response.message,
          });
        } else if(response?.data?.error !== null){
          setLoading(false)
          return Swal.fire({
            icon: "warning",
            title: "Error",
            text: response?.data?.error?.description ?? ''
          })
        } else {
          handleClose();
          setLoading(false);
          localStorage.removeItem("BOXES");
          localStorage.removeItem("WAREHOUSEORIGIN");
          return Toast.fire({
            icon: "success",
            text: "Successfully registered",
          });
        }
      });
    } catch (error) {
      if (error instanceof Error) {
        return Swal.fire({
          icon: "warning",
          confirmButtonText: "OK",
          text: error.message,
        });
      } else {
        return Swal.fire({
          icon: "error",
          confirmButtonText: "OK",
          text: `Error: ${error.description}`,
        });
      }
    }
  }

  const modalStyle = {
    position: "absolute",
    display: "flex",
    flexDirection: "column",
    top: "50%",
    left: "50%",
    transform: "translate(-50%, -50%)",
    width: "50%",
    maxHeight: "70%",
    border: "none",
    backgroundColor: "#ffffff",
    boxShadow: 24,
    borderRadius: "10px",
    p: 4,
  };

  useEffect(() => {
    try {
      setLoading(true);

      async function getItem() {
        return await stockUseCases.queryVolumeUseCases();
      }

      async function getWarehouses() {
        const response = await warehouseRepository.getWarehouses(true);
        return setWarehouses(response);
      }

      async function getWarehouseOrigin() {
        return stockUseCases.queryWarehouseOrigin();
      }

      getWarehouses();
      getItem().then((response) => {
        setData(response);
        timeOutSpinner();
        setLoading(false);
      });
      getWarehouseOrigin().then((response) => {
        setWarehouse(response?.description ?? "");
      });
    } catch (error) {
      return Swal.fire({
        icon: "error",
        text: error.data,
      });
    }
  }, [update]);

  function timeOutSpinner() {
    setLoading(true);
    setTimeout(() => {
      setLoading(false);
    }, 8000);
  }

  const handleDeleteItem = (evt, itemNumber) => {
    evt.preventDefault();
    Swal.fire({
      title: "Are you sure?",
      icon: "warning",
      showCancelButton: true,
      confirmButtonColor: "#032d307d",
      cancelButtonColor: "#8f948c61",
      confirmButtonText: "Remove",
    }).then((result) => {
      if (result.isConfirmed) {
        try {
          stockUseCases.deleteItemUseCases(itemNumber).then(() => {
            setUpdate(!update);
            return Swal.fire(
              "Removed!",
              "Your item has been removed.",
              "success"
            );
          });
        } catch (error) {
          return Swal.fire({
            icon: "error",
            text: error.message,
          });
        }
      }
    });
  };

  const handleRemoveAllBoxes = () => {
    Swal.fire({
      title: "Are you sure?",
      icon: "warning",
      showCancelButton: true,
      confirmButtonColor: "#032d307d",
      cancelButtonColor: "#8f948c61",
      confirmButtonText: "Remove",
    }).then((result) => {
      if (result.isConfirmed) {
        try {
          stockUseCases.deleteAllBoxes();
          setUpdate(!update);
          return Swal.fire(
            "Removed!",
            "All boxes have been removed.",
            "success"
          );
        } catch (error) {
          return Swal.fire({
            icon: "error",
            text: error.message,
          });
        }
      }
    });
  };

  const warehouseDestinyChange = (evt) => {
    setWarehouseDestinyId(evt.target.value);
    setError([]);
  };

  const openPopover = Boolean(anchorE2);

  const boxUUID = openPopover ? "simple-popover" : undefined;

  const handleShowVariants = (evt, boxNumber) => {
    evt.preventDefault();
    const getVariants = async () => {
      const response = await stockUseCases.getVariantsByBox(boxNumber);
      setVariants(response);
    };
    getVariants();
    setAnchorE2(evt.currentTarget);
    setBoxNumber(boxNumber);
  };
  const handleClosePopoverVariant = () => {
    setAnchorE2(null);
  };

  let contentList;

  if (data !== undefined && data.length > 0) {
    let firstBox = 0;
    contentList = data.map((key) => {
      if (key.barCode !== firstBox) {
        firstBox = key.barCode;
        return (
          <TableRow key={key.uuid}>
            <TableCell sx={{ p: 2 }}>{key.barCode}</TableCell>
            <TableCell
              sx={{ cursor: "pointer", p: 2 }}
              onClick={(evt) => handleShowVariants(evt, key.barCode)}
            >
              <Button sx={{ color: "#032d307d" }}>
                View products &nbsp;
                <KeyboardArrowDownIcon />
              </Button>
            </TableCell>
            <TableCell sx={{ p: 2 }} align="right">
              <Button
                onClick={(evt) => handleDeleteItem(evt, key.barCode)}
                sx={{ color: "#032d307d" }}
              >
                Remove this item &nbsp;
                <ClearIcon
                  sx={{ color: "#032d307d" }}
                  titleAccess="Remove item"
                />
              </Button>
            </TableCell>
          </TableRow>
        );
      }
    });
  } else {
    contentList = (
      <TableRow>
        <TableCell colSpan={4} sx={{ border: "none", textAlign: "center" }}>
          <Typography
            variant="body1"
            sx={{ marginTop: "1rem", marginBottom: "1rem" }}
          >
            Add items to your cart
          </Typography>
        </TableCell>
      </TableRow>
    );
  }

  return (
    <Modal
      open={open}
      onClose={handleClose}
      aria-labelledby="modal-modal-title"
      aria-describedby="modal-modal-description"
    >
      <Box sx={{ width: "100%" }}>
        <Grid sx={modalStyle} container spancing={2}>
          <Box
            sx={{
              display: "flex",
              flexDirection: "row",
              justifyContent: "space-between",
            }}
          >
            <Typography
              sx={{ fontSize: "1.5em", fontWeight: "700", color: "#363636" }}
              component="h2"
            >
              Cart
            </Typography>
            <ShoppingBasketRoundedIcon />
          </Box>
          <Divider />

          <Box
            sx={{
              marginTop: "2vh",
              marginBottom: "1vh",
              display: "flex",
              alignItems: "center",
              justifyContent: "space-between",
            }}
          >
            {loading ? (
              ""
            ) : (
              <Typography>
                {warehouse.trim() === ""
                  ? ""
                  : `Origin warehouse - ${warehouse}`}
              </Typography>
            )}
            <Button
              sx={{ color: "#032d307d" }}
              onClick={() => handleRemoveAllBoxes()}
              title="Remove all boxes"
            >
              Remove all boxes &nbsp;
              <ClearIcon sx={{ color: "#032d307d" }} />
            </Button>
          </Box>
          <TableContainer
            sx={{
              maxHeight: 400,
              "&::-webkit-scrollbar": {
                width: 5,
                height: 5,
              },
              "&::-webkit-scrollbar-track": {
                backgroundColor: "#e5e5e561",
              },
              "&::-webkit-scrollbar-thumb": {
                backgroundColor: "#032d307d",
                borderRadius: 2,
              },
            }}
          >
            <Table sx={{ minWidth: 500 }}>
              <TableHead>
                <TableRow>
                  <TableCell sx={{ p: 2 }}>Box</TableCell>
                  <TableCell sx={{ p: 2 }}>&nbsp;Products</TableCell>
                  <TableCell
                    align="right"
                    sx={{ color: "#032d307d", p: 2 }}
                  ></TableCell>
                </TableRow>
              </TableHead>
              <TableBody>{contentList}</TableBody>
            </Table>
          </TableContainer>
          <Popover
            id={boxUUID}
            open={openPopover}
            onClose={() => handleClosePopoverVariant()}
            anchorEl={anchorE2}
            anchorOrigin={{
              vertical: "center",
              horizontal: "left",
            }}
            transformOrigin={{
              vertical: "top",
              horizontal: "left",
            }}
          >
            <Box sx={{ padding: "15px" }}>
              <Box
                sx={{
                  display: "flex",
                  justifyContent: "space-between",
                  gap: 2,
                }}
              >
                <Typography fontWeight={"bold"}>Products</Typography>
                <ProductionQuantityLimitsIcon />
              </Box>
              <Divider sx={{ marginBottom: "10px", marginTop: "10px" }} />
              <TableContainer
                sx={{
                  maxHeight: "30vh",
                  "&::-webkit-scrollbar": {
                    width: 5,
                    height: 5,
                  },
                  "&::-webkit-scrollbar-track": {
                    backgroundColor: "#e5e5e561",
                  },
                  "&::-webkit-scrollbar-thumb": {
                    backgroundColor: "#032d307d",
                    borderRadius: 2,
                  },
                }}
              >
                <TableHead stickyHeader>
                  <TableRow>
                    <TableCell align="left" sx={{ p: 1 }}>
                      Product code
                    </TableCell>
                    <TableCell align="left" sx={{ p: 1 }}>
                      Product
                    </TableCell>
                    <TableCell align="left" sx={{ p: 1 }}>
                      Variant
                    </TableCell>
                    <TableCell align="left" sx={{ p: 1 }}>
                      Volume
                    </TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {variants !== undefined &&
                    variants.map((variant, index) => (
                      <TableRow key={index}>
                        <TableCell sx={{ p: 1 }}>
                          {variant?.product?.numericCode ?? ""}
                        </TableCell>
                        <TableCell sx={{ p: 1 }}>
                          {variant?.product?.description ?? ""}
                        </TableCell>
                        <TableCell sx={{ p: 1 }}>
                          {variant?.color?.code ?? ""} -
                          {variant?.color?.description ?? ""}
                        </TableCell>
                        <TableCell>{variant?.product?.volume ?? ""}</TableCell>
                      </TableRow>
                    ))}
                </TableBody>
              </TableContainer>
            </Box>
          </Popover>
          <Box
            sx={{
              display: "flex",
              flexDirection: "row",
              justifyContent: "space-between",
              marginTop: "2vh",
              alignItems: "center",
            }}
          >
            <FormControl
              variant="standard"
              sx={{ width: "40%", marginBottom: "1vh" }}
              {...(error.length !== 0 && { error })}
            >
              <InputLabel id="id-warehouse-form">
                Destination warehouse
              </InputLabel>
              <Select
                labelId="id-warehouse-form"
                label="warehouse"
                value={warehouseDestinyId}
                name="select-warehouse"
                onChange={warehouseDestinyChange}
                MenuProps={MenuProps}
              >
                <MenuItem value={0}>Select the destination warehouse</MenuItem>
                {warehouses.map((warehouse) => (
                  <MenuItem key={warehouse.id} value={warehouse.id}>
                    {warehouse.code} - {warehouse.description}
                  </MenuItem>
                ))}
              </Select>
            </FormControl>
            {!loading ? (
              <Box>
                <Button
                  onClick={() => handleClose()}
                  color="error"
                  variant="outlined"
                >
                  Close cart
                </Button>
                <Button
                  onClick={() => handleConfirmCart()}
                  variant="contained"
                  sx={{ marginLeft: 2 }}
                >
                  Confirm order
                </Button>
              </Box>
            ) : (
              <div className="loading"></div>
            )}
          </Box>
        </Grid>
      </Box>
    </Modal>
  );
};

export default ModalProductsCart;
