import {
  Button,
  Chip,
  Grid,
  MenuItem,
  Pagination,
  Paper,
  Popover,
  Select,
  Table,
  TableBody,
  TableCell,
  tableCellClasses,
  TableContainer,
  TableHead,
  TableRow,
  TableSortLabel,
  TextField,
  Tooltip,
  Typography,
} from "@mui/material";
import { Box, Stack } from "@mui/system";
import styled from "@emotion/styled";
import FilterListRoundedIcon from "@mui/icons-material/FilterListRounded";
import { useState, useEffect } from "react";
import { boxUseCase } from "../usecases/BoxUseCase";

const StyledTableCell = styled(TableCell)(({ theme }) => ({
  [`&.${tableCellClasses.head}`]: {
    backgroundColor: "#15191C",
    color: "white",
  },
  [`&.${tableCellClasses.body}`]: {
    fontSize: 14,
  },
}));

const StyledTableRow = styled(TableRow)(({ theme }) => ({
  "&:nth-of-type(odd)": {
    backgroundColor: "#f3f3f3",
  },
  "&:last-child td, &:last-child th": {
    border: 0,
  },
}));

const columns = [
  {
    value: "number",
    label: "Number",
    width: "4%",
    align: "left",
    isOrder: true,
    isFilter: true,
    isNumber: false,
    maxLength: 10,
    type: "number",
  },
  {
    value: "description",
    label: "Description",
    width: "30%",
    align: "left",
    isOrder: true,
    isFilter: true,
    isNumber: false,
    maxLength: 50,
    type: "string",
  },
  {
    value: "height",
    label: "Height (inch)",
    width: "10%",
    align: "left",
    isOrder: true,
    isFilter: false,
    isNumber: false,
    maxLength: 9,
    type: "number",
  },
  {
    value: "width",
    label: "Width (inch)",
    width: "10%",
    align: "left",
    isOrder: true,
    isFilter: false,
    isNumber: false,
    maxLength: 9,
    type: "number",
  },
  {
    value: "length",
    label: "Length (inch)",
    width: "10%",
    align: "left",
    isOrder: true,
    isFilter: false,
    isNumber: true,
    maxLength: 9,
    type: "number",
  },
  {
    value: "netWeight",
    label: "Net weight (lb)",
    width: "10%",
    align: "left",
    isOrder: true,
    isFilter: false,
    isNumber: true,
    maxLength: 9,
    type: "number",
  },
  {
    value: "grossWeight",
    label: "Gross weight (lb)",
    width: "10%",
    align: "left",
    isOrder: true,
    isFilter: false,
    isNumber: true,
    maxLength: 9,
    type: "number",
  },
  {
    value: "cubicMeters",
    label: "Cubic meters (m³)",
    width: "10%",
    align: "left",
    isOrder: true,
    isFilter: false,
    isNumber: true,
    maxLength: 9,
    type: "number",
  },
  {
    value: "vendorIdentifier",
    label: "Vendor",
    width: "10%",
    align: "left",
    isOrder: true,
    isFilter: true,
    isNumber: false,
    maxLength: 60,
    type: "String",
  },
];

const filtersDefault = {
  page: 1,
  rowsPerPage: 10,
  orderBy: "",
  sort: "asc",
  filters: [],
};

const popoverDefault = {
  label: "",
  column: "",
  type: "text",
  maxLength: 10,
  isNumber: false,
  value: "",
};

const BoxList = () => {
  const [boxList, setBoxList] = useState([]);
  const [filterList, setFilterList] = useState(filtersDefault);
  const [pageList, setPageList] = useState(0);

  const [anchorEl, setAnchorEl] = useState(null);
  const [popover, setPopover] = useState(popoverDefault);
  const [chipData, setChipData] = useState([]);

  const [loading, setLoading] = useState(false);

  const openPopover = Boolean(anchorEl);
  const id = openPopover ? "simple-popover" : undefined;

  /**
   * Arrow funciton to set order by filter
   * @param {String} value
   */
  const handleOrderBy = (value) => {
    setFilterList({
      ...filterList,
      ["orderBy"]: value,
      ["sort"]: filterList.sort === "asc" ? "desc" : "asc",
    });
  };
  /**
   * Arrow function to set the page filter
   * @param {Event} evt
   * @param {String} value
   */
  const handleChangePage = (evt, value) => {
    setFilterList({
      ...filterList,
      ["page"]: value,
      ["orderBy"]: "",
      ["sort"]: "asc",
    });
  };
  /**
   * Arrow function to set the rows per page filter
   * @param {Event} evt
   */
  const handleChangeRowsPerPage = (evt) => {
    setFilterList({
      ...filterList,
      ["rowsPerPage"]: evt.target.value,
      ["orderBy"]: "",
      ["sort"]: "asc",
    });
  };
  /**
   * Arrow function to close popover
   */
  const handleClosePopover = () => {
    setAnchorEl(null);
  };
  /**
   * Arrow function to open and set the default values popover
   */
  const handleClickPopover = (
    event,
    label,
    column,
    type,
    maxLength,
    number
  ) => {
    setAnchorEl(event);
    setPopover({
      label: label,
      column: column,
      type: type,
      maxLength: maxLength,
      isNumber: number,
    });
  };
  /**
   * Arrow function to confirm and set the filters to list
   */
  const handleConfirmPopover = () => {
    setAnchorEl(null);
    setChipData((chips) =>
      chips.filter((chip) => chip.labelFilter !== popover.label)
    );
    setChipData((prevState) => [
      ...prevState,
      {
        labelFilter: popover.label,
        columnPopover: popover.column,
        valueFilter: popover.value,
      },
    ]);
    setFilterList({
      ...filterList,
      ["page"]: 1,
      ["filters"]: [
        {
          labelFilter: popover.label,
          columnPopover: popover.column,
          valueFilter: popover.value,
        },
      ],
    });
  };
  /**
   * Arrow function to delete the chipData list and re-set the filter to reload the page
   * @param {[]} chipToDelete
   */
  const handleDeleteChip = (chipToDelete) => () => {
    setChipData((chips) =>
      chips.filter((chip) => chip.labelFilter !== chipToDelete.labelFilter)
    );
    setFilterList({
      ...filterList,
      ["filters"]: chipData.filter(
        (chip) => chip.labelFilter !== chipToDelete.labelFilter
      ),
    });
  };
  /**
   * Arrow function to reset the filters
   */
  const handClickResetList = () => {
    setChipData([]);
    setFilterList(filtersDefault);
  };
  /**
   * Arrow function to set time out to loader from page
   */
  const handleTimeOut = (response) => {
    setTimeout(() => {
      setBoxList(response?.data?.boxType ?? []);
      setPageList(response?.data?.numberPages ?? 0);
      // setLoading(false);
    }, 0);
  };
  useEffect(() => {
    document.title = 'Lince Tech Micro ERP | Box type listing'
    // setLoading(true);
    const getBoxes = async () => {
      const response = await boxUseCase.getBoxes(filterList);
      return response;
    };
    getBoxes().then((response) => handleTimeOut(response));
  }, [filterList]);

  return (
    <Box
      sx={{
        display: "flex",
        marginLeft: "3rem",
        marginTop: "3rem",
        marginRight: "2rem",
      }}
    >
      <Box sx={{ width: "100%" }}>
        <Typography sx={{ fontSize: "26pt", fontWeight: "800" }}>
          Box type
        </Typography>
        <Box
          sx={{
            minWidth: "100%",
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
            marginTop: "0.5rem",
          }}
        >
          <Box sx={{ display: "flex" }}>
            <Box
              sx={{
                display: "flex",
                justifyContent: "center",
                flexWrap: "nowrap",
                listStyle: "none",
                p: 0,
                m: 0,
                border: "none",
                height: "4rem",
                alignItems: "center",
              }}
            >
              {chipData.map((data) => {
                return (
                  <Tooltip title={data.labelFilter} placement="bottom" arrow>
                    <Chip
                      sx={{
                        textOverFlow: "ellipsis",
                        overFlow: "hidden",
                        whiteSpace: "nowrap",
                        maxWidth: "145px",
                        marginRight: "1rem",
                      }}
                      color="primary"
                      variant="outlined"
                      label={data.valueFilter}
                      onDelete={handleDeleteChip(data)}
                    />
                  </Tooltip>
                );
              })}
            </Box>
            {chipData.length === 0 ? (
              <></>
            ) : (
              <Button onClick={handClickResetList}>Clear All</Button>
            )}
          </Box>
        </Box>

        <Paper sx={{ width: "100%", overflow: "hidden", marginTop: "0.5rem" }}>
          {loading ? (
            <Box
              sx={{
                width: "100%",
                justifyContent: "center",
                display: "flex",
                padding: "2%",
              }}
            >
              <Box className="loader" />
            </Box>
          ) : (
            <TableContainer sx={{ maxHeight: "80vh" }}>
              <Table
                stickyHeader
                aria-label="sticky table"
                sx={{ minWidth: "1200px" }}
              >
                <TableHead>
                  <StyledTableRow>
                    {columns.map((key, index) => (
                      <StyledTableCell
                        key={index}
                        align={key.align}
                        width={key.width}
                      >
                        <Grid
                          container
                          justifyContent={"space-between"}
                          flexWrap={"nowrap"}
                          alignItems={"center"}
                        >
                          {key.isOrder === true ? (
                            <TableSortLabel
                              sx={{
                                "&.MuiTableSortLabel-root": {
                                  color: "white",
                                },
                                "&.MuiTableSortLabel-root:hover": {
                                  color: "white",
                                },
                                "&.Mui-active": {
                                  color: "white",
                                },
                                "& .MuiTableSortLabel-icon": {
                                  color: "white !important",
                                },
                              }}
                              active={filterList.orderBy === key.value}
                              direction={filterList.sort}
                              onClick={() => handleOrderBy(key.value)}
                            >
                              {key.label}
                            </TableSortLabel>
                          ) : (
                            <>{key.label}</>
                          )}
                          {key.isFilter === true && (
                            <FilterListRoundedIcon
                              variant="contained"
                              onClick={(evt) =>
                                handleClickPopover(
                                  evt.currentTarget,
                                  key.label,
                                  key.value,
                                  key.type,
                                  key.maxLength,
                                  key.isNumber
                                )
                              }
                              sx={{
                                width: "18px",
                                justifySelf: "end",
                                cursor: "pointer",
                              }}
                            />
                          )}
                        </Grid>
                      </StyledTableCell>
                    ))}
                  </StyledTableRow>
                </TableHead>
                <TableBody>
                  {boxList.map((box, index) => {
                    return (
                      <StyledTableRow key={index}>
                        <StyledTableCell>{box?.number ?? ""}</StyledTableCell>
                        <StyledTableCell>
                          {box?.description ?? ""}
                        </StyledTableCell>
                        <StyledTableCell>{new Intl.NumberFormat('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(box?.height ?? "")}</StyledTableCell>
                        <StyledTableCell>{new Intl.NumberFormat('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(box?.width ?? "")}</StyledTableCell>
                        <StyledTableCell>{new Intl.NumberFormat('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(box?.height ?? box?.length ?? "")}</StyledTableCell>
                        <StyledTableCell>
                          {box?.netWeight ?? ""}
                        </StyledTableCell>
                        <StyledTableCell>
                          {box?.grossWeight ?? ""}
                        </StyledTableCell>
                        <StyledTableCell>
                          {box?.cubicMeters ?? ""}
                        </StyledTableCell>
                        <StyledTableCell>
                          {box?.vendorIdentifier ?? ""}
                        </StyledTableCell>
                      </StyledTableRow>
                    );
                  })}
                </TableBody>
              </Table>
            </TableContainer>
          )}
        </Paper>
        <Box
          display={"flex"}
          justifyContent={"flex-end"}
          sx={{ marginTop: "2vh", alignItems: "center", gap: "1vw" }}
        >
          <Typography sx={{ align: "center", fontSize: "11pt" }}>
            Rows Per Page
          </Typography>

          <Select
            sx={{ height: "4vh", align: "center" }}
            autoWidth
            value={filterList.rowsPerPage}
            onChange={handleChangeRowsPerPage}
          >
            <MenuItem value={5}>5</MenuItem>
            <MenuItem value={10}>10</MenuItem>
            <MenuItem value={15}>15</MenuItem>
          </Select>

          <Stack spacing={2}>
            <Pagination
              count={pageList}
              page={filterList.page}
              onChange={handleChangePage}
            />
          </Stack>
        </Box>

        <Popover
          id={id}
          open={openPopover}
          anchorEl={anchorEl}
          onClose={handleClosePopover}
          anchorOrigin={{
            vertical: "bottom",
            horizontal: "left",
          }}
        >
          <Box
            sx={{
              display: "flex",
              alignContent: "center",
              alignItems: "center",
              p: 2,
              gap: 2,
            }}
          >
            <Typography>Filter</Typography>
            <TextField
              type={popover.type}
              inputProps={{ maxLength: popover.maxLength }}
              variant="outlined"
              placeholder={popover.label}
              size="small"
              onKeyDown={(evt) =>
                evt.keyCode === 13 ? handleConfirmPopover() : ""
              }
              onChange={(evt) => {
                if (popover.type === "number") {
                  evt.target.value = evt.target.value.replace(/[^0-9,]/g, "");
                }
                setPopover({
                  ...popover,
                  ["value"]: evt.target.value,
                });
              }}
            ></TextField>
            <Button variant="outlined" onClick={handleConfirmPopover}>
              Confirm
            </Button>
          </Box>
        </Popover>
      </Box>
    </Box>
  );
};

export default BoxList;
