import { PagedWarehouses } from "../entities/entities";
import http from "./../../../HttpHelper";

class WarehouseRepository {
  /**
   * @param page {int}
   * @param rowsPerPage {int}
   * @param orderBy {string}
   * @param situation {string}
   * @param sort {string}
   * @param chipData {string}
   * @returns {Promise<PagedWarehouses>}
   */

  async listWarehouses(page, rowsPerPage, orderBy, situation, sort, chipData) {
    try {
      const filters = `${
        chipData.size === 0
          ? ""
          : chipData.map(
              (data) =>
                "&filter=(" + data.columnPopover + ":" + data.valueFilter + ")"
            )
      }`;

      const response = await http.get(
        `/warehouse?page=${page}&size=${rowsPerPage}&orderBy=${orderBy}&sortBy=${sort}&filter=(statusCode:${situation})${
          filters === "" ? "" : filters.replaceAll(",", "")
        }`
      );

      // return response
      return new PagedWarehouses(
        response.data.warehouse,
        response.data.numberPages
      );
    } catch (error) {
      console.log(`error: ${error}`);
    }
  }

  async postWarehouse(warehouse) {    
    try {
      const response =  await http.post("/warehouse", {
        uuid: `${warehouse.uuid === null ? "" : warehouse.uuid}`,
        code: `${warehouse.code}`,
        description: `${warehouse.description}`,
        address: `${warehouse.address}`,
        email: `${warehouse.email}`,
        phone: `${warehouse.phone}`,
        statusCode: `${warehouse.situation}`,
        maxCapacity: `${warehouse.capacity}`,
        separationIndicator: `${warehouse.separation}`,
      });
      return response;
    } catch (error) {
      return error;
    }
  }

  async getWarehouses(separation) {
    try {
      let url;
      if (separation !== undefined && separation !== null) {
        url = `/warehouse?filter=(statusCode:0)&filter=(separationIndicator:${separation})`;
      } else {
        url = `/warehouse?filter=(statusCode:0)`;
      }

      const response = await http.get(url);
      return response.data.warehouse;
    } catch (error) {
      return error;
    }
  }

  /**
   * @param warehousesId {Number}
   * @returns {Object}
   */
  async getInfoWarehouse(warehousesId) {
    try {
      const response = await http.get(
        `/warehouse?filter=(code:${warehousesId})`
      );
      console.log(response)
      return response.data.warehouse;
    } catch (error) {
      return error.response;
    }
  }
}

export const warehouseRepository = new WarehouseRepository();
