export class User {
  /**
   * @param uuid {string}
   * @param name {string}
   * @param email {string}
   * @param userType {UserType}
   * @param authenticationRecord {string}
   * @param contact {string}
   * @param isActive {string}
   * @param password {string}
   * */
  constructor(uuid, name, email, type, authenticationRecord, phone, situation, password) {
    this.uuid = uuid;
    this.name = name;
    this.email = email;
    this.type = type;
    this.authenticationRecord = authenticationRecord;
    this.phone = phone;
    this.situation = situation;
    this.password = password;
  }
}

export class UserType {
  /**
   * @param uuid {string} is the identifier of this user type
   * @param label {string} is the human-readable name/label of this user type
   */
  constructor(uuid, label) {
    this.uuid = uuid;
    this.label = label;
  }
}