import {
  Box,
  FormControl,
  InputLabel,
  MenuItem,
  Select,
  TextField,
} from "@mui/material";
import { useEffect } from "react";
import { useState } from "react";
import ReactInputMask from "react-input-mask";
import { vendorUseCases } from "../../usecases/VendorUseCases";
import ContactTypesOptions from "./ContactType";

const Contact = ({
  key,
  index,
  initialLabel,
  initialType,
  setVendorContact,
  error
}) => {
  const [contactType, setContactType] = useState(initialType);
  const [contactTypeOption, setContactTypeOption] = useState([]);

  const [contact, setContact] = useState(
    <ContactTypesOptions
      key={index}
      index={index}
      initialLabel={initialLabel}
      initialType={initialType}
      setVendorContact={setVendorContact}
      error={error}
    />
  );
  const [change, setChange] = useState(0)

  const handleChangeContactType = (evt) => {
    evt.preventDefault();
    const { value } = evt.target;
    setContact(
      <ContactTypesOptions
        key={index}
        index={index}
        initialLabel={initialLabel}
        initialType={value}
        setVendorContact={setVendorContact}
        error={error}
      />
    );
    setContactType(value);
    setChange(1)
  };

  useEffect(() => {
    const getContactType = async () => {
      const response = await vendorUseCases.getVendorContactType();      
      setContactTypeOption(response.data);
    };
    getContactType();
  }, []);

  return (
    <Box
      sx={{
        marginTop: "1rem",
        width: "100%",
        display: "grid",
        gridGap: "1rem",
        gridTemplateColumns:
          "repeat(auto-fit, minmax(150px, 0.3fr) minmax(300px, 1fr))",
      }}
    >
      <FormControl variant="standard" required={index === 0 ? true : false}>
        <InputLabel id="id-contact-type-form-vendor">Contact type</InputLabel>
        <Select
          labelId="id-contact-type-form-vendor"
          label="Contact Type"
          name="contact"
          value={contactType === "" ? initialType : contactType}
          onChange={(evt) => handleChangeContactType(evt)}
        >
          {contactTypeOption.map((item, index) => (
            <MenuItem
              key={index}
              value={item.label}
              sx={{
                justifyContent: "space-between",
                alignItems: "center",
              }}
            >
              {item.label === "email"
                ? item.label[0].toUpperCase() + "-" + item.label.substring(1)
                : item.label === "telephone"
                ? "Phone"
                : item.label[0].toUpperCase() + item.label.substring(1)}
            </MenuItem>
          ))}
        </Select>
      </FormControl>
      {change === 0 ? (
        <ContactTypesOptions
          key={index}
          index={index}
          initialLabel={initialLabel}
          initialType={initialType}
          setVendorContact={setVendorContact}
          error={error}
        />
      ) : (
        contact
      )}
    </Box>
  );
};

export default Contact;
