import {
  Button,
  Divider,
  FormControl,
  Grid,
  InputLabel,
  MenuItem,
  Modal,
  Select,
  TextField,
  Typography,
} from "@mui/material";
import { Box } from "@mui/system";
import { DateTimePicker, LocalizationProvider } from "@mui/x-date-pickers";
import React, { useEffect } from "react";
import { AdapterDayjs } from "@mui/x-date-pickers/AdapterDayjs";
import { packingUseCases } from "../../packing/usecases/PackingUseCases";
import Swal from "sweetalert2";
import { warehouseRepository } from "../../warehouse/repositories/WarehouseRepositories";

const ConfirmationPackingModal = ({
  packingCode,
  isOpen,
  packingId,
  parentCallback,
}) => {
  const dayjs = require("dayjs");

  const [open, setOpen] = React.useState(isOpen);
  const [date, setDate] = React.useState(dayjs());
  const [warehouseId, setWarehouseId] = React.useState(0);
  const [warehouse, setWarehouse] = React.useState([]);
  const [error, setError] = React.useState([]);
  const [loading, setLoading] = React.useState(false);

  const Toast = Swal.mixin({
    toast: true,
    position: "top-end",
    showConfirmButton: false,
    timer: 3000,
    timerProgressBar: true,
    didOpen: (toast) => {
      toast.addEventListener("mouseenter", Swal.stopTimer);
      toast.addEventListener("mouseleave", Swal.resumeTimer);
    },
  });

  function timeOutSpinner() {
    setLoading(true);
    setTimeout(() => {
      setLoading(false);
      parentCallback(true);
      handleClose();
    }, 100);
  }

  const confirmPacking = async (packing) => {
    return await packingUseCases.setConfirmPacking(packing);
  };

  async function handleRegister(packingId, warehouseId, date) {
    const packing = {
      packingId,
      warehouseId,
      date,
    };

    try {
      setLoading(true);
      confirmPacking(packing).then((response) => {                
        console.log(response)
        if (response instanceof Map) {
          setLoading(false)
          const errors = response.values();          
          setError(errors);
          return Swal.fire({
            icon: "warning",
            confirmButtonText: "OK",
            text: errors.next().value,
          });
        }
        timeOutSpinner();        
        return Toast.fire({
          icon: "success",
          text: "Successfully registered",
        });
      });      
    } catch (error) {
      setLoading(false)
      return Swal.fire({
        icon: "error",
        confirmButtonText: "OK",
        text: `Error: ${error.error} - Status code: ${error.status}`,
      });
    }
  }

  const handleDateChange = (value) => {
    setDate(value);
  };

  useEffect(() => {
    async function getWarehouses() {
      const response = await warehouseRepository.getWarehouses();
      return setWarehouse(response);
    }

    getWarehouses();
  }, []);

  const modalStyle = {
    position: "absolute",
    display: "flex",
    flexDirection: "column",
    top: "50%",
    left: "50%",
    transform: "translate(-50%, -50%)",
    width: "60vw",
    height: "35vh",
    border: "none",
    backgroundColor: "#ffffff",
    boxShadow: 24,
    borderRadius: "10px",
    p: 4,
  };

  const handleClose = () => {
    setOpen(false);
  };

  const ITEM_HEIGHT = 60;
  const ITEM_PADDING_TOP = 10;
  const MenuProps = {
    PaperProps: {
      style: {
        maxHeight: ITEM_HEIGHT * 4.5 + ITEM_PADDING_TOP,
        width: 250,
      },
    },
  };

  return (
    <div>
      <Modal
        open={open}
        onClose={handleClose}
        aria-labelledby="modal-modal-title"
        aria-describedby="modal-modal-description"
      >
        <Box sx={{ width: "100%" }}>
          <Box sx={modalStyle} spancing={2}>
            <Typography
              sx={{ fontSize: "1.5em", fontWeight: "700", color: "#363636" }}
              component="h2"
            >
              Confirm packing
            </Typography>
            <Divider />
            <Typography
              sx={{
                fontSize: "1em",
                fontWeight: "700",
                color: "#363636",
                marginTop: "2vh",
                marginLeft: "0.8vw",
              }}
              component="h1"
            >
              Packing code: {packingCode}
            </Typography>
            <Box
              style={{
                display: "flex",
                width: "100%",
                justifyContent: "space-between",
                alignItems: "center",
              }}
            >
              <FormControl
                variant="standard"
                sx={{ m: 2, width: "70%" }}
                {...(error.length !== 0 && { error })}
              >
                <InputLabel id="id-warehouse-form">Warehouse</InputLabel>
                <Select
                  labelId="id-warehouse-form"
                  label="warehouse"
                  value={warehouseId}
                  name="select-warehouse"
                  onChange={(evt) => {
                    setWarehouseId(evt.target.value);
                    setError([]);
                  }}
                  MenuProps={MenuProps}
                >
                  <MenuItem value={0}>Select a warehouse</MenuItem>
                  {warehouse.map((warehouse) => (
                    <MenuItem key={warehouse.id} value={warehouse.id}>
                      {warehouse.code} - {warehouse.description}
                    </MenuItem>
                  ))}
                </Select>
              </FormControl>
              <LocalizationProvider dateAdapter={AdapterDayjs}>
                <DateTimePicker
                  label="Receipt date"
                  inputFormat="MM/DD/YYYY HH:mm"
                  value={date}
                  onChange={handleDateChange}
                  renderInput={(params) => (
                    <TextField {...params} variant="standard" sx={{ m: 2 }} />
                  )}
                />
              </LocalizationProvider>
            </Box>
            {loading ? (
              <Box
                sx={{
                  width: "95%",
                  display: "flex",
                  justifyContent: "flex-end",
                  flexWrap: "nowrap",
                  marginTop: "3%",
                }}
              >
                <div className="loading" sx="height: 20px; width: 20px"></div>
              </Box>
            ) : (
              <Box
                sx={{
                  width: "100%",
                  display: "flex",
                  justifyContent: "flex-end",
                  flexWrap: "nowrap",
                  marginTop: "3%",
                }}
              >
                <Button
                  variant="contained"
                  sx={{ m: 1, minWidth: "7vw", height: "4vh" }}
                  onClick={() => {                    
                    handleRegister(
                      packingId,
                      warehouseId,
                      date.format("YYYY-MM-DD HH:mm:ss")
                    );
                  }}
                >
                  Confirm
                </Button>
                <Button
                  variant="outlined"
                  sx={{ m: 1, minWidth: "7vw", height: "4vh" }}
                  onClick={() => handleClose()}
                  color="error"
                >
                  Cancel
                </Button>
              </Box>
            )}
          </Box>
        </Box>
      </Modal>
    </div>
  );
};

export default ConfirmationPackingModal;
