import { useEffect, useState } from 'react';
import { packingUseCases } from '../usecases/PackingUseCases';

import Paper from '@mui/material/Paper';
import Table from '@mui/material/Table';
import TableBody from '@mui/material/TableBody';
import TableCell from '@mui/material/TableCell';
import TableContainer from '@mui/material/TableContainer';
import TableHead from '@mui/material/TableHead';
import TablePagination from '@mui/material/TablePagination';
import TableRow from '@mui/material/TableRow';

import MenuItem from "@mui/material/MenuItem";
import Pagination from "@mui/material/Pagination";
import Stack from "@mui/material/Stack";
import Box from "@mui/material/Box";
import Typography from "@mui/material/Typography";
import Select from "@mui/material/Select";
import "./LoadingPacking.css"

const columns = [
  { id: 'ARTICLE', label: 'ARTICLE', minWidth: 170 },
  { id: 'TOTALGROSSWEIGHT', label: 'TOTAL GROSS WEIGHT (lb)', minWidth: 100 },
  {
    id: 'TOTALNETWEIGHT',
    label: 'TOTAL NET WEIGHT (lb)',
    minWidth: 70,
    // align: 'right',
    // format: (value) => value.toLocaleString('en-US'),
  },
  {
    id: 'BOXES',
    label: 'BOXES',
    minWidth: 70,
    // align: 'right',
    // format: (value) => value.toLocaleString('en-US'),
  },
  {
    id: 'QUANTITY',
    label: 'QUANTITY',
    minWidth: 70,
    // align: 'right',
    // format: (value) => value.toFixed(2),
  },
  {
    id: 'CUBICMETE',
    label: 'CUBIC METRE',
    minWidth: 70,
    // align: 'right',
    // format: (value) => value.toFixed(2),
  },
];


// function createData(BOXNO, GROSS, WEIGHT, NETWEIGHT, QUANTITYUNIT, ARTICLE, COLOR, LOT) {
//   return { BOXNO, GROSS, WEIGHT, NETWEIGHT, QUANTITYUNIT, ARTICLE, COLOR, LOT };
// }

// const rows = [
//   createData(122, 12, 1324171354, 3287263,121,121,1211,121),
// ];

export default function Products(props) {

  const [pageList, setPageList] = useState(1);
  const [page, setPage] = useState(1);
  const [orderBy, setOrderBy] = useState("");
  const [sort, setSort] = useState("asc");
  const [rowsPerPage, setRowsPerPage] = useState(10);
  const [detailingSummary, setDetailingSummary] = useState([])
  const [loading, setLoading] = useState(true)

  /**
   * - *English* Function to pagination
   * - *Português* Função para paginação
   * - @param event
   */
  const handleChangeRowsPerPage = (event) => {
    setRowsPerPage(+event.target.value);
    setPage(1);
    setOrderBy("");
    setSort("asc");
  };

  /**
   * - *English* Function to pagination
   * - *Português* Função para paginação
   * - @param event @param value
   */
  const handleChangePage = (event, value) => {
    setPage(value);
    setOrderBy("");
    setSort("asc");
  };


  useEffect(() => {
    const getDetailingPackingSummary = async () => {
      const detailingPackingSummary = await packingUseCases.detailingPackingSummary(props.packingId, page, rowsPerPage, orderBy, sort);
      setDetailingSummary(detailingPackingSummary.packings);
      setPageList(detailingPackingSummary.numberPages);
    }
    getDetailingPackingSummary()
      .then(() => {
        timeOutSpinner()
        setLoading(false)
      })
  }, [page, rowsPerPage, orderBy, sort])

  function timeOutSpinner() {
    setLoading(true);
    setTimeout(() => {
      setLoading(false);
    }, 8000);
  }

  return (
    <>
      <Paper sx={{ width: '100%', overflow: 'hidden' }}>
        <TableContainer>
          <Table stickyHeader aria-label="sticky table">
            <TableHead>
              <TableRow>
                {columns.map((column) => (
                  <TableCell
                    key={column.id}
                    align={column.align}
                    style={{ minWidth: column.minWidth, fontWeight: "700", backgroundColor: "#ECF0F1" }}
                  >
                    {column.label}
                  </TableCell>
                ))}
              </TableRow>
            </TableHead>
            <TableBody>
              {detailingSummary
                .map((key, index) => (
                  <TableRow hover role="checkbox" tabIndex={-1} key={index}>
                    <TableCell align={key.align}>{key.variant.product.description}</TableCell >
                    <TableCell align={key.align}>{new Intl.NumberFormat('en-US', { style: 'decimal', unit: 'pound', minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(key.grossWeight)}</TableCell>
                    <TableCell align={key.align}>{new Intl.NumberFormat('en-US', { style: 'decimal', unit: 'pound', minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(key.netWeight)}</TableCell>
                    <TableCell >{key.variant.boxQuantity}</TableCell>
                    <TableCell >{key.quantity}</TableCell>
                    <TableCell >{new Intl.NumberFormat('en-US', { minimumFractionDigits: 3, maximumFractionDigits: 3 }).format(key.cubeMeter)}</TableCell>
                  </TableRow>
                ))}
            </TableBody>
          </Table>
        </TableContainer>
        {loading ? <Box sx={{ width: '100%', height: '100%', display: 'flex', justifyContent: 'center', padding: '10%' }}><div className="loading-packing"></div></Box> : <></>}
        {/* <TablePagination
          rowsPerPageOptions={[10, 25, 100]}
          component="div"
          count={detailingByColor.length}
          rowsPerPage={rowsPerPage}
          page={page}
          onPageChange={handleChangePage}
          onRowsPerPageChange={handleChangeRowsPerPage}
        /> */}
      </Paper>
      <Box
        display={"flex"}
        justifyContent={"end"}
        justifyItems={"center"}
        sx={{ marginTop: "10px", alignItems: "center", gap: "15px" }}
      >
        <Typography sx={{ align: "center", fontSize: "11pt" }}>
          Rows Per Page
        </Typography>
        <Select
          sx={{ height: "35px" }}
          labelId="demo-simple-select-label"
          id="demo-simple-select"
          autoWidth
          value={rowsPerPage}
          label="Rows"
          onChange={handleChangeRowsPerPage}
        >
          <MenuItem value={5}>5</MenuItem>
          <MenuItem value={10}>10</MenuItem>
          <MenuItem value={15}>15</MenuItem>
        </Select>

        <Stack spacing={2}>
          <Pagination
            count={pageList}
            page={page}
            onChange={handleChangePage}
          />
        </Stack>
      </Box>
    </>
  )
}