import { productDetailRepository } from "../repositories/ProducDetailRepository";

class ProductDetailUseCase {
  /**
   *
   * @param code {int}
   */
  async getProductDetail(code) {
    const response = await productDetailRepository.getProductDetail(
      code
    );
    return response;
  }

  async getVariants(code, page, rowsPerPage) {
    const response = await productDetailRepository.getVariant(
      code, page, rowsPerPage
    );
    return response;
  }

  async postProductInstruction(uuid, instructions, technicalDescription) {    
    const response = await productDetailRepository.postProductInstruction(
      uuid, instructions, technicalDescription
    );
    return response;
  }

}

export const productDetailUseCase = new ProductDetailUseCase();
