import {
  Box,
  Button,
  FormControl,
  InputLabel,
  MenuItem,
  Modal,
  Select,
  TextField,
  Typography,
} from "@mui/material";
import { useEffect, useState } from "react";
import AddBusinessIcon from "@mui/icons-material/AddBusiness";
import { Vendor } from "../entities/Vendor";
import { vendorUseCases } from "../usecases/VendorUseCases";
import Swal from "sweetalert2";
import Contact from "./Contact/Contact";

const vendorRegisterModalStyle = {
  position: "absolute",
  top: "50%",
  left: "50%",
  transform: "translate(-50%, -50%)",
  minWidth: "60%",
  backgroundColor: "#ffffff",
  borderRadius: "10px",
  boxShadow: 24,
  p: 4,
  display: "flex",
  flexDirection: "row",
  overflow: "hidden",
  outline: "none",
  flexWrap: "wrap",
};

const Toast = Swal.mixin({
  toast: true,
  position: "top-end",
  showConfirmButton: false,
  timer: 3000,
  timerProgressBar: true,
  didOpen: (toast) => {
    toast.addEventListener("mouseenter", Swal.stopTimer);
    toast.addEventListener("mouseleave", Swal.resumeTimer);
  },
});

const vendorSituation = [
  {
    label: "Active",
    value: true,
  },
  {
    label: "Inative",
    value: false,
  },
];

const initialContact = [
  {
    contactTypeLabel: "",
    label: "",
  },
  {
    contactTypeLabel: "",
    label: "",
  },
  {
    contactTypeLabel: "",
    label: "",
  },
];

const ModalVendor = ({ vendorUUID, isOpen, parentCallback }) => {
  const [open, setOpen] = useState(isOpen);
  const [vendor, setVendor] = useState(new Vendor("", "", true, "", [], ""));
  const [error, setError] = useState([]);
  const [contact, setContact] = useState(initialContact);
  const [loading, setLoading] = useState(false);

  const handleCloseModal = () => {
    setOpen(!open);
  };

  const handleOnChange = (evt) => {
    const { name, value } = evt.target;
    setVendor({
      ...vendor,
      [name]: value,
    });
  };

  useEffect(() => {
    if (vendorUUID !== undefined) {
      const getVendor = async () => {
        const response = await vendorUseCases.getVendorByIdentifier(vendorUUID);
        return response;
      };
      getVendor().then((response) => {
        setVendor(
          new Vendor(
            response.data.uuid,
            response.data.identifier,
            response.data.isActive,
            response.data.name,
            response.data.contact,
            response.data.address
          )
        );
        setContact(response.data.contact);
      });
    }
  }, []);

  const setVendorContact = (value) => {
    initialContact.map((item, index) =>
      index === value.index
        ? (vendor.contact[index] = {
            contactTypeLabel: value.contactType,
            label: value.label,
          })
        : vendor.contact.length > index - 1
        ? {
            contactTypeLabel: "",
            label: "",
          }
        : {
            contactTypeLabel: vendor.contact[index].contactType,
            label: vendor.contact[index].label,
          }
    );
  };

  function timeOutLoader() {
    setLoading(true);
    setTimeout(() => {
      setLoading(false);
      handleCloseModal();
    }, 500);
  }

  const handleRegisterVendor = async () => {
    setLoading(true);
    const response = await vendorUseCases.postVendor(vendor);
    if (response.size) {
      setLoading(false);
      const error = response.values();
      const errorKey = response.keys();
      setError(errorKey.next().value.key);      
      return Swal.fire({
        icon: "warning",
        confirmButtonText: "OK",
        text: error.next().value,
      });
    }
    if (!response.status) {
      setLoading(false);
      return Swal.fire({
        icon: "error",
        confirmButtonText: "OK",
        text: "Connection error",
      });
    }
    if (response.data.error !== null) {
      setLoading(false);
      return Swal.fire({
        icon: "error",
        confirmButtonText: "OK",
        text: response.data.error.description,
      });
    } else {
      parentCallback(true);
      timeOutLoader();
      return Toast.fire({
        icon: "success",
        text: "Successfully registered",
      });
    }
  };

  return (
    <Modal open={open} onClose={handleCloseModal}>
      <Box sx={vendorRegisterModalStyle}>
        <Box
          sx={{
            display: "flex",
            justifyContent: "space-between",
            width: "100%",
          }}
        >
          <Typography
            sx={{ fontSize: "1.5rem", fontWeight: "700", color: "#363636" }}
            component="h2"
          >
            {vendorUUID !== undefined ? "Edit" : "Register"} Vendor
          </Typography>
          <AddBusinessIcon fontSize="large" />
        </Box>
        <Box
          sx={{
            marginTop: "1rem",
            width: "100%",
            display: "grid",
            gridGap: "1rem",
            gridTemplateColumns:
              "repeat(auto-fit, minmax(250px, 1fr) minmax(200px, 0.5fr))",
          }}
        >
          <TextField
            label="Identifier"
            variant="standard"
            name="identificator"
            inputProps={
              vendorUUID === undefined
                ? { maxLength: 60 }
                : { maxLength: 60, readOnly: true }
            }
            value={vendor.identificator}
            onChange={(evt) => {
              handleOnChange(evt);
              setError([]);
            }}
            fullWidth
            required
            {...(error === "identificator" && { error })}
          />
          <FormControl variant="standard">
            <InputLabel id="id-situation-form-vendor">Situation</InputLabel>
            <Select
              labelId="id-situation-form-vendor"
              label="Situation"
              value={vendor.situation}
              name="situation"
              onChange={(evt) => {
                handleOnChange(evt);
              }}
            >
              {vendorSituation.map((item, index) => (
                <MenuItem key={index} value={item.value}>
                  {item.label}
                </MenuItem>
              ))}
            </Select>
          </FormControl>
        </Box>
        <Box sx={{ width: "100%", marginTop: "1rem" }}>
          <TextField
            label="Name"
            variant="standard"
            name="name"
            inputProps={{ maxLength: 60 }}
            value={vendor.name}
            onChange={(evt) => {
              handleOnChange(evt);
              setError([]);
            }}
            fullWidth
            required
            {...(error === "name" && { error })}
          />
        </Box>
        <Box sx={{ width: "100%", marginTop: "1rem" }}>
          <TextField
            label="Address"
            variant="standard"
            name="address"
            inputProps={{ maxLength: 60 }}
            value={vendor.address}
            onChange={(evt) => {
              handleOnChange(evt);
              setError([]);
            }}
            fullWidth
            required
            {...(error === "address" && { error })}
          />
        </Box>
        {contact.length > 0
          ? contact.map((item, index) => {
              return (
                <Contact
                  key={index}
                  index={index}
                  initialLabel={item.label}
                  initialType={item.contactTypeLabel}
                  setVendorContact={setVendorContact}
                  error={error}
                />
              );
            })
          : initialContact.map((item, index) => {
              return (
                <Contact
                  key={index}
                  index={index}
                  initialLabel={item.label}
                  initialType={item.contactTypeLabel}
                  setVendorContact={setVendorContact}
                  error={error}
                />
              );
            })}
        {contact.length > 0 && contact.length < initialContact.length ? (
          initialContact.map((item, index) => {
            if (index >= contact.length) {
              return (
                <Contact
                  key={index}
                  index={index}
                  initialLabel={item.label}
                  initialType={item.contactTypeLabel}
                  setVendorContact={setVendorContact}
                  error={error}
                />
              );
            }
          })
        ) : (
          <></>
        )}
        <Box
          sx={{
            width: "100%",
            marginTop: "1rem",
            display: "flex",
            justifyContent: "end",
          }}
        >
          {loading ? (
            <Box className="loader" sx={{ width: "3rem", height: "3rem" }} />
          ) : (
            <Box
              sx={{
                marginTop: "1.5rem",
                width: "100%",
                display: "grid",
                gridGap: "1rem",
                gridTemplateColumns: "repeat(auto-fill, minmax(150px, 1fr))",
                direction: "rtl",
              }}
            >
              <Button
                onClick={handleCloseModal}
                variant="outlined"
                color="error"
              >
                Cancel
              </Button>
              <Button
                onClick={() => {
                  handleRegisterVendor();
                }}
                variant="contained"
              >
                {vendorUUID === undefined ? "Register" : "Save"}
              </Button>
            </Box>
          )}
        </Box>
      </Box>
    </Modal>
  );
};

export default ModalVendor;
