import { stockRepository } from "../repositories/StockRepository";

class StockUseCases {
  async getStock(filterList, listByWarehouse) {
    const response = await stockRepository.getStock(filterList, listByWarehouse);
    return response;
  }

  async getStockExcel(warehouseUUID){
    const errors = new Map();
    if(warehouseUUID === ""){
      return errors.set("error", "You need to inform an warehouse");
    }
    return await stockRepository.getStockExcel(warehouseUUID);
  }

  async getWarehouse() {
    const response = await stockRepository.getWarehouse();
    return response.data;
  }

  async getStockDetail(packingId) {
    const response = await stockRepository.getDetailingStock(packingId);
    return response;
  }

  async confirmCartUseCase(data, warehouseUuid) {
    if (warehouseUuid === 0) {
      const response = new Error("You need select a warehouse");
      return response
    } else {
      return await stockRepository.confirmCart(data, warehouseUuid);
    }
  }

  async queryVolumeUseCases() {
    return await stockRepository.queryVolume();
  }

  async queryWarehouseOrigin() {
    return stockRepository.queryWarehouseOrigin();
  }

  async deleteItemUseCases(itemNumber) {
    return await stockRepository.deleteItem(itemNumber);
  }

  addItemUseCase(item) {
    return stockRepository.addItem(item);
  }

  verifyExistingItem(item) {
    return stockRepository.verifyExistingItem(item);
  }

  deleteAllBoxes() {
    stockRepository.deleteAllBoxes();
  }

  async confirmReceipt(uuid) {
    return stockRepository.confirmReceipt(uuid);
  }

  async getVariantsByBox(boxNumber) {
    return await stockRepository.getVariantsByBox(boxNumber);
  }
}

export const stockUseCases = new StockUseCases();
