import styled from "@emotion/styled";
import {
  Button,
  Chip,
  FormControlLabel,
  Grid,
  Icon,
  IconButton,
  MenuItem,
  Pagination,
  Paper,
  Popover,
  Select,
  Switch,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  TableSortLabel,
  TextField,
  Tooltip,
  Typography,
  tableCellClasses,
} from "@mui/material";
import { Box, Stack } from "@mui/system";
import { useEffect, useState } from "react";
import FilterListRoundedIcon from "@mui/icons-material/FilterListRounded";
import { stockUseCases } from "../usecases/StockUseCases";
import { Link } from "react-router-dom";
import ListRoundedIcon from "@mui/icons-material/ListRounded";
import ModalStockExcel from "../components/ModalStockExcel";
import ReactDOM from "react-dom/client";
import { RiFileExcel2Fill } from "react-icons/ri";

const StyledTableCell = styled(TableCell)(({ theme }) => ({
  [`&.${tableCellClasses.head}`]: {
    backgroundColor: "#15191C",
    color: "white",
  },
  [`&.${tableCellClasses.body}`]: {
    fontSize: 14,
  },
}));

const StyledTableRow = styled(TableRow)(({ theme }) => ({
  "&:nth-of-type(odd)": {
    backgroundColor: "#f3f3f3",
  },
  "&:last-child td, &:last-child th": {
    border: 0,
  },
}));

const columns = [
  {
    label: "Code",
    value: "productTextCode",
    width: "10%",
    align: "right",
    isOrder: true,
    isFilter: true,
    isNumber: false,
    maxLength: 10,
    type: "text",
  },
  {
    label: "Description",
    value: "productDescription",
    width: "30%",
    align: "left",
    isOrder: true,
    isFilter: true,
    isNumber: false,
    maxLength: 30,
    type: "text",
  },
  {
    label: "Box quantity",
    value: "totalQuantity",
    width: "10%",
    align: "right",
    isOrder: false,
    isFilter: false,
    isNumber: false,
    maxLength: 10,
    type: "number",
  },
  {
    label: "Box requested",
    value: "requestedQuantity",
    width: "10%",
    align: "right",
    isOrder: false,
    isFilter: false,
    isNumber: false,
    maxLength: 10,
    type: "number",
  },
  {
    label: "Box available",
    value: "availableQuantity",
    width: "10%",
    align: "right",
    isOrder: false,
    isFilter: false,
    isNumber: false,
    maxLength: 10,
    type: "number",
  },
  {
    label: "Warehouse Code",
    value: "warehouseCode",
    width: "15%",
    align: "left",
    isOrder: true,
    isFilter: true,
    isNumber: false,
    maxLength: 10,
    type: "text",
  },
  {
    label: "Warehouse",
    value: "warehouseDescription",
    width: "15%",
    align: "left",
    isOrder: true,
    isFilter: true,
    isNumber: false,
    maxLength: 30,
    type: "text",
  },
  {
    label: "Action",
    value: "action",
    align: "center",
    width: "4%",
    isOrder: false,
    isFilter: false,
  },
];

const styleTableSortLabel = {
  "&.MuiTableSortLabel-root": {
    color: "white",
  },
  "&.MuiTableSortLabel-root:hover": {
    color: "white",
  },
  "&.Mui-active": {
    color: "white",
  },
  "& .MuiTableSortLabel-icon": {
    color: "white !important",
  },
  textAlign: "center",
};

const filtersDefault = {
  page: 1,
  rowsPerPage: 10,
  orderBy: "",
  sort: "asc",
  filters: [],
};

const popoverDefault = {
  label: "",
  column: "",
  type: "text",
  maxLength: 10,
  isNumber: false,
  value: "",
};

const Stock = () => {
  const [stockList, setStockList] = useState([]);

  const [filterList, setFilterList] = useState(filtersDefault);
  const [pageList, setPageList] = useState(0);

  const [anchorEl, setAnchorEl] = useState(null);
  const [popover, setPopover] = useState(popoverDefault);
  const [chipData, setChipData] = useState([]);

  const [loading, setLoading] = useState(false);

  const [listByWarehouse, setListByWarehouse] = useState(
    JSON.parse(sessionStorage.getItem("list-stock_byWarehouse")) !== null
      ? JSON.parse(sessionStorage.getItem("list-stock_byWarehouse"))
      : false
  );

  const openPopover = Boolean(anchorEl);
  const id = openPopover ? "simple-popover" : undefined;

  /**
   * Arrow funciton to set order by filter
   * @param {String} value
   */
  const handleOrderBy = (value) => {
    setFilterList({
      ...filterList,
      ["orderBy"]: value,
      ["sort"]: filterList.sort === "asc" ? "desc" : "asc",
    });
  };
  /**
   * Arrow function to set the page filter
   * @param {Event} evt
   * @param {String} value
   */
  const handleChangePage = (evt, value) => {
    setFilterList({
      ...filterList,
      ["page"]: value,
      ["orderBy"]: "",
      ["sort"]: "asc",
    });
  };
  /**
   * Arrow function to set the rows per page filter
   * @param {Event} evt
   */
  const handleChangeRowsPerPage = (evt) => {
    setFilterList({
      ...filterList,
      ["rowsPerPage"]: evt.target.value,
      ["orderBy"]: "",
      ["sort"]: "asc",
    });
  };
  /**
   * Arrow function to close popover
   */
  const handleClosePopover = () => {
    setAnchorEl(null);
  };
  /**
   * Arrow function to open and set the default values popover
   */
  const handleClickPopover = (
    event,
    label,
    column,
    type,
    maxLength,
    number
  ) => {
    setAnchorEl(event);
    setPopover({
      label: label,
      column: column,
      type: type,
      maxLength: maxLength,
      isNumber: number,
    });
  };
  /**
   * Arrow function to confirm and set the filters to list
   */
  const handleConfirmPopover = () => {
    setAnchorEl(null);
    setChipData((chips) =>
      chips.filter((chip) => chip.labelFilter !== popover.label)
    );
    setChipData((prevState) => [
      ...prevState,
      {
        labelFilter: popover.label,
        columnPopover: popover.column,
        valueFilter: popover.value,
      },
    ]);
    setFilterList({
      ...filterList,
      ["page"]: 1,
      ["filters"]: [
        {
          labelFilter: popover.label,
          columnPopover: popover.column,
          valueFilter: popover.value,
        },
      ],
    });
  };
  /**
   * Arrow function to delete the chipData list and re-set the filter to reload the page
   * @param {[]} chipToDelete
   */
  const handleDeleteChip = (chipToDelete) => () => {
    setChipData((chips) =>
      chips.filter((chip) => chip.labelFilter !== chipToDelete.labelFilter)
    );
    setFilterList({
      ...filterList,
      ["filters"]: chipData.filter(
        (chip) => chip.labelFilter !== chipToDelete.labelFilter
      ),
    });
  };

  const handleListByWarehouse = () => {
    sessionStorage.setItem("list-stock_byWarehouse", !listByWarehouse);
    setListByWarehouse(!listByWarehouse);
  };

  /**
   * Arrow function to reset the filters
   */
  const handClickResetList = () => {
    setFilterList({
      page: 1,
      rowsPerPage: 10,
      orderBy: "",
      sort: "asc",
      filters: [],
    });
    setChipData([]);
  };

  /**
   * Arrow function to set time out to loader from page
   */
  const handleTimeOut = (response) => {
    setTimeout(() => {
      setStockList(response?.data?.stock ?? []);
      setPageList(response?.data?.numberPages ?? 0);
      setLoading(false);
    }, 100);
  };
  const openModalStockExcel = () => {
    const root = ReactDOM.createRoot(
      document.getElementById("view_modal_excel_stock")
    );
    return root.render(<ModalStockExcel isOpenDetails={true} />);
  };

  useEffect(() => {
    document.title = "Lince Tech Micro ERP | Stock managment";
    // setLoading(true);

    if (sessionStorage.getItem("pre_filters") !== null) {
      const filters = sessionStorage.getItem("pre_filters");
      filterList.filters = JSON.parse(filters);
      setChipData(JSON.parse(filters));
      console.log(sessionStorage.getItem("pre_filters"))
      sessionStorage.removeItem("pre_filters");
    }

    const getStock = async () => {
      const response = await stockUseCases.getStock(
        filterList,
        listByWarehouse
      );
      return response;
    };
    getStock().then((response) => {
      handleTimeOut(response);
    });
  }, [filterList, listByWarehouse, chipData]);

  return (
    <Box
      sx={{
        display: "flex",
        marginLeft: "3rem",
        marginTop: "3rem",
        marginRight: "2rem",
      }}
    >
      <input type="hidden" id="view_modal_excel_stock" />
      <Box sx={{ width: "100%" }}>
        <Typography sx={{ fontSize: "26pt", fontWeight: "800" }}>
          Stock
        </Typography>
        <Box
          sx={{
            minWidth: "100%",
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
            marginTop: "0.5rem",
          }}
        >
          <Box sx={{ display: "flex" }}>
            <Box
              sx={{
                display: "flex",
                justifyContent: "center",
                flexWrap: "nowrap",
                listStyle: "none",
                p: 0,
                m: 0,
                border: "none",
                height: "4rem",
                alignItems: "center",
              }}
            >
              {chipData.map((data, index) => {
                return (
                  <Tooltip
                    title={data.labelFilter}
                    placement="bottom"
                    arrow
                    key={index}
                  >
                    <Chip
                      sx={{
                        textOverFlow: "ellipsis",
                        overFlow: "hidden",
                        whiteSpace: "nowrap",
                        maxWidth: "145px",
                        marginRight: "1rem",
                      }}
                      color="primary"
                      variant="outlined"
                      label={data.valueFilter}
                      onDelete={handleDeleteChip(data)}
                    />
                  </Tooltip>
                );
              })}
            </Box>
            {chipData.length === 0 ? (
              <></>
            ) : (
              <Button onClick={() => handClickResetList()}>Clear All</Button>
            )}
          </Box>
          <Box>
            <Tooltip title="Create excel from stock" placement="bottom">
              <IconButton
                onClick={(evt) => {
                  openModalStockExcel(evt);
                }}
                size="large"
              >
                <RiFileExcel2Fill />
              </IconButton>
            </Tooltip>
            <FormControlLabel
              sx={{ align: "left", fontSize: "11pt", marginLeft: "5px" }}
              control={
                <Tooltip title="Show warehouse" placement="bottom">
                  <Switch
                    onChange={handleListByWarehouse}
                    checked={listByWarehouse}
                  />
                </Tooltip>
              }
              label="Show warehouse"
            />
          </Box>
        </Box>
        <Paper sx={{ width: "100%", overflow: "hidden", marginTop: "0.5rem" }}>
          {loading ? (
            <Box
              sx={{
                width: "100%",
                justifyContent: "center",
                display: "flex",
                padding: "2%",
              }}
            >
              <Box className="loader" />
            </Box>
          ) : (
            <TableContainer component={Paper} sx={{ maxHeight: "80vh" }}>
              <Table
                stickyHeader
                aria-label="stock table"
                sx={{ minWidth: "800px" }}
              >
                <TableHead>
                  <StyledTableRow>
                    {columns.map((key, index) => {
                      if (
                        (key.value === "warehouseCode" ||
                          key.value === "warehouseDescription") &&
                        !listByWarehouse
                      )
                        return "";
                      return (
                        <StyledTableCell
                          key={index}
                          align={key.align}
                          width={key.width}
                        >
                          <Grid
                            container
                            justifyContent={"space-between"}
                            flexWrap={"nowrap"}
                            alignItems={"center"}
                          >
                            <Tooltip title={key.label} placement="top">
                              {key.isOrder === true ? (
                                <TableSortLabel
                                  sx={styleTableSortLabel}
                                  active={filterList.orderBy === key.value}
                                  direction={filterList.sort}
                                  onClick={() => handleOrderBy(key.value)}
                                >
                                  {key.label}
                                </TableSortLabel>
                              ) : (
                                <Typography sx={{ textAlign: "center" }}>
                                  {key.label}
                                </Typography>
                              )}
                            </Tooltip>
                            {key.isFilter === true && (
                              <Tooltip
                                title={`Filter by ${key.label}`}
                                placement="top"
                              >
                                <FilterListRoundedIcon
                                  variant="contained"
                                  onClick={(evt) =>
                                    handleClickPopover(
                                      evt.currentTarget,
                                      key.label,
                                      key.value,
                                      key.type,
                                      key.maxLength,
                                      key.isNumber
                                    )
                                  }
                                  sx={{
                                    width: "18px",
                                    justifySelf: "end",
                                    cursor: "pointer",
                                  }}
                                />
                              </Tooltip>
                            )}
                          </Grid>
                        </StyledTableCell>
                      );
                    })}
                  </StyledTableRow>
                </TableHead>
                <TableBody>
                  {stockList.map((stock, index) => {
                    return (
                      <StyledTableRow key={index}>
                        <StyledTableCell size="small">
                          {stock?.product?.numericCode ?? ""}
                        </StyledTableCell>
                        <StyledTableCell size="small">
                          {stock?.product?.description ?? ""}
                        </StyledTableCell>
                        <StyledTableCell size="small">
                          {stock?.totalQuantity ?? ""}
                        </StyledTableCell>
                        <StyledTableCell size="small">
                          {stock?.requestedQuantity ?? ""}
                        </StyledTableCell>
                        <StyledTableCell size="small">
                          {stock?.availableQuantity ?? ""}
                        </StyledTableCell>
                        {listByWarehouse == true && stock?.warehouse != null && (
                          <>
                            <StyledTableCell size="small">
                              {stock.warehouse.code}
                            </StyledTableCell>
                            <StyledTableCell size="small">
                              {stock.warehouse.description}
                            </StyledTableCell>
                          </>
                        )}
                        <StyledTableCell size="small">
                          <Link
                            to={
                              listByWarehouse
                                ? `${stock?.product?.textCode ?? ""}/${
                                    stock?.warehouse?.description ?? ""
                                  }/BoxRequestListing`
                                : `${
                                    stock?.product?.textCode ?? ""
                                  }/BoxRequestListing`
                            }
                            onClick={() =>
                              sessionStorage.setItem(
                                "pre_filters",
                                JSON.stringify(chipData)
                              )
                            }
                          >
                            <Tooltip title="View boxes" placement="left">
                              <IconButton>
                                <ListRoundedIcon
                                  sx={{
                                    cursor: "pointer",
                                    "&:hover": { textDecoration: "none" },
                                  }}
                                  color="action"
                                />
                              </IconButton>
                            </Tooltip>
                          </Link>
                        </StyledTableCell>
                      </StyledTableRow>
                    );
                  })}
                </TableBody>
              </Table>
            </TableContainer>
          )}
        </Paper>
        <Box
          display={"flex"}
          justifyContent={"flex-end"}
          sx={{ marginTop: "2vh", alignItems: "center", gap: "1vw" }}
        >
          <Typography sx={{ align: "center", fontSize: "11pt" }}>
            Rows Per Page
          </Typography>

          <Select
            sx={{ height: "4vh", align: "center" }}
            autoWidth
            value={filterList.rowsPerPage}
            onChange={handleChangeRowsPerPage}
          >
            <MenuItem value={5}>5</MenuItem>
            <MenuItem value={10}>10</MenuItem>
            <MenuItem value={15}>15</MenuItem>
          </Select>

          <Stack spacing={2}>
            <Pagination
              count={pageList}
              page={filterList.page}
              onChange={handleChangePage}
            />
          </Stack>
        </Box>
        <Popover
          id={id}
          open={openPopover}
          anchorEl={anchorEl}
          onClose={handleClosePopover}
          anchorOrigin={{
            vertical: "bottom",
            horizontal: "left",
          }}
        >
          <Box
            sx={{
              display: "flex",
              alignContent: "center",
              alignItems: "center",
              p: 2,
              gap: 2,
            }}
          >
            <Typography>Filter</Typography>
            <TextField
              type={popover.type}
              inputProps={{ maxLength: popover.maxLength }}
              variant="outlined"
              placeholder={popover.label}
              size="small"
              onKeyDown={(evt) =>
                evt.keyCode === 13 ? handleConfirmPopover() : ""
              }
              onChange={(evt) => {
                if (popover.type === "number") {
                  evt.target.value = evt.target.value.replace(/[^0-9,]/g, "");
                }
                setPopover({
                  ...popover,
                  ["value"]: evt.target.value,
                });
              }}
            ></TextField>
            <Button variant="outlined" onClick={handleConfirmPopover}>
              Confirm
            </Button>
          </Box>
        </Popover>
      </Box>
    </Box>
  );
};

export default Stock;
