import {
  Box,
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  FormControl,
  InputLabel,
  MenuItem,
  Modal,
  Paper,
  Select,
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableRow,
  Typography,
} from "@mui/material";
import { useEffect, useState } from "react";
import { icons as Icons } from "../../../shared/entities/Icons";
import { productUseCase } from "../usecases/ProductUseCase";
import ClearIcon from "@mui/icons-material/Clear";
import Swal from "sweetalert2";

const modalStyle = {
  position: "absolute",
  top: "50%",
  left: "50%",
  transform: "translate(-50%, -50%)",
  minWidth: "60%",
  backgroundColor: "#ffffff",
  borderRadius: "10px",
  boxShadow: 24,
  p: 4,
  display: "flex",
  flexDirection: "row",
  overflowY: "hidden",
  outline: "none",
  flexWrap: "wrap",
  mxHeight: "75vh",
};

const ModalProductExcel = ({
  isOpen,
  handleUpdateSetListProducts,
  productsToExport,
}) => {
  const [open, setOpen] = useState(isOpen);
  const [selectedProducts, setSelectedProducts] = useState(
    Array.from(productsToExport.keys())
  );
  const [listSelectedProducts, setListSelectedProducts] = useState(
    Array.from(productsToExport.values())
  );
  const [priceTable, setPriceTable] = useState([]);
  const [selectedPriceTable, setSelectedPriceTable] = useState("");

  const handleClose = () => {
    setOpen(!open);
  };

  const handleDeleteItem = (evt, product) => {
    evt.preventDefault();
    handleUpdateSetListProducts(product);
    var newArray = selectedProducts.filter((value) => value != product);
    setSelectedProducts(Array.from(newArray));
  };

  const handleExportExcel = () => {
    const getProductExcel = async () => {
      const response = await productUseCase.getProductExcel(
        selectedProducts,
        selectedPriceTable
      );
      return response;
    };
    getProductExcel().then((response) => {
      if (response instanceof Map) {
        return Swal.fire({
          icon: "warning",
          text: response.get("error"),
        });
      }else{
        handleClose();
      }
    });
  };

  useEffect(() => {
    const getPriceTable = async () => {
      const response = await productUseCase.getPriceTable();
      return response;
    };
    getPriceTable().then((response) =>
      setPriceTable(response?.data?.priceTable ?? [])
    );
  }, []);

  return (
    <Modal open={open} onClose={handleClose}>
      <Box sx={modalStyle}>
        <Box sx={{ display: "flex", flexDirection: "column", width: "100%" }}>
          <Box
            sx={{
              display: "flex",
              flexDirection: "row",
              justifyContent: "space-between",
              width: "100%",
            }}
          >
            <Typography
              sx={{
                fontSize: "1.2em",
                fontWeight: "700",
                color: "#363636",
                paddingBottom: 1,
              }}
            >
              Export product to Excel
            </Typography>
          </Box>
          <Box
            sx={{
              display: "flex",
              flexDirection: "column",
              width: "100%",
            }}
          >
            <FormControl
              variant="outlined"
              sx={{ width: "100%", marginBottom: "1rem", marginTop: "1rem" }}
            >
              <InputLabel id="id-priceTable-form">
                Select an price table
              </InputLabel>
              <Select
                labelId="id-priceTable-form"
                label="Select an price table"
                value={selectedPriceTable}
                name="select-priceTable"
                onChange={(event) => setSelectedPriceTable(event.target.value)}
              >
                {priceTable.map((table, index) => (
                  <MenuItem key={index} value={table?.priceTableUUID ?? ""}>
                    {table?.name ?? ""}
                  </MenuItem>
                ))}
              </Select>
            </FormControl>
          </Box>
          <Box sx={{ height: "500px", maxHeight: "75%", overflowY: "scroll" }}>
            <Paper>
              <Table>
                <TableHead>
                  <TableRow>
                    <TableCell>Description</TableCell>
                    <TableCell>&nbsp;</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {selectedProducts.length > 0 ? (
                    selectedProducts.map((value, index) => (
                      <TableRow key={index}>
                        <TableCell>{listSelectedProducts[index]}</TableCell>
                        <TableCell sx={{ p: 0 }} align="right">
                          <Button
                            onClick={(evt) => handleDeleteItem(evt, value)}
                            sx={{ color: "#032d307d" }}
                          >
                            Remove &nbsp;
                            <ClearIcon
                              sx={{ color: "#032d307d" }}
                              titleAccess="Remove item"
                            />
                          </Button>
                        </TableCell>
                      </TableRow>
                    ))
                  ) : (
                    <TableRow>
                      <TableCell colSpan={2} align="center">
                        Select an product
                      </TableCell>
                    </TableRow>
                  )}
                </TableBody>
              </Table>
            </Paper>
          </Box>
          <Box
            sx={{
              width: "100%",
              display: "flex",
              marginTop: "2rem"
            }}
          >
            <Box
              sx={{
                width: "100%",
                display: "grid",
                gridGap: "1rem",
                gridTemplateColumns: "repeat(auto-fill, minmax(120px, 1fr))",
                direction: "rtl",
              }}
            >
              <Button variant="contained" onClick={handleExportExcel}>
                Excel
              </Button>
              <Button variant="outlined" color="error" onClick={handleClose}>
                Close
              </Button>
            </Box>
          </Box>
        </Box>
      </Box>
    </Modal>
  );
};

export default ModalProductExcel;
