import styled from "@emotion/styled";
import {
  Button,
  Chip,
  CircularProgress,
  Grid,
  IconButton,
  MenuItem,
  Pagination,
  Paper,
  Popover,
  Select,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  TableSortLabel,
  TextField,
  Tooltip,
  Typography,
  tableCellClasses,
} from "@mui/material";
import { Box, Stack } from "@mui/system";
import { useEffect, useState } from "react";
import FilterListRoundedIcon from "@mui/icons-material/FilterListRounded";
import { requestHistoryUseCases } from "../usecases/RequestHistoryUseCases";
import dayjs from "dayjs";
import AutorenewIcon from "@mui/icons-material/Autorenew";
import CheckIcon from "@mui/icons-material/Check";
import DeleteRoundedIcon from "@mui/icons-material/DeleteRounded";
import CancelRoundedIcon from "@mui/icons-material/CancelRounded";
import FormatListBulletedIcon from "@mui/icons-material/FormatListBulleted";
import PackingList from "../components/detailStock/ModalStockDetail";
import ReactDOM from "react-dom/client";
import Swal from "sweetalert2";

const StyledTableCell = styled(TableCell)(({ theme }) => ({
  [`&.${tableCellClasses.head}`]: {
    backgroundColor: "#15191C",
    color: "white",
  },
  [`&.${tableCellClasses.body}`]: {
    fontSize: 14,
  },
}));

const StyledTableRow = styled(TableRow)(({ theme }) => ({
  "&:nth-of-type(odd)": {
    backgroundColor: "#f3f3f3",
  },
  "&:last-child td, &:last-child th": {
    border: 0,
  },
}));

const columns = [
  {
    label: "Code",
    value: "code",
    width: "8%",
    align: "left",
    isOrder: true,
    isFilter: true,
    isNumber: true,
    maxLength: 10,
    type: "number",
  },
  {
    label: "Warehouse origin",
    value: "originWarehouse",
    width: "30%",
    align: "left",
    isOrder: false,
    isFilter: false,
    isNumber: false,
    maxLength: 30,
    type: "text",
  },
  {
    label: "Warehouse destiny",
    value: "destinyWarehouse",
    width: "10%",
    align: "right",
    isOrder: false,
    isFilter: false,
    isNumber: false,
    maxLength: 30,
    type: "text",
  },
  {
    label: "Volumes",
    value: "volumes",
    width: "10%",
    align: "right",
    isOrder: false,
    isFilter: false,
    isNumber: true,
    maxLength: 10,
    type: "number",
  },
  {
    label: "Situation",
    value: "condition",
    width: "10%",
    align: "right",
    isOrder: false,
    isFilter: false,
    isNumber: false,
    maxLength: 20,
    type: "text",
  },
  {
    label: "Create",
    value: "createdAt",
    width: "15%",
    align: "left",
    isOrder: true,
    isFilter: true,
    isNumber: false,
    maxLength: 10,
    type: "text",
  },
  {
    label: "Received",
    value: "receivedAt",
    width: "15%",
    align: "left",
    isOrder: true,
    isFilter: true,
    isNumber: false,
    maxLength: 10,
    type: "text",
  },
  {
    label: "Action",
    value: "action",
    align: "center",
    width: "4%",
    isOrder: false,
    isFilter: false,
  },
];

const styleTableSortLabel = {
  "&.MuiTableSortLabel-root": {
    color: "white",
  },
  "&.MuiTableSortLabel-root:hover": {
    color: "white",
  },
  "&.Mui-active": {
    color: "white",
  },
  "& .MuiTableSortLabel-icon": {
    color: "white !important",
  },
  textAlign: "center",
};

const filtersDefault = {
  page: 1,
  rowsPerPage: 10,
  orderBy: "",
  sort: "desc",
  filters: [],
};

const popoverDefault = {
  label: "",
  column: "",
  type: "text",
  maxLength: 10,
  isNumber: false,
  value: "",
};

const Toast = Swal.mixin({
  toast: true,
  position: "top-end",
  showConfirmButton: false,
  timer: 3000,
  timerProgressBar: true,
  didOpen: (toast) => {
    toast.addEventListener("mouseenter", Swal.stopTimer);
    toast.addEventListener("mouseleave", Swal.resumeTimer);
  },
});

const RequestHistory = () => {
  const [requestHistoryList, setRequestHistoryList] = useState([]);

  const [filterList, setFilterList] = useState(filtersDefault);
  const [pageList, setPageList] = useState(0);

  const [anchorEl, setAnchorEl] = useState(null);
  const [popover, setPopover] = useState(popoverDefault);
  const [chipData, setChipData] = useState([]);

  const [loading, setLoading] = useState(false);

  const openPopover = Boolean(anchorEl);
  const id = openPopover ? "simple-popover" : undefined;

  const [change, setChange] = useState(true);

  const [loadingLine, setLoadingLine] = useState(false);

  /**
   * Arrow funciton to set order by filter
   * @param {String} value
   */
  const handleOrderBy = (value) => {
    setFilterList({
      ...filterList,
      ["orderBy"]: value,
      ["sort"]: filterList.sort === "asc" ? "desc" : "asc",
    });
  };
  /**
   * Arrow function to set the page filter
   * @param {Event} evt
   * @param {String} value
   */
  const handleChangePage = (evt, value) => {
    setFilterList({
      ...filterList,
      ["page"]: value,
    });
  };
  /**
   * Arrow function to set the rows per page filter
   * @param {Event} evt
   */
  const handleChangeRowsPerPage = (evt) => {
    setFilterList({
      ...filterList,
      ["rowsPerPage"]: evt.target.value,
    });
  };
  /**
   * Arrow function to close popover
   */
  const handleClosePopover = () => {
    setAnchorEl(null);
  };
  /**
   * Arrow function to open and set the default values popover
   */
  const handleClickPopover = (
    event,
    label,
    column,
    type,
    maxLength,
    number
  ) => {
    setAnchorEl(event);
    setPopover({
      label: label,
      column: column,
      type: type,
      maxLength: maxLength,
      isNumber: number,
    });
  };
  /**
   * Arrow function to confirm and set the filters to list
   */
  const handleConfirmPopover = () => {
    setAnchorEl(null);
    setChipData((chips) =>
      chips.filter((chip) => chip.labelFilter !== popover.label)
    );
    setChipData((prevState) => [
      ...prevState,
      {
        labelFilter: popover.label,
        columnPopover: popover.column,
        valueFilter: popover.value,
      },
    ]);
    setFilterList({
      ...filterList,
      ["page"]: 1,
      ["filters"]: [
        {
          labelFilter: popover.label,
          columnPopover: popover.column,
          valueFilter: popover.value,
        },
      ],
    });
  };
  /**
   * Arrow function to delete the chipData list and re-set the filter to reload the page
   * @param {[]} chipToDelete
   */
  const handleDeleteChip = (chipToDelete) => () => {
    setChipData((chips) =>
      chips.filter((chip) => chip.labelFilter !== chipToDelete.labelFilter)
    );
    setFilterList({
      ...filterList,
      ["filters"]: chipData.filter(
        (chip) => chip.labelFilter !== chipToDelete.labelFilter
      ),
    });
  };
  /**
   * Arrow function to reset the filters
   */
  const handClickResetList = () => {
    setChipData([]);
    setFilterList(filtersDefault);
  };
  /**
   * Arrow function to set time out to loader from page
   */
  const handleTimeOut = (response) => {
    setTimeout(() => {
      setRequestHistoryList(response?.data?.stockTransfers ?? []);
      setPageList(response?.data?.numberPages ?? 0);
      // setLoading(false);
      setLoadingLine(false);
    }, 0);
  };

  const dateFormat = (date) => {
    if (date === "") {
      return "";
    }
    return new dayjs(date).format("MM/DD/YYYY");
  };

  const confirmRequest = (uuid) => {
    if (uuid === "") {
      return;
    } else {
      Swal.fire({
        title: "Confirm receipt?",
        text: "You will confirm this request!",
        icon: "warning",
        showCancelButton: true,
        confirmButtonColor: "#3085d6",
        cancelButtonColor: "#d33",
        confirmButtonText: "Confirm",
      }).then((result) => {
        if (result.isConfirmed) {
          submitConfirm(uuid);
        }
      });
    }
  };

  const submitConfirm = async (uuid) => {
    try {
      setLoadingLine(true);
      await requestHistoryUseCases.confirmRequest(uuid).then((response) => {
        if (response.description) {
          return Swal.fire({
            icon: "error",
            text: response.description,
            confirmButtonColor: "#3085d6",
          });
        } else {
          setChange(!change);
          return Toast.fire({
            icon: "success",
            text: "Success",
          });
        }
      });
    } catch (e) {
      if (e.response.data) {
        Swal.fire("Error", "An error has occurred", "error");
      }
    }
  };

  const deleteRequest = (uuid) => {
    if (uuid === "") {
      return;
    } else {
      Swal.fire({
        title: "Delete receipt?",
        text: "You will delete this request!",
        icon: "warning",
        showCancelButton: true,
        confirmButtonColor: "#3085d6",
        cancelButtonColor: "#d33",
        confirmButtonText: "Confirm",
      }).then((result) => {
        if (result.isConfirmed) {
          submitDelete(uuid);
        }
      });
    }
  };

  const submitDelete = async (uuid) => {
    try {
      setLoadingLine(true);
      await requestHistoryUseCases.deleteRequest(uuid).then((response) => {
        if (response.description) {
          return Swal.fire({
            icon: "error",
            text: response.description,
            confirmButtonColor: "#3085d6",
          });
        } else {
          setChange(!change);
          return Toast.fire({
            icon: "success",
            text: "Success",
          });
        }
      });
    } catch (e) {
      if (e.response.data) {
        Swal.fire("Error", "An error has ocurred", "error");
      }
    }
  };

  const cancelRequest = (uuid) => {
    if (uuid === "") {
      return;
    } else {
      Swal.fire({
        title: "Cancel receipt?",
        text: "You will cancel this request!",
        icon: "warning",
        showCancelButton: true,
        confirmButtonColor: "#3085d6",
        cancelButtonColor: "#d33",
        confirmButtonText: "Confirm",
      }).then((result) => {
        if (result.isConfirmed) {
          submitCancel(uuid);
        }
      });
    }
  };

  const submitCancel = async (uuid) => {
    try {
      setLoadingLine(true);
      await requestHistoryUseCases.cancelRequest(uuid).then((response) => {
        if (response.description) {
          return Swal.fire({
            icon: "error",
            text: response.description,
            confirmButtonColor: "#3085d6",
          });
        } else {
          setChange(!change);
          return Toast.fire({
            icon: "success",
            text: "Success",
          });
        }
      });
    } catch (e) {
      if (e.response.data) {
        Swal.fire("Error", "An error has ocurred", "error");
      }
    }
  };

  useEffect(() => {
    document.title = "Lince Tech Micro ERP | Request history";
    // setLoading(true);
    const getRequestHistory = async () => {
      const response = await requestHistoryUseCases.listRequestHistory(
        filterList
      );
      return response;
    };
    getRequestHistory().then((response) => {
      handleTimeOut(response);
    });
  }, [filterList, change]);

  const handleOpenDetailing = (stockUUID) => {
    if (stockUUID === "") {
      return;
    } else {
      const root = ReactDOM.createRoot(document.getElementById("modal-stock"));
      return root.render(<PackingList isOpen={true} stockUUID={stockUUID} />);
    }
  };

  return (
    <Box
      sx={{
        display: "flex",
        marginLeft: "3rem",
        marginTop: "3rem",
        marginRight: "2rem",
      }}
    >
      <input type="hidden" id="modal-stock" />
      <Box sx={{ width: "100%" }}>
        <Typography sx={{ fontSize: "26pt", fontWeight: "800" }}>
          Request history
        </Typography>
        <Box
          sx={{
            minWidth: "100%",
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
            marginTop: "0.5rem",
          }}
        >
          <Box sx={{ display: "flex" }}>
            <Box
              sx={{
                display: "flex",
                justifyContent: "center",
                flexWrap: "nowrap",
                listStyle: "none",
                p: 0,
                m: 0,
                border: "none",
                height: "4rem",
                alignItems: "center",
              }}
            >
              {chipData.map((data, index) => {
                return (
                  <Tooltip title={data.labelFilter} placement="bottom" arrow>
                    <Chip
                      key={index}
                      sx={{
                        textOverFlow: "ellipsis",
                        overFlow: "hidden",
                        whiteSpace: "nowrap",
                        maxWidth: "145px",
                        marginRight: "1rem",
                      }}
                      color="primary"
                      variant="outlined"
                      label={data.valueFilter}
                      onDelete={handleDeleteChip(data)}
                    />
                  </Tooltip>
                );
              })}
            </Box>
            {chipData.length === 0 ? (
              <></>
            ) : (
              <Button onClick={handClickResetList}>Clear All</Button>
            )}
          </Box>
        </Box>
        <Paper sx={{ width: "100%", overflow: "hidden", marginTop: "0.5rem" }}>
          {loading ? (
            <Box
              sx={{
                width: "100%",
                justifyContent: "center",
                display: "flex",
                padding: "2%",
              }}
            >
              <Box className="loader" />
            </Box>
          ) : (
            <TableContainer component={Paper} sx={{ maxHeight: "80vh" }}>
              <Table
                stickyHeader
                aria-label="stock table"
                sx={{ minWidth: "800px" }}
              >
                <TableHead>
                  <StyledTableRow>
                    {columns.map((key, index) => (
                      <StyledTableCell
                        key={index}
                        align={key.align}
                        width={key.width}
                        colSpan={key.label === "Action" ? 3 : 1}
                      >
                        <Grid
                          container
                          justifyContent={
                            key.label === "Action" ? "center" : "space-between"
                          }
                          flexWrap={"nowrap"}
                          alignItems={"center"}
                        >
                          <Tooltip title={key.label} placement="top">
                            {key.isOrder === true ? (
                              <TableSortLabel
                                sx={styleTableSortLabel}
                                active={filterList.orderBy === key.value}
                                direction={filterList.sort}
                                onClick={() => handleOrderBy(key.value)}
                              >
                                {key.label}
                              </TableSortLabel>
                            ) : (
                              <Typography sx={{ textAlign: "center" }}>
                                {key.label}
                              </Typography>
                            )}
                          </Tooltip>
                          {key.isFilter === true && (
                            <Tooltip
                              title={`Filter by ${key.label}`}
                              placement="top"
                            >
                              <FilterListRoundedIcon
                                variant="contained"
                                onClick={(evt) =>
                                  handleClickPopover(
                                    evt.currentTarget,
                                    key.label,
                                    key.value,
                                    key.type,
                                    key.maxLength,
                                    key.isNumber
                                  )
                                }
                                sx={{
                                  width: "18px",
                                  justifySelf: "end",
                                  cursor: "pointer",
                                }}
                              />
                            </Tooltip>
                          )}
                        </Grid>
                      </StyledTableCell>
                    ))}
                  </StyledTableRow>
                </TableHead>
                <TableBody>
                  {requestHistoryList.map((stock, index) => (
                    <StyledTableRow key={index}>
                      <StyledTableCell size="small">
                        {stock?.code ?? ""}
                      </StyledTableCell>
                      <StyledTableCell size="small">
                        {stock?.originWarehouse?.description ?? ""}
                      </StyledTableCell>
                      <StyledTableCell size="small">
                        {stock?.destinyWarehouse?.description ?? ""}
                      </StyledTableCell>
                      <StyledTableCell size="small">
                        {stock?.boxes.length ?? ""}
                      </StyledTableCell>
                      <StyledTableCell size="small">
                        {stock.condition === 0 ? 'Waiting' : stock.condition === 1 ? 'Received' : stock.condition === 2 ? 'Deleted' : ''}
                      </StyledTableCell>
                      <StyledTableCell size="small">
                        {dateFormat(stock?.createdAt ?? "")}
                      </StyledTableCell>
                      <StyledTableCell size="small">
                        {dateFormat(stock?.receivedAt ?? "")}
                      </StyledTableCell>
                      {loadingLine ? (
                        <TableCell colSpan={2} size="small">
                          <Tooltip title="Loading..." placement="left">
                            <IconButton>
                              <CircularProgress size={20} />
                            </IconButton>
                          </Tooltip>
                        </TableCell>
                      ) : (
                        <>
                          <StyledTableCell size="small">
                            {stock.receivedAt === null ? (
                              <Tooltip title="Confirm receipt" placement="left">
                                <IconButton
                                  color="primary"
                                  onClick={() =>
                                    confirmRequest(stock?.uuid ?? "")
                                  }
                                >
                                  <AutorenewIcon />
                                </IconButton>
                              </Tooltip>
                            ) : (
                              <Tooltip title="Receipt" placement="left">
                                <IconButton color="success">
                                  <CheckIcon />
                                </IconButton>
                              </Tooltip>
                            )}
                          </StyledTableCell>
                          <StyledTableCell size="small">
                            {stock.receivedAt === null ? (
                              <Tooltip title="Delete request" placement="left">
                                <IconButton
                                  color="default"
                                  onClick={() =>
                                    deleteRequest(stock?.uuid ?? "")
                                  }
                                >
                                  <DeleteRoundedIcon />
                                </IconButton>
                              </Tooltip>
                            ) : (
                              <Tooltip title="Cancel request" placement="left">
                                <IconButton
                                  color="default"
                                  onClick={() =>
                                    cancelRequest(stock?.uuid ?? "")
                                  }
                                >
                                  <CancelRoundedIcon />
                                </IconButton>
                              </Tooltip>
                            )}
                          </StyledTableCell>
                        </>
                      )}
                      <StyledTableCell size="small">
                        <Tooltip title="Detail request" placement="left">
                          <IconButton
                            color="default"
                            onClick={() =>
                              handleOpenDetailing(stock?.uuid ?? "")
                            }
                          >
                            <FormatListBulletedIcon />
                          </IconButton>
                        </Tooltip>
                      </StyledTableCell>
                    </StyledTableRow>
                  ))}
                </TableBody>
              </Table>
            </TableContainer>
          )}
        </Paper>
        <Box
          display={"flex"}
          justifyContent={"flex-end"}
          sx={{ marginTop: "2vh", alignItems: "center", gap: "1vw" }}
        >
          <Typography sx={{ align: "center", fontSize: "11pt" }}>
            Rows Per Page
          </Typography>

          <Select
            sx={{ height: "4vh", align: "center" }}
            autoWidth
            value={filterList.rowsPerPage}
            onChange={handleChangeRowsPerPage}
          >
            <MenuItem value={5}>5</MenuItem>
            <MenuItem value={10}>10</MenuItem>
            <MenuItem value={15}>15</MenuItem>
          </Select>

          <Stack spacing={2}>
            <Pagination
              count={pageList}
              page={filterList.page}
              onChange={handleChangePage}
            />
          </Stack>
        </Box>
        <Popover
          id={id}
          open={openPopover}
          anchorEl={anchorEl}
          onClose={handleClosePopover}
          anchorOrigin={{
            vertical: "bottom",
            horizontal: "left",
          }}
        >
          <Box
            sx={{
              display: "flex",
              alignContent: "center",
              alignItems: "center",
              p: 2,
              gap: 2,
            }}
          >
            <Typography>Filter</Typography>
            <TextField
              inputProps={{ maxLength: popover.maxLength }}
              variant="outlined"
              placeholder={popover.label}
              size="small"
              onKeyDown={(evt) =>
                evt.keyCode === 13 ? handleConfirmPopover() : ""
              }
              onChange={(evt) => {
                if (popover.type === "number") {
                  evt.target.value = evt.target.value.replace(/[^0-9,]/g, "");
                }
                setPopover({
                  ...popover,
                  ["value"]: evt.target.value,
                });
              }}
            ></TextField>
            <Button variant="outlined" onClick={handleConfirmPopover}>
              Confirm
            </Button>
          </Box>
        </Popover>
      </Box>
    </Box>
  );
};

export default RequestHistory;
