import * as React from "react";
import { styled } from "@mui/material/styles";
import { useEffect, useState } from "react";
import { packingUseCases } from "../usecases/PackingUseCases";
import {
  Box,
  Chip,
  Tooltip,
  Paper,
  Button,
  Typography,
  Table,
  TableBody,
  TableCell,
  tableCellClasses,
  TableContainer,
  TableHead,
  TableRow,
  Select,
  Pagination,
  Stack,
  Grid,
  Popover,
  TextField,
  IconButton,
} from "@mui/material";
import MenuItem from "@mui/material/MenuItem";
import TableSortLabel from "@mui/material/TableSortLabel";
import FilterListRoundedIcon from "@mui/icons-material/FilterListRounded";
import CheckIcon from "@mui/icons-material/Check";
import AutorenewIcon from "@mui/icons-material/Autorenew";
import ModalDetailingPacking from "../components/ModalDetailingPacking";
import ListRoundedIcon from "@mui/icons-material/ListRounded";
import { createRoot } from "react-dom/client";
import ConfirmationPackingModal from "../components/ModalPackingConfirmation";
import Moment from "dayjs";

const ListItem = styled("li")(({ theme }) => ({
  margin: theme.spacing(0.5),
}));
/**
 *  @autor [Mateus Spengler]
 * - *English* Variables for component styling
 * - *Português* Variaveis para estilização de componentes
 */
const StyledTableCell = styled(TableCell)(({ theme }) => ({
  [`&.${tableCellClasses.head}`]: {
    backgroundColor: "#15191C",
    color: theme.palette.common.white,
  },
  [`&.${tableCellClasses.body}`]: {
    fontSize: 14,
  },
}));

const StyledTableRow = styled(TableRow)(({ theme }) => ({
  "&:nth-of-type(odd)": {
    backgroundColor: theme.palette.action.hover,
  },
  "&:last-child td, &:last-child th": {
    border: 0,
  },
}));

/**
 * - *English* Object for header definition
 * - *Português* Objeto para definição do cabeçalho
 */
const columns = [
  {
    label: "Comex",
    type: "text",
    value: "comex",
    width: "5%",
    align: "left",
    isOrder: "true",
    isFilter: "true",
    maxLength: "10",
    isNumber: true,
    columnSpan: 1,
  },
  {
    label: "Buyer",
    type: "text",
    value: "buyer",
    width: "10%",
    align: "left",
    isOrder: "true",
    isFilter: "true",
    maxLength: "60",
    isNumber: false,
    columnSpan: 1,
  },
  {
    label: "Warehouse",
    type: "text",
    value: "warehouse",
    width: "10%",
    align: "left",
    isOrder: "true",
    isFilter: "true",
    maxLength: "60",
    isNumber: false,
    columnSpan: 1,
  },
  {
    label: "Sample",
    type: "text",
    value: "sampleIndicator",
    width: "3%",
    align: "left",
    isOrder: "true",
    isFilter: "false",
    maxLength: "2",
    isNumber: true,
    columnSpan: 1,
  },
  {
    label: "Receive Date",
    type: "date",
    value: "receiveDate",
    width: "7%",
    align: "left",
    isOrder: "true",
    isFilter: "false",
    maxLength: "60",
    isNumber: false,
    columnSpan: 1,
  },
  {
    label: "Send Date",
    type: "date",
    value: "sedDate",
    width: "5%",
    align: "left",
    isOrder: "true",
    isFilter: "false",
    maxLength: "10",
    isNumber: false,
    columnSpan: 1,
  },
  {
    label: "Gross Weight (lb)",
    type: "text",
    value: "totalGrossWeight",
    width: "10%",
    align: "left",
    isOrder: "true",
    isFilter: "false",
    maxLength: "10",
    isNumber: true,
    columnSpan: 1,
  },
  {
    label: "Net Weight (lb)",
    type: "text",
    value: "totalNetWeight",
    width: "10%",
    align: "left",
    isOrder: "true",
    isFilter: "false",
    maxLength: "10",
    isNumber: true,
    columnSpan: 1,
  },
  {
    label: "Quantity",
    type: "text",
    value: "boxTotalQuantity",
    width: "1%",
    align: "center",
    isOrder: "true",
    isFilter: "false",
    maxLength: "10",
    isNumber: true,
    columnSpan: 1,
  },
  {
    label: "CubeMeter",
    type: "text",
    value: "totalCubeMeter",
    width: "1%",
    align: "center",
    isOrder: "true",
    isFilter: "false",
    maxLength: "10",
    isNumber: true,
    columnSpan: 1,
  },
  {
    label: "Action",
    type: "",
    value: "Action",
    width: "0.5%",
    align: "center",
    isOrder: "false",
    isFilter: "false",
    maxLength: "",
    columnSpan: 2,
  },
];

/**
 * - *English* General component for creating the warehouse list
 * - *Português* Componente geral para a criação da lista de armazém
 * - @return Warehouses list
 */
export default function Packing() {
  /**
   * - *English* Variable state control functions
   * - *Português* Funções de controle de estado das variaveis
   */

  const [packings, setPackings] = useState([]);
  const [labelPopover, setLabelPopover] = useState("");
  const [columnPopover, setColumnPopover] = useState("");
  const [valuePopover, setValuePopover] = useState("");
  const [labelFilter, setLabelFilter] = useState("");
  const [typePopover, setTypePopover] = useState("");
  const [orderBy, setOrderBy] = useState("sendDate");
  const [sort, setSort] = useState("desc");
  const [pageList, setPageList] = useState(1);
  const [page, setPage] = useState(1);
  const [changed, setChanged] = useState("");
  const [rowsPerPage, setRowsPerPage] = useState(10);
  const [situation, setSituation] = useState(0);
  const [anchorEl, setAnchorEl] = useState(null);
  const [maxLegthPopover, setMaxLegthPopover] = useState(10);
  const [chipData, setChipData] = useState([]);
  const [isNumber, setIsNumber] = useState();

  /**
   * - *English* Variable to reset the filters
   * - *Português* Variável para resetar os filtros
   */

  const handClickResetList = () => {
    setChipData([]);
    setLabelFilter("");
    setValuePopover("");
    setPage(1);
    setSituation(0);
    setRowsPerPage(10);
    setOrderBy("");
  };

  /**
   * - *English* Variable to assign the Popover position
   * - *Português* Variável para atribuir a posição do Popover
   */
  const openPopover = Boolean(anchorEl);

  /**
   * - *English* Variable to assign to Popover style
   * - *Português* Variável para atribuir a estilo do Popover
   */
  const id = openPopover ? "simple-popover" : undefined;

  /**
   * - *English* Function to open and assign variables in Popover
   * - *Português* Função para abrir e atribuir variaveis no Popover
   * - @param event @param label @param column @param type
   */
  const handleClickPopover = (
    event,
    label,
    column,
    type,
    maxLength,
    number
  ) => {
    setAnchorEl(event);
    setLabelPopover(label);
    setColumnPopover(column);
    setTypePopover(type);
    setMaxLegthPopover(maxLength);
    setIsNumber(number);
  };

  /**
   * - *English* Function to assign the filter field to a state variable
   * - *Português* Função para atribuir o campo do filtro a uma variavel de estado
   * - @param event
   */
  const handleChangePopover = (event) => {
    setValuePopover(event.target.value);
  };

  const handleChangeNumberPopover = (event) => {
    event.target.value = event.target.value.replace(/[^0-9,]/g, "");
    setValuePopover(event.target.value);
  };

  /**
   * - *English* Function to assign the table column field to a state variable and close the Popover
   * - *Português* Função para atribuir o campo da columa da tabela a uma variavel de estado e fechar o Popover
   */
  const handleConfirmPopover = () => {
    setAnchorEl(null);
    setChipData((chips) =>
      chips.filter((chip) => chip.labelFilter !== labelPopover)
    );
    setChipData((prevState) => [
      ...prevState,
      {
        labelFilter: labelPopover,
        columnPopover: columnPopover,
        valueFilter: valuePopover,
      },
    ]);
    setPage(1);
    setChanged(!changed);
  };

  const keyPress = (e) => {
    if (e.keyCode === 13) {
      handleConfirmPopover();
    }
  };

  /**
   * - *English* Function to close the Popover
   * - *Português* Função para fechar o Popover
   */
  const handleClosePopover = () => {
    setAnchorEl(null);
  };

  /**
   * - *English* Function to delete chip itens
   * - *Português* Função para deletar itens no chip
   */
  const handleDelete = (chipToDelete) => () => {
    setChipData((chips) =>
      chips.filter((chip) => chip.labelFilter !== chipToDelete.labelFilter)
    );
  };

  const handleChangeEdit = () => {
    setChanged(!changed);
  };

  /**
   * - *English* Function to pagination
   * - *Português* Função para paginação
   * - @param event
   */
  const handleChangeRowsPerPage = (event) => {
    setRowsPerPage(+event.target.value);
    setPage(1);
  };

  /**
   * - *English* Function to pagination
   * - *Português* Função para paginação
   * - @param event @param value
   */
  const handleChangePage = (event, value) => {
    setPage(value);
  };

  /**
   * - *English* Function to sort in ascending/descending order
   * - *Português* Função para ordenar de forma crescente/decrecente
   * - @param event @param isOrder
   */
  const handleOrderBy = (value, isOrder) => {
    if (isOrder === "true") {
      if (orderBy === value) {
        setOrderBy(value);
        setSort(sort === "asc" ? "desc" : "asc");
      } else {
        setOrderBy(value);
        setSort("asc");
      }
    }
    setPage(1);
  };

  const openModalConfirmationPacking = (evt, packingId, packingCode, index) => {
    evt.preventDefault();
    const container = document.getElementById(`confirm${index}`);
    const root = createRoot(container);
    return root.render(
      <ConfirmationPackingModal
        packingCode={packingCode}
        isOpen={true}
        packingId={packingId}
        parentCallback={handleChangeEdit}
      />
    );
  };

  const convertDate = (originalDate) => {
    if (originalDate != null) {
      return <> {Moment(originalDate).format("MM/DD/YYYY")} </>;
    }
  };

  /**
   * - *English* This function is responsible for sending a JSON to the backend and will handle the response sent by it, through an asynchronous function.
   *    If this return is successful will return the bank information if not it will be empty.
   * - *Português* Esta função  tem a responsabilidade de enviar um JSON para o backend e tratará da resposta enviada por ele, por meio de uma função assíncrona. Se esse retorno for bem sucedido
   *    retornara as informação do banco se não ficará vazio
   */
  /**
   * - *English* This function is responsible for sending a JSON to the backend and will handle the response sent by it, through an asynchronous function.
   *    If this return is successful will return the bank information if not it will be empty.
   * - *Português* Esta função  tem a responsabilidade de enviar um JSON para o backend e tratará da resposta enviada por ele, por meio de uma função assíncrona. Se esse retorno for bem sucedido
   *    retornara as informação do banco se não ficará vazio
   */
  useEffect(() => {
    // setLoading(true);
    document.title = "Lince Tech Micro ERP | Packing management";
    const getPackings = async () => {
      const PagedPacking = await packingUseCases.listPacking(
        page,
        rowsPerPage,
        orderBy,
        sort,
        chipData
      );
      return PagedPacking;
    };
    getPackings().then((response) => {
      setPackings(response.packings ?? []);
      setPageList(response.numberPages ?? 0);
      // timeOutSpinner();
      // setLoading(false);
    });
  }, [
    page,
    rowsPerPage,
    changed,
    situation,
    orderBy,
    sort,
    labelFilter,
    chipData,
  ]);
  const openModalDetailingPacking = (evt, packingId, index) => {
    evt.preventDefault();
    const container = document.getElementById(`view${index}`);
    const root = createRoot(container);
    return root.render(
      <ModalDetailingPacking isOpenDetails={true} packingId={packingId} />
    );
  };

  return (
    <Box
      sx={{
        display: "flex",
        marginLeft: "3rem",
        marginTop: "3rem",
        marginRight: "2rem",
      }}
    >
      <Box sx={{ width: "100%" }}>
        <Typography sx={{ fontSize: "26pt", fontWeight: "800" }}>
          Packing
        </Typography>

        <Box
          sx={{
            minWidth: "100%",
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
            marginTop: "0.5rem",
          }}
        >
          <Box sx={{ display: "flex" }}>
            <Box
              sx={{
                display: "flex",
                justifyContent: "center",
                flexWrap: "nowrap",
                listStyle: "none",
                p: 0,
                m: 0,
                border: "none",
                height: "4rem",
                alignItems: "center",
              }}
            >
              {chipData.map((data) => {
                return (
                  <ListItem key={data.valueFilter}>
                    <Tooltip title={data.labelFilter} placement="bottom" arrow>
                      <Chip
                        sx={{
                          textOverFlow: "ellipsis",
                          overFlow: "hidden",
                          whiteSpace: "nowrap",
                          maxWidth: "145px",
                        }}
                        color="primary"
                        variant="outlined"
                        label={data.valueFilter}
                        onDelete={handleDelete(data)}
                      />
                    </Tooltip>
                  </ListItem>
                );
              })}
            </Box>
            {chipData.length === 0 ? (
              <></>
            ) : (
              <Button onClick={handClickResetList}>Clear All</Button>
            )}
          </Box>
        </Box>
        <Paper sx={{ width: "100%", overflow: "hidden", marginTop: "0.5rem" }}>
          <TableContainer component={Paper}>
            <Table aria-label="Packing Table" sx={{ miWidth: 1300 }}>
              <TableHead>
                <TableRow>
                  {columns.map((key) => (
                    <StyledTableCell
                      colSpan={key.columnSpan}
                      sx={{
                        width: key.width,
                        columnSpan: key.columnSpan,
                        textAlign: key.align,
                      }}
                      key={key.value}
                    >
                      {key.isOrder === "true" && (
                        <Grid
                          container
                          justifyContent={"space-between"}
                          flexWrap={"nowrap"}
                        >
                          <TableSortLabel
                            sx={{
                              "&.MuiTableSortLabel-root": {
                                color: "white",
                              },
                              "&.MuiTableSortLabel-root:hover": {
                                color: "white",
                              },
                              "&.Mui-active": {
                                color: "white",
                              },
                              "& .MuiTableSortLabel-icon": {
                                color: "white !important",
                              },
                              textAlign: "center",
                            }}
                            active={orderBy === key.value}
                            direction={sort}
                            onClick={() =>
                              handleOrderBy(key.value, key.isOrder)
                            }
                          >
                            {key.label}
                          </TableSortLabel>
                          {key.isFilter === "true" && (
                            <FilterListRoundedIcon
                              aria-describedby={id}
                              variant="contained"
                              onClick={(e) =>
                                handleClickPopover(
                                  e.currentTarget,
                                  key.label,
                                  key.value,
                                  key.type,
                                  key.maxLength,
                                  key.isNumber
                                )
                              }
                              sx={{
                                width: "18px",
                                justifySelf: "end",
                                cursor: "pointer",
                              }}
                            />
                          )}
                        </Grid>
                      )}
                      {key.isOrder === "false" && <Box>{key.label}</Box>}
                    </StyledTableCell>
                  ))}
                </TableRow>
              </TableHead>
              <TableBody>
                {packings?.map((key, index) => (
                  <StyledTableRow key={index}>
                    <StyledTableCell size="small" align={"left"}>
                      {key.comex}
                    </StyledTableCell>
                    <StyledTableCell size="small" align={"left"}>
                      {key.buyer}
                    </StyledTableCell>
                    <StyledTableCell size="small" align={"left"}>
                      {key.warehouse !== null ? key.warehouse.description : ""}
                    </StyledTableCell>
                    <StyledTableCell size="small" align={"left"}>
                      {key.sampleIndicator === true ? "Yes" : "No"}
                    </StyledTableCell>
                    <StyledTableCell size="small" align={"left"}>
                      {convertDate(key.receiveDate)}
                    </StyledTableCell>
                    <StyledTableCell size="small" align={"left"}>
                      {convertDate(key.sendDate)}
                    </StyledTableCell>
                    <StyledTableCell size="small" align={"left"}>
                      {key.totalGrossWeight.toFixed(2)}
                    </StyledTableCell>
                    <StyledTableCell size="small" align={"left"}>
                      {key.totalNetWeight.toFixed(2)}
                    </StyledTableCell>
                    <StyledTableCell size="small" align={"left"}>
                      {key.boxTotalQuantity}
                    </StyledTableCell>
                    <StyledTableCell size="small" align={"left"}>
                      {new Intl.NumberFormat("en-US", {
                        minimumFractionDigits: 3,
                        maximumFractionDigits: 3,
                      }).format(key.cubeMeter)}
                    </StyledTableCell>
                    <StyledTableCell size="small" align={"center"}>
                      {key.receiveDate === null ? (
                        <Tooltip title="Confirm receive" placement="left">
                          <IconButton
                            color="primary"
                            onClick={(evt) =>
                              openModalConfirmationPacking(
                                evt,
                                key.uuid,
                                key.comex,
                                index
                              )
                            }
                          >
                            <AutorenewIcon />
                          </IconButton>
                        </Tooltip>
                      ) : (
                        <Tooltip title="Receipt" placement="left">
                          <CheckIcon color="success" />
                        </Tooltip>
                      )}
                      <input type="hidden" id={`confirm${index}`} />
                    </StyledTableCell>
                    <StyledTableCell size="small" align={"center"}>
                      <Tooltip title="Details" placement="left">
                        <IconButton
                          color="default"
                          onClick={(evt) =>
                            openModalDetailingPacking(evt, key.uuid, index)
                          }
                        >
                          <ListRoundedIcon sx={{ cursor: "pointer" }} />
                        </IconButton>
                      </Tooltip>
                      <input type="hidden" id={`view${index}`} />
                    </StyledTableCell>
                  </StyledTableRow>
                ))}
              </TableBody>
            </Table>
          </TableContainer>
        </Paper>
        <Box
          display={"flex"}
          justifyContent={"end"}
          justifyItems={"center"}
          sx={{ marginTop: "10px", alignItems: "center", gap: "15px" }}
        >
          <Typography sx={{ align: "center", fontSize: "11pt" }}>
            Rows Per Page
          </Typography>
          <Select
            sx={{ height: "35px" }}
            labelId="demo-simple-select-label"
            id="demo-simple-select"
            autoWidth
            value={rowsPerPage}
            label="Rows"
            onChange={handleChangeRowsPerPage}
          >
            <MenuItem value={5}>5</MenuItem>
            <MenuItem value={10}>10</MenuItem>
            <MenuItem value={15}>15</MenuItem>
          </Select>

          <Stack spacing={2}>
            <Pagination
              count={pageList}
              page={page}
              onChange={handleChangePage}
            />
          </Stack>
        </Box>
      </Box>

      <Popover
        id={id}
        open={openPopover}
        anchorEl={anchorEl}
        onClose={handleClosePopover}
        anchorOrigin={{
          vertical: "bottom",
          horizontal: "left",
        }}
      >
        <Box
          sx={{
            display: "flex",
            alignContent: "center",
            alignItems: "center",
            p: 2,
            gap: 2,
          }}
        >
          <Typography>Filter</Typography>
          <TextField
            type={typePopover}
            inputProps={{ maxLength: maxLegthPopover }}
            variant="outlined"
            placeholder={labelPopover}
            onChange={
              isNumber ? handleChangeNumberPopover : handleChangePopover
            }
            size="small"
            onKeyDown={keyPress}
          ></TextField>
          <Button variant="outlined" onClick={handleConfirmPopover}>
            Confirm
          </Button>
        </Box>
      </Popover>
    </Box>
  );
}
