import React, { useState } from "react";
import { Box, Button, TextField, Typography } from "@mui/material";
import CheckCircleIcon from "@mui/icons-material/CheckCircle";
import AuthenticationUseCase from "../../usecases/authentication_usecase";
import { Link, useLocation, useNavigate } from "react-router-dom";
import "./ResetPassword.css";
import { useEffect } from "react";

function useQuery() {
  const { search } = useLocation();
  return React.useMemo(() => new URLSearchParams(search), [search]);
}

function ResetPassword() {
  const navigate = useNavigate();
  const query = useQuery();
  const [email, setEmail] = useState("");
  const [emailError, setEmailError] = useState("");

  const handleEmailInput = (event) => {
    setEmail(event.target.value);
    if (emailError) {
      setEmailError("");
    }
  };

  const submit = async (event) => {
    event.preventDefault();
    try {
      await AuthenticationUseCase.resetPassword(email);
      navigate("/ResetPassword?step=2");
    } catch (errors) {
      errors.forEach((error) => {
        if (error.code === "INVALID_EMAIL") {
          setEmailError(error.message);
        }
      });
    }
  };

  useEffect(() => {
    document.title = 'Lince Tech Micro ERP | Reset Password'
  }, [])

  return (
    <Box className="reset-password-view">
      <Box sx={{ width: "350px" }}>
        {query.get("step") == 1 ? (
          <Box>
            <Typography component="h1" variant="h4">
              Reset password
            </Typography>
            <Box component="form" onSubmit={submit} noValidate sx={{ mt: 1 }}>
              <fieldset className="fieldset">
                <Typography component="legend" marginBottom="1rem">
                  Enter the email address associated with your account and we'll
                  send you a link to reset your password.
                </Typography>
                <Typography component="legend" marginBottom="1rem">
                  If you don't have an email, contact an administrator.
                </Typography>
                <TextField
                  name="email"
                  type="text"
                  label="Email"
                  variant="standard"
                  autoFocus
                  required
                  error={Boolean(emailError.length)}
                  helperText={emailError}
                  value={email}
                  onInput={handleEmailInput}
                />
                <Button
                  type="submit"
                  id="contained-button"
                  variant="contained"
                  color="primary"
                >
                  Send email
                </Button>
              </fieldset>
            </Box>
          </Box>
        ) : (
          <Box>
            <Box
              sx={{
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
                gap: "1rem",
              }}
            >
              <CheckCircleIcon sx={{ width: "100px", height: "100px" }} />
              <Typography component="legend" marginBottom="1rem">
                Email sent.
              </Typography>
            </Box>
            <Typography
              component="legend"
              marginBottom="1rem"
              textAlign="center"
            >
              Please check your inbox and click in the received link to reset
              your password.
            </Typography>
            <Box
              sx={{
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
                gap: "1rem",
              }}
            >
              <Button
                type="button"
                id="contained-button"
                variant="contained"
                color="primary"
                sx={{ width: "100%" }}
                onClick={() => navigate("/")}
              >
                Login
              </Button>
              <Typography component="span" marginBottom="1rem">
                Didn't received the link?{" "}
                <Link to="/ResetPassword?step=1">Resend</Link>
              </Typography>
            </Box>
          </Box>
        )}
      </Box>
    </Box>
  );
}

export default ResetPassword;
