import {
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  FormControl,
  InputLabel,
  MenuItem,
  Select,
  Typography,
} from "@mui/material";
import { Box } from "@mui/system";
import { useEffect, useState } from "react";
import { stockUseCases } from "../usecases/StockUseCases";
import Swal from "sweetalert2";
import * as React from "react";

const ModalStockExcel = ({ isOpenDetails }) => {
  const [open, setOpen] = React.useState(isOpenDetails);
  const [warehouse, setWarehouses] = useState([]);
  const [warehouseSelected, setWarehouseSelected] = useState("");

  const handleClose = () => {
    setOpen(false);
  };

  useEffect(() => {
    const getWarehouses = async () => {
      const PagedWarehouse = await stockUseCases.getWarehouse();
      return PagedWarehouse;
    };
    getWarehouses().then((response) => {
      setWarehouses(response.warehouse);
    });
  }, []);

  const handleChangeWarehouse = (evt) => {
    setWarehouseSelected(evt.target.value);
  };

  const handleExportExcel = async () => {
    const getStockExcel = async () => {
      const response = await stockUseCases.getStockExcel(warehouseSelected);
      return response;
    };
    getStockExcel().then((response) => {
      if (response instanceof Map) {
        return Swal.fire({
          icon: "warning",
          text: response.get("error"),
        });
      }
      if (response.data.length === 0) {
        return Swal.fire({
          icon: "info",
          title: "Couldn't generate excel",
          text: "The selected warehouse is empty",
        });
      }
      if (response.data.length > 0) {
        createExcel(response);
      }
    });
  };

  const createExcel = (values) => {
    console.log(values);
    var iframe = document.createElement("iframe");
    iframe.setAttribute("id", "ifram-table");
    iframe.setAttribute("style", "display:none");
    document.body.appendChild(iframe);
    var tableText = "<meta content='text/html; charset=utf-8'>";
    tableText += "<table border=0 cellspacing=0 cellpadding=0>";
    tableText += "  <tr>";
    tableText += "    <td>Box number</td>";
    tableText += "    <td>Box quantity</td>";
    tableText += "    <td>Color description</td>";
    tableText += "    <td>Color numeric code</td>";
    tableText += "    <td>Packing</td>";
    tableText += "    <td>Packing quantity</td>";
    tableText += "    <td>Product code</td>";
    tableText += "    <td>Product description</td>";
    tableText += "    <td>Situation</td>";
    tableText += "  </tr>";
    for (let value of values.data) {
      tableText += "    <tr>";
      tableText += `      <td>${value?.boxNumber ?? ''}</td>`;
      tableText += `      <td>${value?.boxQuantity ?? ''}</td>`;
      tableText += `      <td>${value?.colorDescription ?? ''}</td>`;
      tableText += `      <td>${value?.colorNumericCode ?? ''}</td>`;
      tableText += `      <td>${value?.packing ?? ''}</td>`;
      tableText += `      <td>${value?.packingQuantity ?? ''}</td>`;
      tableText += `      <td>${value?.productCode ?? ''}</td>`;
      tableText += `      <td>${value?.productDescription ?? ''}</td>`;
      tableText += `      <td>${value?.alreadyRequested ? 'Requested' : 'In stock'}</td>`;
      tableText += "    </tr>";
    }
    tableText += "</table>";
    tableText.replace(/<a[^>]*>|<\/a > /g, "");
    tableText.replace(/<img[^>]*>/gi, "");
    tableText.replace(/<input[^>]*>|<\/input > /gi, "");

    var a = document.createElement("a");
    a.href = "data:application/vnd.ms-excel," + encodeURIComponent(tableText);
    for (let value of warehouse) {
      if (warehouseSelected === value.id) {
        a.download = `stock_${value.description.toLowerCase()}.xls`;
      }
    }
    a.click();
    handleClose();
    return;
  };

  return (
    <Dialog open={open} onClose={handleClose} maxWidth="sm" fullWidth>
      <DialogTitle>
        <Box
          sx={{
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
          }}
        >
          <Typography
            sx={{
              fontSize: "1.2em",
              fontWeight: "700",
              color: "#363636",
            }}
          >
            Export to Excel
          </Typography>
        </Box>
      </DialogTitle>
      <DialogContent
        sx={{ height: "11vh", display: "flex", alignItems: "center" }}
      >
        <Box
          sx={{
            width: "100%",
            display: "flex",
            alignItems: "center",
            justifyContent: "space-between",
          }}
        >
          <FormControl sx={{ width: "100%" }}>
            <InputLabel id="id-warehouse-selected-modal-stock-excel">
              Select an warehouse
            </InputLabel>
            <Select
              labelId="id-warehouse-selected-modal-stock-excel"
              label="Select an warehouse"
              value={warehouseSelected}
              onChange={handleChangeWarehouse}
            >
              {warehouse.map((key, index) => {
                return (
                  <MenuItem key={index} value={key.id}>
                    {key.code} - {key.description}
                  </MenuItem>
                );
              })}
            </Select>
          </FormControl>
        </Box>
      </DialogContent>
      <DialogActions>
        <Box
          sx={{
            width: "100%",
            display: "flex",
            m: "1rem",
          }}
        >
          <Box
            sx={{
              width: "100%",
              display: "grid",
              gridGap: "1rem",
              gridTemplateColumns: "repeat(auto-fill, minmax(150px, 1fr))",
              direction: "rtl",
            }}
          >
            <Button variant="contained" onClick={handleExportExcel}>
              Excel
            </Button>
            <Button variant="outlined" color="error" onClick={handleClose}>
              Close
            </Button>
          </Box>
        </Box>
      </DialogActions>
    </Dialog>
  );
};

export default ModalStockExcel;
