import {
  Box,
  Button,
  FormControlLabel,
  Grid,
  MenuItem,
  Pagination,
  Paper,
  Popover,
  Select,
  Stack,
  styled,
  Switch,
  Table,
  TableBody,
  TableCell,
  tableCellClasses,
  TableContainer,
  TableHead,
  TableRow,
  TableSortLabel,
  TextField,
  Typography,
} from "@mui/material";

import FilterListRoundedIcon from "@mui/icons-material/FilterListRounded";
import EditRoundedIcon from "@mui/icons-material/EditRounded";
import LibraryAddRoundedIcon from "@mui/icons-material/LibraryAddRounded";
import LoopIcon from "@mui/icons-material/Loop";
import Chip from "@mui/material/Chip";
import Tooltip from "@mui/material/Tooltip";

import { useEffect, useState } from "react";

import ModalUser from "../components/ModalUser";
import { userUseCase } from "../usecases/UserUseCase";
import { createRoot } from "react-dom/client";

const ListItem = styled("li")(({ theme }) => ({
  margin: theme.spacing(0.5),
}));

// STYLES
const StyledTableCell = styled(TableCell)(({ theme }) => ({
  [`&.${tableCellClasses.head}`]: {
    backgroundColor: "#15191C",
    color: theme.palette.common.white,
  },
  [`&.${tableCellClasses.body}`]: {
    fontSize: 14,
  },
}));

const StyledTableRow = styled(TableRow)(({ theme }) => ({
  "&:nth-of-type(odd)": {
    backgroundColor: theme.palette.action.hover,
  },

  // hide last border
  "&:last-child td, &:last-child th": {
    border: 0,
  },
}));

const columns = [
  {
    label: "Name",
    value: "name",
    width: "18%",
    isOrder: "true",
    isActive: "true",
    maxLength: "60",
  },
  {
    label: "E-mail",
    value: "email",
    width: "18%",
    isOrder: "true",
    isActive: "true",
    maxLength: "60",
  },
  {
    label: "User Type",
    value: "type",
    width: "9%",
    isOrder: "true",
    isActive: "true",
    maxLength: "10",
  },
  {
    label: "Auth. Record",
    value: "authenticationRecord",
    width: "4%",
    isOrder: "true",
    isActive: "true",
    maxLength: "30",
  },
  {
    label: "Phone",
    value: "phone",
    width: "15%",
    isOrder: "true",
    isActive: "true",
    maxLength: "20",
  },
  {
    label: "Situation",
    value: "situation",
    width: "4%",
    isOrder: "true",
    isActive: "false",
    maxLength: "10",
  },
  {
    label: "Action",
    value: "action",
    width: "4%",
    isOrder: "false",
    isActive: "true",
    maxLength: "5",
  },
];

export default function User() {
  const [users, setUsers] = useState([]);

  const [pageList, setPageList] = useState(0);
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(10);

  const [orderBy, setOrderBy] = useState("");
  const [sort, setSort] = useState("desc");
  const [checked, setChecked] = useState(true);
  const [uuidUserToEdit, setUuidUserToEdit] = useState("");
  const [openModal, setOpenModal] = useState(false);
  const [changed, setChanged] = useState("");
  const [maxLegthPopover, setMaxLegthPopover] = useState(10);

  // POPOVER
  const [anchorEl, setAnchorEl] = useState(null);
  const openPopover = Boolean(anchorEl);
  const id = openPopover ? "simple-popover" : undefined;

  const [labelPopover, setLabelPopover] = useState("");
  const [columnPopover, setColumnPopover] = useState("");
  const [typePopover, setTypePopover] = useState("");
  const [labelFilter, setLabelFilter] = useState("");
  const [valuePopover, setValuePopover] = useState("");

  const [chipData, setChipData] = useState([]);

  const handleDelete = (chipToDelete) => () => {
    setChipData((chips) =>
      chips.filter((chip) => chip.labelFilter !== chipToDelete.labelFilter)
    );
  };

  const handClickResetList = (event) => {
    setChipData([]);
    setLabelFilter("");
    setValuePopover("");
    setPage(1);
    setRowsPerPage(10);
    setOrderBy("");
  };

  const handleClickPopover = (event, label, column, type, maxLength) => {
    setAnchorEl(event);
    setLabelPopover(label);
    setColumnPopover(column);
    setTypePopover(type);
    setMaxLegthPopover(maxLength);
  };

  /**
   * - *English* Function to assign the filter field to a state variable
   * - *Português* Função para atribuir o campo do filtro a uma variavel de estado
   * - @param event
   */
  const handleChangePopover = (event) => {
    setValuePopover(event.target.value);
  };

  /**
   * - *English* Function to assign the table column field to a state variable and close the Popover
   * - *Português* Função para atribuir o campo da columa da tabela a uma variavel de estado e fechar o Popover
   */
  const handleConfirmPopover = () => {
    setAnchorEl(null);
    setChipData((chips) =>
      chips.filter((chip) => chip.labelFilter !== labelPopover)
    );
    setChipData((prevState) => [
      ...prevState,
      {
        labelFilter: labelPopover,
        columnPopover: columnPopover,
        valueFilter: valuePopover,
      },
    ]);
    setPage(1);
    setChanged(!changed);
  };

  const keyPress = (e) => {
    if (e.keyCode === 13) {
      handleConfirmPopover();
    }
  };

  const handleClosePopover = () => {
    setAnchorEl(null);
  };

  const handleChangePage = (event, value) => {
    setPage(value);
  };

  const handleChangeRowsPerPage = (event) => {
    setRowsPerPage(+event.target.value);
    setPage(1);
  };

  const handleChange = () => {
    setChecked(!checked);
  };

  const handleOrderBy = (value, isOrder) => {
    if (isOrder === "true") {
      if (orderBy === value) {
        setOrderBy(value);
        setSort(sort === "asc" ? "desc" : "asc");
      } else {
        setOrderBy(value);
        setSort("asc");
      }
    }
  };

  useEffect(() => {
    document.title = "Lince Tech Micro ERP | Users management";
    const getUsers = async () => {
      const pagedUser = await userUseCase.getUsers(
        page,
        rowsPerPage,
        orderBy,
        sort,
        chipData,
        checked
      );
      setUsers(pagedUser.users);
      setPageList(pagedUser.numberOfPages);
    };

    getUsers();
  }, [
    page,
    pageList,
    orderBy,
    sort,
    rowsPerPage,
    labelFilter,
    checked,
    chipData,
    openModal,
    changed
  ]);

  const handleChangeList = () => {
    setChanged(!changed);
  }

  const handleOpenModalUser = (evt, userUUID) => {
    evt.preventDefault();
    const container = document.getElementById("modal-user");
    const root = createRoot(container);
    return root.render(
      <ModalUser
        userUUID={userUUID}
        isOpen={true}
        parentCallback={handleChangeList}
      />
    );
  };

  return (
    <Box sx={{ display: "flex" }}>
      <input type="hidden" id="modal-user" />
      <Box sx={{ width: "100%", marginRight: "2rem" }}>
        <Typography
          sx={{
            fontSize: "26pt",
            fontWeight: "800",
            marginLeft: "3rem",
            marginTop: "3rem",
          }}
        >
          Users
        </Typography>
        <Box
          display={"flex"}
          justifyContent={"space-between"}
          justifyItems={"center"}
          sx={{ marginLeft: "3rem", marginTop: "0.5rem" }}
        >
          <Box sx={{ display: "flex" }}>
            <Box
              sx={{
                display: "flex",
                justifyContent: "center",
                flexWrap: "wrap",
                listStyle: "none",
                p: 0,
                m: 0,
                border: "none",
              }}
              component="ul"
            >
              {chipData.map((data) => {
                return (
                  <ListItem key={data.valueFilter}>
                    <Tooltip title={data.labelFilter} arrow>
                      <Chip
                        sx={{
                          textOverFlow: "ellipsis",
                          overFlow: "hidden",
                          whiteSpace: "nowrap",
                          maxWidth: "145px",
                        }}
                        color="primary"
                        variant="outlined"
                        label={data.valueFilter}
                        onDelete={handleDelete(data)}
                      />
                    </Tooltip>
                  </ListItem>
                );
              })}
            </Box>
            {chipData.length === 0 ? (
              <></>
            ) : (
              <Button onClick={handClickResetList}>Clear All</Button>
            )}
          </Box>
          <Box
            sx={{
              display: "flex",
              alignItems: "center",
              justifyContent: "space-between",
            }}
          >
            <FormControlLabel
              sx={{ align: "left", fontSize: "11pt" }}
              control={
                <Switch
                  onChange={handleChange}
                  checked={checked ? false : true}
                />
              }
              label="List only inactivated users"
            />
            <Button onClick={handClickResetList} title="Reset filters">
              <LoopIcon color="action" />
            </Button>

            <LibraryAddRoundedIcon
              color="action"
              sx={{ cursor: "pointer" }}
              onClick={(evt) => handleOpenModalUser(evt)}
            ></LibraryAddRoundedIcon>
          </Box>
        </Box>

        <Paper
          sx={{
            justifyContent: "center",
            marginLeft: "3rem",
            marginTop: "0.5rem",
          }}
        >
          <TableContainer component={Paper}>
            <Table aria-label="User Table" width="auto">
              <TableHead>
                <TableRow>
                  {columns.map((key) => (
                    <StyledTableCell key={key.value}>
                      <Grid
                        container
                        justifyContent={"space-between"}
                        flexWrap="nowrap"
                      >
                        <TableSortLabel
                          sx={{
                            "&.MuiTableSortLabel-root": {
                              color: "white",
                            },
                            "&.MuiTableSortLabel-root:hover": {
                              color: "white",
                            },
                            "&.Mui-active": {
                              color: "white",
                            },
                            "& .MuiTableSortLabel-icon": {
                              color: "white !important",
                            },
                          }}
                          active={orderBy === key.value}
                          direction={sort}
                          onClick={() => handleOrderBy(key.value, key.isOrder)}
                        >
                          {key.label}
                        </TableSortLabel>
                        {key.isOrder === "true" && (
                          <FilterListRoundedIcon
                            variant="contained"
                            aria-describedby={id}
                            onClick={(e) =>
                              handleClickPopover(
                                e.currentTarget,
                                key.label,
                                key.value,
                                key.type,
                                key.maxLength
                              )
                            }
                            sx={{
                              width: "18px",
                              justifySelf: "end",
                              cursor: "pointer",
                            }}
                          />
                        )}
                      </Grid>
                    </StyledTableCell>
                  ))}
                </TableRow>
              </TableHead>

              <TableBody>
                {users.map((key, index) => (
                  <StyledTableRow
                    key={index}
                    className={key.isActive}
                    sx={{ display: "table-row" }}
                  >
                    <StyledTableCell width="18%">{key.name}</StyledTableCell>
                    <StyledTableCell width="18%">{key.email}</StyledTableCell>
                    <StyledTableCell width="9%">
                      {key.userType.label}
                    </StyledTableCell>
                    <StyledTableCell width="29%">
                      {key.authenticationRecord}
                    </StyledTableCell>
                    <StyledTableCell width="18%">
                      {key.contact === ""
                        ? ""
                        : "+ (" +
                          key.contact.substring(0, 3) +
                          ") " +
                          key.contact.substring(3, 4) +
                          " " +
                          key.contact.substring(4, 9) +
                          "-" +
                          key.contact.substring(9, 13)}
                    </StyledTableCell>
                    <StyledTableCell width="4%" align="center">
                      {key.isActive === true ? "Active" : "Inative"}
                    </StyledTableCell>
                    <StyledTableCell width="4%" align="center">
                      <EditRoundedIcon
                        sx={{
                          cursor: "pointer",
                          "&:hover": { textDecoration: "none" },
                        }}
                        onClick={(evt) => handleOpenModalUser(evt, key.uuid)}
                        color="action"
                      />
                    </StyledTableCell>
                  </StyledTableRow>
                ))}
              </TableBody>
            </Table>
          </TableContainer>
        </Paper>
        <Box
          display={"flex"}
          justifyContent={"end"}
          justifyItems={"center"}
          sx={{ marginTop: "10px", alignItems: "center", gap: "15px" }}
        >
          <Typography sx={{ align: "center", fontSize: "11pt" }}>
            Rows Per Page
          </Typography>
          <Select
            sx={{ height: "35px" }}
            labelId="demo-simple-select-label"
            id="demo-simple-select"
            autoWidth
            defaultValue={10}
            label="Rows"
            value={rowsPerPage}
            onChange={handleChangeRowsPerPage}
          >
            <MenuItem value={5}>5</MenuItem>
            <MenuItem value={10}>10</MenuItem>
            <MenuItem value={15}>15</MenuItem>
          </Select>

          <Stack spacing={2}>
            <Pagination
              count={pageList}
              page={page}
              onChange={handleChangePage}
            />
          </Stack>
        </Box>
      </Box>

      <Popover
        id={id}
        open={openPopover}
        anchorEl={anchorEl}
        onClose={handleClosePopover}
        anchorOrigin={{
          vertical: "bottom",
          horizontal: "left",
        }}
      >
        <Box
          sx={{
            display: "flex",
            alignContent: "center",
            alignItems: "center",
            p: 2,
            gap: 2,
          }}
        >
          <Typography>Filter</Typography>
          <TextField
            type={typePopover}
            inputProps={{ maxLength: maxLegthPopover }}
            variant="outlined"
            placeholder={labelPopover}
            onChange={handleChangePopover}
            size="small"
            onKeyDown={keyPress}
          ></TextField>
          <Button variant="outlined" onClick={handleConfirmPopover}>
            Confirm
          </Button>
        </Box>
      </Popover>
    </Box>
  );
}
