import {
  Box,
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Tab,
  Tabs,
  Typography,
} from "@mui/material";
import { useEffect, useRef, useState } from "react";
import MenuBookRoundedIcon from "@mui/icons-material/MenuBookRounded";
import { requestHistoryUseCases } from "../../usecases/RequestHistoryUseCases";
import PropTypes from "prop-types";
import StockDetail from "./StockDetail";
import StockHistory from "./StockHistory";

function TabPanel(props) {
  const { children, value, index, ...other } = props;

  return (
    <Box
      role="tabpanel"
      hidden={value !== index}
      id={`simple-tabpanel-${index}`}
      aria-labelledby={`simple-tab-${index}`}
      {...other}
    >
      {value === index && (
        <Box sx={{ p: 4 }}>
          <Typography>{children}</Typography>
        </Box>
      )}
    </Box>
  );
}

TabPanel.propTypes = {
  children: PropTypes.node,
  index: PropTypes.number.isRequired,
  value: PropTypes.number.isRequired,
};

function a11yProps(index) {
  return {
    id: `simple-tab-${index}`,
    "aria-controls": `simple-tabpanel-${index}`,
  };
}

const ModalStockDetail = ({ isOpen, stockUUID }) => {
  const [open, setOpen] = useState(isOpen);
  const [numberSolicitation, setNumberSolicitation] = useState(0);
  const [stockTransfer, setStockTransfer] = useState({});

  const [value, setValue] = useState(0);

  const handleChange = (event, newTab) => {
    setValue(newTab);
  };

  const handleClose = () => {
    setOpen(false);
  };

  useEffect(() => {
    const getStockSolicitation = async () => {
      const response = await requestHistoryUseCases.getStockDetail(stockUUID);
      return response;
    };
    getStockSolicitation().then((response) => {
      setStockTransfer(response?.data?.stockTransfer ?? {});
      setNumberSolicitation(response?.data?.stockTransfer?.code ?? 0);
    });
  }, []);

  return (
    <Dialog
      open={open}
      onClose={handleClose}
      maxWidth="lg"
      fullWidth
      scroll="body"
    >
      <DialogTitle
        sx={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          marginTop: "1rem",
        }}
      >
        <Box sx={{ display: "flex", justifyContent: "space-between", width: "100%" }}>
          <Box sx={{display: "flex", flexDirection: "row", justifyContent: "start", width: "100%"}}>
            <Typography
              sx={{
                fontSize: "1.2em",
                fontWeight: "700",
                color: "#363636",
              }}
            >
              Request code: {numberSolicitation}
            </Typography>
          </Box>
        </Box>
        <Box sx={{ borderBottom: 1, borderColor: "divider", width: "100%" }}>
          <Tabs value={value} onChange={handleChange}>
            <Tab label="Details" {...a11yProps(0)} />
            <Tab label="History" {...a11yProps(1)} />
          </Tabs>
        </Box>
      </DialogTitle>

      <DialogContent sx={{ height: "50vh" }}>
        <TabPanel value={value} index={0}>
          <StockDetail
            stockUUID={stockUUID}
            stockTransfer={stockTransfer}
          />
        </TabPanel>
        <TabPanel value={value} index={1}>
          <StockHistory stockUUID={stockUUID} stockTransfer={stockTransfer} />
        </TabPanel>
      </DialogContent>
      <DialogActions>
        <Box
          sx={{
            display: "flex",
            justifyContent: "end",
            marginBottom: "15px",
            marginRight: "15px",
            width: "100%",
          }}
        >
          <Button variant="outlined" onClick={handleClose} color="error">
            Close
          </Button>
        </Box>
      </DialogActions>
    </Dialog>
  );
};

export default ModalStockDetail;
