import * as React from 'react';
import Button from '@mui/material/Button';
import DescriptionIcon from "@mui/icons-material/Description";
import DetailingProducts from '../components/DetailingProducts'
import DetailingSummary from '../components/DetailingSummary'
import DetailingByColor from '../components/DetailingByColor'


//dialog
import Dialog from '@mui/material/Dialog';
import DialogActions from '@mui/material/DialogActions';
import DialogContent from '@mui/material/DialogContent';
import DialogContentText from '@mui/material/DialogContentText';
import DialogTitle from '@mui/material/DialogTitle';

//tabs
import PropTypes from 'prop-types';
import Tabs from '@mui/material/Tabs';
import Tab from '@mui/material/Tab';
import Typography from '@mui/material/Typography';
import Box from '@mui/material/Box';

function TabPanel(props) {
  const { children, value, index, ...other } = props;

  return (
    <div
      role="tabpanel"
      hidden={value !== index}
      id={`simple-tabpanel-${index}`}
      aria-labelledby={`simple-tab-${index}`}
      {...other}
    >
      {value === index && (
        <Box sx={{ p: 4 }}>
          <Typography>{children}</Typography>
        </Box>
      )}
    </div>
  );
}

TabPanel.propTypes = {
  children: PropTypes.node,
  index: PropTypes.number.isRequired,
  value: PropTypes.number.isRequired,
};

function a11yProps(index) {
  return {
    id: `simple-tab-${index}`,
    'aria-controls': `simple-tabpanel-${index}`,
  };
}

export default function PackingList({ isOpenDetails, packingId }) {

  const [value, setValue] = React.useState(0);

  const handleChange = (event, newValue) => {
    setValue(newValue);
  };

  const [open, setOpen] = React.useState(isOpenDetails);
  const [scroll, setScroll] = React.useState('body');

  // const [open, setOpen] = React.useState(false);
  // const [scroll, setScroll] = React.useState('paper');
  // const handleClickOpen = () => () => {
  //   setOpen(true);
  //   setScroll("body");
  // };


  const handleClose = () => {
    setOpen(false);
  };

  const descriptionElementRef = React.useRef(null);
  React.useEffect(() => {
    if (open) {
      const { current: descriptionElement } = descriptionElementRef;
      if (descriptionElement !== null) {
        descriptionElement.focus();
      }
    }
  }, [open]);

  return (
    <div>
      {/* <EditIcon onClick={handleClickOpen("body")}></EditIcon> */}

      <Dialog
        open={open}
        onClose={handleClose}
        scroll={scroll}
        maxWidth='xl'
        fullWidth
      >
        <DialogTitle id="scroll-dialog-title">
          <Box sx={{ display: 'flex', justifyContent: 'space-between' }}>
            <Typography
              sx={{
                fontSize: "1.2em",
                fontWeight: "700",
                color: "#363636",
              }}
            >
              Packing List
            </Typography>
            <DescriptionIcon fontSize='large' />
          </Box>
          <Box sx={{ borderBottom: 1, borderColor: "divider" }}>
            <Tabs
              value={value}
              onChange={handleChange}
            >
              <Tab label="Products" {...a11yProps(0)} />
              <Tab label="Total summary" {...a11yProps(1)} />
              <Tab label="Abstract by color" {...a11yProps(2)} />
            </Tabs>
          </Box>
        </DialogTitle>
        <DialogContent sx={{ height: '74vh' }}>

          <TabPanel value={value} index={0}>
            <DetailingProducts packingId={packingId} />
          </TabPanel>
          <TabPanel value={value} index={1}>
            <DetailingSummary packingId={packingId} />
          </TabPanel>
          <TabPanel value={value} index={2}>
            <DetailingByColor packingId={packingId} />
          </TabPanel>

        </DialogContent>
        <DialogActions>
          <Box sx={{ display: 'flex', justifyContent: 'end', marginBottom: '15px', marginRight: '15px' }}>
            <Button variant="outlined" onClick={handleClose}>
              Close
            </Button>
          </Box>
        </DialogActions>
      </Dialog>
    </div>
  );
}
