import { PagedPrice } from "../entities/Entities";
import { priceRepository } from "../repositories/PriceRepositories";

class PriceUseCase {
  async postPriceTable(priceTable) {
    const errors = new Map();

    if (priceTable.name === "") {
      const errorCode = { key: "name" };
      errors.set(errorCode, "Name must not be empty");
    }

    if (priceTable.initial === null) {
      const errorCode = { key: "initial" };
      errors.set(errorCode, "Initial date must not be empty");
    }

    if (priceTable.final === null) {
      const errorCode = { key: "final" };
      errors.set(errorCode, "Final date must not be empty");
    }

    if (errors.size > 0) {
      return errors;
    }
    try {
      return await priceRepository.postPriceTable(priceTable);
    } catch (error) {
      return error;
    }
  }

  async postPriceTableProduct(
    priceTableUuid,
    priceTableProduct,
    priceTableColor,
    values
  ) {
    const errors = new Map();

    if (priceTableProduct === "") {
      const errorCode = { key: "product" };
      errors.set(errorCode, "Product must not be empty");
    }

    if (values.cost === "") {
      const errorCode = { key: "cost" };
      errors.set(errorCode, "Cost date must not be empty");
    }

    if (values.sale === "") {
      const errorCode = { key: "sale" };
      errors.set(errorCode, "Sale date must not be empty");
    }

    if (errors.size > 0) {
      return errors;
    }

    try {
      return await priceRepository.postPriceTableProduct(
        priceTableUuid,
        priceTableProduct,
        priceTableColor,
        values
      );
    } catch (error) {
      return error;
    }
  }

  /**
   * @param page {int}
   * @param rowsPerPage {int}
   * @param orderBy {string}
   * @param situation {boolen}
   * @param sort {string}
   * @param chipData {string}
   * @returns {Promise<PagedPrice>}
   */
  async listPriceTables(page, rowsPerPage, situation, orderBy, sort, chipData) {
    const response = await priceRepository.listPriceTables(
      page,
      rowsPerPage,
      orderBy,
      situation,
      sort,
      chipData
    );
    return response;
  }

  async postPriceTableInactive(priceTableUuid, situation) {
    const response = await priceRepository.postPriceTableInactive(
      priceTableUuid,
      situation
    );
    return response;
  }

  /**
   * @param priceTableId {String}
   * @returns {Object}
   */
  async getInformationPrice(priceTableId) {
    const response = await priceRepository.getInfoPriceTable(priceTableId);
    return response;
  }

  /**
   * @param priceTableId {String}
   * @returns {Object}
   */
  async listPriceTableProducts(priceTableuuid) {
    const response = await priceRepository.listPriceTableProducts(
      priceTableuuid
    );
    return response;
  }

  /**
   * @param priceTableProductUuid {String}
   * @returns {Object}
   */
  async priceTableProductRemove(priceTableProductUuid) {
    const response = await priceRepository.priceTableProductRemove(
      priceTableProductUuid
    );
    return response;
  }

  /**
   * @returns {Object}
   */
  async getProductList() {
    const response = await priceRepository.getProductList();
    return response;
  }

  /**
   * @returns {Object}
   */
  async getProductColorList(priceTableProductUuid) {
    const response = await priceRepository.getProductColorList(
      priceTableProductUuid
    );
    return response;
  }
}

export const priceUseCase = new PriceUseCase();
