import {
  Box,
  Button,
  Divider,
  FormControl,
  InputLabel,
  MenuItem,
  Modal,
  Select,
  TextField,
  Typography,
} from "@mui/material";
import { useEffect, useState } from "react";
import React from "react";
import Swal from "sweetalert2";
import { userUseCase } from "../usecases/UserUseCase";
import { Error } from "../../../shared/entities/Error";
import { User, UserType } from "../entities/Entities";
import GroupAddIcon from "@mui/icons-material/GroupAdd";
import ReactInputMask from "react-input-mask";

const userRegisterModalStyle = {
  position: "absolute",
  top: "50%",
  left: "50%",
  transform: "translate(-50%, -50%)",
  minWidth: "40%",
  backgroundColor: "#ffffff",
  borderRadius: "10px",
  boxShadow: 24,
  p: 4,
  display: "flex",
  flexDirection: "row",
  overflow: "hidden",
  outline: "none",
  flexWrap: "wrap",
};

const userSituationOption = [
  {
    value: true,
    label: "Active",
  },
  {
    value: false,
    label: "Inactive",
  },
];

const Toast = Swal.mixin({
  toast: true,
  position: "top-end",
  showConfirmButton: false,
  timer: 3000,
  timerProgressBar: true,
  didOpen: (toast) => {
    toast.addEventListener("mouseenter", Swal.stopTimer);
    toast.addEventListener("mouseleave", Swal.resumeTimer);
  },
});

const ModalUser = ({ userUUID, isOpen, parentCallback }) => {
  const [open, setOpen] = React.useState(isOpen);
  const [userObject, setUserObject] = React.useState(
    new User("", "", "", "", "", "", "", "")
  );
  const [userTypeOption, setUserTypeOption] = React.useState([]);
  const [
    authenticationRecordControllGenerateNewPassword,
    setAuthenticationRecordControllGenerateNewPassword,
  ] = React.useState("");

  const handleOnChange = (evt) => {
    const { name, value } = evt.target;
    setUserObject({
      ...userObject,
      [name]:
        name === "phone"
          ? value
              .replace("+", "")
              .replace("-", " ")
              .replace("(", "")
              .replace(")", "")
              .replace(" ", "")
              .replace(/\s/g, "")
          : value,
    });
  };

  const handleCloseModal = () => {
    setOpen(!open);
    setUserObject(new User("", "", "", "", "", "", "", ""));
  };

  React.useEffect(() => {
    const getUserType = async () => {
      return await userUseCase.getUserTypes();
    };
    getUserType()
      .then((response) => {
        setUserTypeOption(response);
      })
      .catch((error) => {
        console.log(error);
      });

    if (userUUID !== undefined) {
      const getUserInformation = async () => {
        return await userUseCase.getUserByUuid(userUUID);
      };
      getUserInformation()
        .then((response) => {
          setAuthenticationRecordControllGenerateNewPassword(
            response.authenticationRecord
          );
          setUserObject(
            new User(
              response.uuid,
              response.name,
              response.email,
              response.userType.uuid,
              response.authenticationRecord,
              response.contact,
              response.isActive
            )
          );
        })
        .catch((error) => {
          console.log(error);
        });
    }
  }, []);

  const handleRegisterUser = async () => {
    const response = await userUseCase.postUser(
      new User(
        userObject.uuid,
        userObject.name,
        userObject.email,
        new UserType(userObject.type, ""),
        userObject.authenticationRecord,
        userObject.phone,
        userObject.situation,
        ""
      )
    );
    console.log(response)
    if (response instanceof Error) {
      return Swal.fire({
        title: "Error",
        icon: "error",
        text: response.description,
        confirmButtonText: "OK",
      });
    }
    if (response instanceof User) {
      handleCloseModal();
      parentCallback(true);
      return Toast.fire({
        icon: "success",
        text: "Successfully registered",
      });
    }
  };

  const handleGenerateNewPassword = async () => {
    const response = await userUseCase.generateNewPassword(
      authenticationRecordControllGenerateNewPassword
    );
    if (response instanceof Error) {
      return Swal.fire({
        title: "Error",
        icon: "error",
        text: response.description,
        confirmButtonText: "OK",
      });
    }
    handleCloseModal();
    return Swal.fire({
      title: "Success",
      icon: "success",
      text: `New password ${response}`,
      confirmButtonText: "OK",
    });
  };

  return (
    <Modal open={open} onClose={handleCloseModal}>
      <Box sx={userRegisterModalStyle}>
        <Box
          sx={{
            display: "flex",
            justifyContent: "space-between",
            width: "100%",
          }}
        >
          <Typography
            sx={{ fontSize: "1.5rem", fontWeight: "700", color: "#363636" }}
            component="h2"
          >
            {userUUID !== undefined ? "Edit" : "Register"} User
          </Typography>
          <GroupAddIcon fontSize="large" />
        </Box>
        <Box sx={{ width: "100%", marginTop: "1rem" }}>
          <TextField
            label="Name"
            variant="standard"
            name="name"
            inputProps={{ maxLength: 60 }}
            value={userObject.name}
            onChange={(evt) => {
              handleOnChange(evt);
            }}
            fullWidth
            required
          />
        </Box>
        <Box
          sx={{
            marginTop: "1.5rem",
            width: "100%",
            display: "grid",
            gridGap: "1rem",
            gridTemplateColumns:
              "repeat(auto-fit, minmax(200px, 1fr) minmax(200px, 1fr))",
          }}
        >
          <FormControl variant="standard">
            <InputLabel id="id-usertype-form-user">User type</InputLabel>
            <Select
              labelId="id-usertype-form-user"
              name="type"
              value={userObject.type}
              onChange={(evt) => {
                handleOnChange(evt);
              }}
            >
              {userTypeOption.map((type) => {
                return (
                  <MenuItem key={type.uuid} value={type.uuid}>
                    {type.label}
                  </MenuItem>
                );
              })}
            </Select>
          </FormControl>
          <FormControl variant="standard">
            <InputLabel id="id-situatio-form-user">Situation</InputLabel>
            <Select
              labelId="id-situatio-form-user"
              value={userObject.situation}
              name="situation"
              onChange={(evt) => {
                handleOnChange(evt);
              }}
            >
              {userSituationOption.map((item, index) => {
                return (
                  <MenuItem key={index} value={item.value}>
                    {item.label}
                  </MenuItem>
                );
              })}
            </Select>
          </FormControl>
        </Box>
        <Box sx={{ width: "100%", marginTop: "1rem" }}>
          <TextField
            label="Authentication"
            variant="standard"
            name="authenticationRecord"
            value={userObject.authenticationRecord}
            onChange={(evt) => {
              handleOnChange(evt);
            }}
            fullWidth
            required
          />
        </Box>
        <Box
          sx={{
            marginTop: "1.5rem",
            width: "100%",
            display: "grid",
            gridGap: "1rem",
            gridTemplateColumns:
              "repeat(auto-fit, minmax(250px, 1fr) minmax(200px, 0.5fr))",
          }}
        >
          <TextField
            label="E-mail"
            variant="standard"
            name="email"
            value={userObject.email}
            onChange={(evt) => {
              handleOnChange(evt);
            }}
            fullWidth
          />
          <ReactInputMask
            mask="+ (999) 9 99999-9999"
            maskChar=""
            onChange={(evt) => {
              handleOnChange(evt);
            }}
            value={userObject.phone}
          >
            {() => <TextField label="Phone" variant="standard" name="phone" />}
          </ReactInputMask>
        </Box>
        <Box
          sx={{
            width: "100%",
            marginTop: "1rem",
            display: "flex",
            justifyContent: "end",
          }}
        >
          <Box
            sx={{
              marginTop: "1.5rem",
              width: "100%",
              display: "grid",
              gridGap: "1rem",
              gridTemplateColumns: "repeat(auto-fill, minmax(150px, 1fr))",
              direction: "rtl",
            }}
          >
            <Button
              onClick={() => {
                handleRegisterUser();
              }}
              variant="contained"
            >
              Register
            </Button>
            <Button onClick={handleCloseModal} variant="outlined" color="error">
              Cancel
            </Button>
            {!userObject.email && userUUID !== undefined ? (
              <Button
                variant="outlined"
                onClick={handleGenerateNewPassword}
                sx={{ width: "300px" }}
                color="success"
              >
                Genereate new password
              </Button>
            ) : (
              ""
            )}
          </Box>
        </Box>
      </Box>
    </Modal>
  );
};

export default ModalUser;
