import { ProductDetail } from "../entities/Product";
import { PagedVariant } from "../entities/Product";
import http from "../../../HttpHelper";

class ProductDetailRepository {
  /**
   *
   * @param code {int}
   * @returns {Promise<PagedProduct>}
   */

  async getProductDetail(code) {
    const response = await http.get(`/product/${code}`);

    return new ProductDetail(
      response.data.product.uuid,
      response.data.product.textCode,
      response.data.product.numericCode,
      response.data.product.description,
      response.data.product.netValue,
      response.data.product.grossValue,
      response.data.product.salesMultiple,
      response.data.product.unitOfMeasurement,
      response.data.product.cube,
      response.data.product.dun14,
      response.data.product.statusCode,
      response.data.product.instructions,
      response.data.product.technicalDescription,
      response.data.width,
      response.data.height,
      response.data.volume
    );
  }

  async getVariant(code, page, rowsPerPage) {
    const response = await http.get(
      `/variant/${code}?page=${page}&size=${rowsPerPage}`
    );
    return new PagedVariant(response.data.colors, response.data.numberPages);
  }

  async postProductInstruction(uuid, instructions, technicalDescription) {
    try{
      const response = await http.post(`/product/${uuid}/alter`, {
        instructions: `${instructions}`,
        technicalDescription: `${technicalDescription}`,
      });
      return response;
    }catch(e){
      const error = new Error("Connection error")
      return error;
    }
  }
}

export const productDetailRepository = new ProductDetailRepository();
