import { FiltersList } from "../entities/FiltersPage";
import { productRepository } from "../repositories/ProductRepository";

class ProductUseCase {
  /**
   * @param {FiltersList} filterList 
   * @returns 
   */
  async getProducts(filterList) {
    const response = await productRepository.getProducts(filterList);
    return response;
  }
  async getProductExcel(products, priceTable){
    const errors = new Map();
    if(products.length === 0){
      return errors.set("error", "You need to inform an product");
    }
    if(priceTable === ''){
      return errors.set("error", "You need to inform an price table");
    }
    return await productRepository.getProductExcel(products, priceTable);
  }
  async getProductsFromSessionStorage(){
    return await productRepository.getProductsFromSessionStorage();
  }
  async getPriceTable(){
    return await productRepository.getPriceTable();
  }
}

export const productUseCase = new ProductUseCase();
