import { PagedPrice } from "../entities/Entities";
import http from "./../../../HttpHelper";

class PriceRepository {
    /**
     * @param {int} page {int}
     * @param {int} rowsPerPage {int}
     * @param {string} orderBy {string}
     * @param {string} situation {string}
     * @param {string} sort {string}
     * @param {string} chipData {string}
     * @returns {Promise<PagedPrice>}
     */

    async listPriceTables(page, rowsPerPage, orderBy, situation, sort, chipData) {
        try {
            const filters = `${chipData.size === 0
                ? ""
                : chipData.map(
                    (data) =>
                        "&filter=(" + data.columnPopover + ":" + data.valueFilter + ")"
                )
                }`;

            const response = await http.get(
                `/priceTable?page=${page}&size=${rowsPerPage}&orderBy=${orderBy}&sortBy=${sort}&filter=(isActive:${situation})&${filters === "" ? "" : filters.replaceAll(",", "")
                }`
            );

            // return response
            return new PagedPrice(
                response.data.priceTable,
                response.data.numberPages
            );
        } catch (error) {
            console.log(`error: ${error}`);
        }
    }

    /**
    * @param {int} page {Array}
    */

    async postPriceTable(priceTable) {
        try {
            const response = await http.post("/priceTable", {
                uuid: `${priceTable.uuid === null ? "" : priceTable.uuid}`,
                code: `${priceTable.code === null ? "" : priceTable.code}`,
                name: `${priceTable.name}`,
                isActive: `${priceTable.isActive}`,
                initial: `${priceTable.initial}`,
                final: `${priceTable.final}`,
            });
            return response;
        } catch (error) {
            return error;
        }
    }

    async postPriceTableProduct(priceTableUuid, priceTableProduct, priceTableColor, values) {
        try {
            const response = await http.post(`/priceTable/${priceTableUuid}/add`, {
                product: {
                    textCode: `${priceTableProduct}`
                },
                color: { code: `${priceTableColor === '' ? null : priceTableColor}` },
                cost: `${values.cost}`,
                sale: `${values.sale}`
            });
            return response;
        } catch (error) {
            return error;
        }
    }

    /**
    * @param {int} priceTableUuid {int}
    * @param {boolean} priceSituation {boolean}
    */

    async postPriceTableInactive(priceTableUuid, priceSituation) {
        try {
            const response = await http.post(`/priceTable/${priceTableUuid}/status/${priceSituation}`);
            return response;
        } catch (error) {
            return error;
        }
    }


    /**
    * @param priceTableId {Number}
    * @returns {Object}
    */
    async getInfoPriceTable(priceTableId) {
        try {
            const response = await http.get(
                `/priceTable/${priceTableId}`
            );

            return response.data;
        } catch (error) {
            return error.response;
        }
    }

    /**
     * @param {String} priceTableUuid {String}
     */

    async listPriceTableProducts(priceTableUuid) {
        try {
            const response = await http.get(`/priceTable/${priceTableUuid}`);
            return response
        } catch (error) {
            console.log(`error: ${error}`);
        }
    }

    /**
    * @param {String} priceTableProductUuid {String}
    */

    async priceTableProductRemove(priceTableProductUuid) {
        try {
            const response = await http.delete(`/priceTable/remove/${priceTableProductUuid}`);
            return response
        } catch (error) {
            console.log(`error: ${error}`);
        }
    }

    /**
    * @returns {Object}
    */

    async getProductList() {
        try {
            const response = await http.get('/product?page=1&size=9999&orderBy=description&sortBy=asc');
            return response
        } catch (error) {
            console.log(`error: ${error}`);
        }
    }

    /**
    * @param {String} priceTableProductUuid {String}
    * @returns {Object}
    */

    async getProductColorList(priceTableProductUuid) {
        try {
            const response = await http.get(`/variant/${priceTableProductUuid}?page=1&size=99`);
            return response
        } catch (error) {
            console.log(`error: ${error}`);
        }
    }

}

export const priceRepository = new PriceRepository();
