import http from "../../../HttpHelper";
import { PagedVendor } from "../entities/Vendor";

class VendorRepository {
  /**
   * @param {Vendor} vendor
   */
  async vendorPost(vendor) {
    const response = await http.post("/vendor", {
      uuid: vendor.uuid === null ? "" : vendor.uuid,
      identifier: vendor.identificator,
      name: vendor.name,
      isActive: vendor.situation,
      address: vendor.address,
      contact: vendor.contact.map((value) => ({
        // contactTypeUUID: value.uuid === undefined ? null : value.uuid,
        contactTypeLabel: value.contactTypeLabel,
        label: value.label,
      })),
    });
    return response;
  }

  async getVendorByIdentifier(vendorIdentifier) {
    const response = await http.get(`/vendor/${vendorIdentifier}`);
    return response;
  }

  /**
   * Function to get the options of contact from back end
   */
  async getVendorContactType() {
    try {
      return await http.get("/vendor/type?filter=(statusCode:0)");
    } catch (error) {
      return error;
    }
  }

  async vendorGet(page, rowsPerPage, orderBy, sort, chipData) {
    try {
      const filters = `${
        chipData.size == 0
          ? ""
          : chipData.map(
              (data) =>
                "&filter=(" + data.columnPopover + ":" + data.valueFilter + ")"
            )
      }`;

      const response = await http.get(
        `/vendor?page=${page}&size=${rowsPerPage}&orderBy=${orderBy}&sortBy=${sort}${
          filters == "" ? "" : filters.replaceAll(",", "")
        }`
      );
      console.log(response)
      return new PagedVendor(response.data.vendor, response.data.numberPages);
    } catch (e) {
      console.log(`erro: ${e}`);
    }
  }
}

export const vendorRepository = new VendorRepository();
