import axios from "axios";
import http from "../../../HttpHelper";
import { Error } from "../../../shared/entities/Error";
import { PagedStock } from "../entities/Entities";

class StockRepository {
  /**
   * @param {Number} packingId
   * @returns {Object}
   */
  async getDetailingStock(packingId) {
    try {
      const response = await http.get(`/stock/${packingId}/detailed`);
      return new PagedStock(response.data.stockTransfer);
    } catch (error) {
      return error.response;
    }
  }

  async getWarehouse() {
    const response = await http.get(
      "/warehouse?filter=(separationIndicator:false)"
    );
    return response;
  }

  async getStock(filterList, listByWarehouse) {
    const parameters = `page=${filterList.page}&size=${
      filterList.rowsPerPage
    }&orderBy=${
      filterList.orderBy === "" ? "description" : filterList.orderBy
    }&sortBy=${filterList.sort}`;
    const filters = `${
      filterList.filters.length > 0
        ? filterList.filters.map(
            (filter) =>
              "&filter=(" +
              filter.columnPopover +
              ":" +
              filter.valueFilter +
              ")"
          )
        : ""
    }`;
    try {
      const response = await http.get(
        `/stock?${parameters}${listByWarehouse ? "&groupWarehouse=true" : ""}${
          filters !== "" ? filters : ""
        }`
      );
      return response;
    } catch (error) {
      return error;
    }
  }

  async confirmCart(data, warehouseId) {
    try {
      const bodyBoxes = [];

      for (let idx = 0; idx < data.length; idx++) {
        bodyBoxes.push({ uuid: data[idx].uuid });
      }
      const response = await http.post(
        `/stock/transfer/${data[0].packing.warehouse.uuid}/${warehouseId}`,
        bodyBoxes
      );
      return response;
    } catch (error) {
      return error;
    }
  }

  async queryVolume() {
    try {
      const valuesJSON = localStorage.getItem("BOXES");
      const response = JSON.parse(valuesJSON);
      var itens = [];
      for (let idx = 0; idx < response.length; idx++) {
        itens.push(JSON.parse(response[idx]));
      }
      return itens;
    } catch (error) {
      return error;
    }
  }

  async queryWarehouseOrigin() {
    try {
      const warehouseOrigin = localStorage.getItem("WAREHOUSEORIGIN");
      if (warehouseOrigin) {
        return JSON.parse(warehouseOrigin);
      }
      return null;
    } catch (error) {
      throw error;
    }
  }

  async deleteItem(itemNumber) {
    var boxes = [];
    const getItens = async () => {
      return await this.queryVolume();
    };
    getItens().then((itens) => {
      boxes = itens.filter((box) => box.barCode != itemNumber);
      if (boxes.length === 0) {
        localStorage.removeItem("WAREHOUSEORIGIN");
      }
      let arrayStringfy = [];
      for (let idx = 0; idx < boxes.length; idx++) {
        arrayStringfy.push(JSON.stringify(boxes[idx]));
      }
      localStorage.setItem("BOXES", JSON.stringify(arrayStringfy));
    });
  }

  async deleteAllBoxes() {
    var itens = await this.queryVolume();
    itens.map((item, index) => {
      itens.splice(index);
    });
    if (itens.length === 0) {
      localStorage.removeItem("WAREHOUSEORIGIN");
    }
    let arrayStringfy = [];
    for (let idx = 0; idx < itens.length; idx++) {
      arrayStringfy.push(JSON.stringify(itens[idx]));
    }
    localStorage.setItem("BOXES", JSON.stringify(arrayStringfy));
  }

  addItem(item) {    
    if (localStorage.getItem("WAREHOUSEORIGIN") === null) {
      localStorage.setItem(
        "WAREHOUSEORIGIN",
        JSON.stringify(item.packing.warehouse)
      );
    }
    if (
      item.packing.warehouse.uuid !==
      JSON.parse(localStorage.getItem("WAREHOUSEORIGIN")).uuid
    ) {
      return new Error(
        "Warehouse error",
        "The selected box is not from the origin warehouse"
      );
    }
    if (localStorage.getItem("BOXES") !== null) {
      if (
        JSON.parse(localStorage.getItem("BOXES")).some(
          (element) => JSON.parse(element).uuid === item.uuid
        )
      ) {
        return new Error(
          "Box error",
          "This box is already included in the cart"
        );
      }
    }
    let itens = JSON.parse(localStorage.getItem("BOXES"));

    if (itens === null) itens = [];
    itens.push(JSON.stringify(item));
    localStorage.setItem("BOXES", JSON.stringify(itens));
  }

  verifyExistingItem(item) {
    if (localStorage.getItem("BOXES") !== null) {
      if (
        JSON.parse(localStorage.getItem("BOXES")).some(
          (element) => JSON.parse(element).uuid === item.uuid
        )
      ) {
        return true;
      } else {
        return false;
      }
    }
    return false;
  }

  async confirmReceipt(uuid) {
    const response = await http.post(`/stock/${uuid}`);
    return response.data;
  }

  async getVariantsByBox(boxNumber) {
    const response = await http.get(`/variant/box/${boxNumber}`);
    return response.data.variants;
  }

  async getStockExcel(warehouseUUID) {
    try {
      const response = await http.get(`/stock/xlsx/${warehouseUUID}`);
      return response;
    } catch (error) {
      const errors = new Map();
      return errors.set("error", "Error connection");
    }
  }
}

export const stockRepository = new StockRepository();
