import styled from "@emotion/styled";
import {
  Box,
  Button,
  Chip,
  Collapse,
  Grid,
  IconButton,
  MenuItem,
  Pagination,
  Paper,
  Popover,
  Select,
  Stack,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  TableSortLabel,
  TextField,
  Tooltip,
  Typography,
  tableCellClasses,
} from "@mui/material";
import React, { useEffect } from "react";
import { useState } from "react";
import { useNavigate, useParams } from "react-router-dom";
import FilterListRoundedIcon from "@mui/icons-material/FilterListRounded";
import ArrowBackRoundedIcon from "@mui/icons-material/ArrowBackRounded";
import { boxRequestUseCase } from "../usecases/BoxRequestUseCases";
import { stockUseCases } from "../usecases/StockUseCases";
import Swal from "sweetalert2";
import { icons } from "../../../shared/entities/Icons";
import CheckIcon from "@mui/icons-material/Check";
import AddIcon from "@mui/icons-material/Add";
import ShoppingCartCheckoutIcon from "@mui/icons-material/ShoppingCartCheckout";
import ReactDOM from "react-dom/client";
import ModalProductsCart from "../components/ModalProductsCart";
import { MdDelete } from "react-icons/md";

const columns = [
  {
    label: "Comex",
    value: "comex",
    width: "7%",
    align: "right",
    isOrder: true,
    isFilter: true,
    isNumber: true,
    maxLength: 10,
    type: "text",
  },
  {
    label: "Box Number",
    value: "boxNumber",
    width: "10%",
    align: "right",
    isOrder: true,
    isFilter: true,
    isNumber: true,
    maxLength: 10,
    type: "text",
  },
  {
    label: "Bar code",
    value: "barCode",
    width: "10%",
    align: "right",
    isOrder: true,
    isFilter: true,
    isNumber: true,
    maxLength: 10,
    type: "text",
  },
  {
    label: "Warehouse",
    value: "warehouseDescription",
    width: "12%",
    align: "right",
    isOrder: true,
    isFilter: true,
    isNumber: false,
    maxLength: 30,
    type: "text",
  },
  {
    label: "Product",
    value: "productDescription",
    width: "25%",
    align: "right",
    isOrder: false,
    isFilter: false,
    isNumber: false,
    maxLength: 30,
    type: "text",
  },
  {
    label: "Color",
    value: "colorDescription",
    width: "12%",
    align: "right",
    isOrder: true,
    isFilter: true,
    isNumber: false,
    maxLength: 30,
    type: "text",
  },
  {
    label: "Batch",
    value: "batch",
    width: "10%",
    align: "right",
    isOrder: true,
    isFilter: true,
    isNumber: false,
    maxLength: 10,
    type: "text",
  },
  {
    label: "Unity",
    value: "unity",
    width: "7%",
    align: "right",
    isOrder: true,
    isFilter: true,
    isNumber: false,
    maxLength: 10,
    type: "text",
  },
  {
    label: "Quantity",
    value: "quantity",
    width: "7%",
    align: "right",
    isOrder: true,
    isFilter: true,
    isNumber: true,
    maxLength: 10,
    type: "text",
  },
  {
    label: "Action",
    value: "action",
    width: "2%",
    align: "center",
    isOrder: false,
    isFilter: false,
    isNumber: false,
    maxLength: 10,
    type: "text",
  },
];

const StyledTableCell = styled(TableCell)(() => ({
  [`&.${tableCellClasses.head}`]: {
    backgroundColor: "#15191C",
    color: "white",
  },
  [`&.${tableCellClasses.body}`]: {
    fontSize: 14,
  },
}));

const StyledTableRow = styled(TableRow)(() => ({
  "&:nth-of-type(odd)": {
    backgroundColor: "#f3f3f3",
  },
  "&:last-child td, &:last-child th": {
    border: 0,
  },
}));

const styleTableSortLabel = {
  "&.MuiTableSortLabel-root": {
    color: "white",
  },
  "&.MuiTableSortLabel-root:hover": {
    color: "white",
  },
  "&.Mui-active": {
    color: "white",
  },
  "& .MuiTableSortLabel-icon": {
    color: "white !important",
  },
  textAlign: "center",
};

const filtersDefault = {
  page: 1,
  rowsPerPage: 10,
  orderBy: "",
  sort: "asc",
  filters: [],
};

const popoverDefault = {
  label: "",
  column: "",
  type: "text",
  maxLength: 10,
  isNumber: false,
  value: "",
};

const Toast = Swal.mixin({
  toast: true,
  position: "top-end",
  showConfirmButton: false,
  timer: 3000,
  timerProgressBar: true,
  didOpen: (toast) => {
    toast.addEventListener("mouseenter", Swal.stopTimer);
    toast.addEventListener("mouseleave", Swal.resumeTimer);
  },
});

const BoxRequestListing = () => {
  const [code, setCode] = useState(useParams().code);

  const [boxList, setBoxList] = useState([]);

  const [filterList, setFilterList] = useState(filtersDefault);
  const [pageList, setPageList] = useState(0);

  const [anchorEl, setAnchorEl] = useState(null);
  const [popover, setPopover] = useState(popoverDefault);
  const [chipData, setChipData] = useState([]);

  const [loading, setLoading] = useState(false);

  const openPopover = Boolean(anchorEl);
  const id = openPopover ? "simple-popover" : undefined;

  const [change, setChange] = useState(true);

  const [changeWithoutLoading, setChangeWithoutLoading] = useState(false);

  const navigate = useNavigate();

  /**
   * Arrow funciton to set order by filter
   * @param {String} value
   */
  const handleOrderBy = (value) => {
    setFilterList({
      ...filterList,
      ["orderBy"]: value,
      ["sort"]: filterList.sort === "asc" ? "desc" : "asc",
    });
  };
  /**
   * Arrow function to set the page filter
   * @param {Event} evt
   * @param {String} value
   */
  const handleChangePage = (evt, value) => {
    setFilterList({
      ...filterList,
      ["page"]: value,
      ["orderBy"]: "",
      ["sort"]: "asc",
    });
  };
  /**
   * Arrow function to set the rows per page filter
   * @param {Event} evt
   */
  const handleChangeRowsPerPage = (evt) => {
    setFilterList({
      ...filterList,
      ["rowsPerPage"]: evt.target.value,
      ["orderBy"]: "",
      ["sort"]: "asc",
    });
  };
  /**
   * Arrow function to close popover
   */
  const handleClosePopover = () => {
    setAnchorEl(null);
  };
  /**
   * Arrow function to open and set the default values popover
   */
  const handleClickPopover = (
    event,
    label,
    column,
    type,
    maxLength,
    number
  ) => {
    setAnchorEl(event);
    setPopover({
      label: label,
      column: column,
      type: type,
      maxLength: maxLength,
      isNumber: number,
    });
  };
  /**
   * Arrow function to confirm and set the filters to list
   */
  const handleConfirmPopover = () => {
    setAnchorEl(null);
    setChipData((chips) =>
      chips.filter((chip) => chip.labelFilter !== popover.label)
    );
    setChipData((prevState) => [
      ...prevState,
      {
        labelFilter: popover.label,
        columnPopover: popover.column,
        valueFilter: popover.value,
      },
    ]);
    setFilterList({
      ...filterList,
      ["page"]: 1,
      ["filters"]: [
        {
          labelFilter: popover.label,
          columnPopover: popover.column,
          valueFilter: popover.value,
        },
      ],
    });
  };
  /**
   * Arrow function to delete the chipData list and re-set the filter to reload the page
   * @param {[]} chipToDelete
   */
  const handleDeleteChip = (chipToDelete) => () => {
    setChipData((chips) =>
      chips.filter((chip) => chip.labelFilter !== chipToDelete.labelFilter)
    );
    setFilterList({
      ...filterList,
      ["filters"]: chipData.filter(
        (chip) => chip.labelFilter !== chipToDelete.labelFilter
      ),
    });
  };
  /**
   * Arrow function to reset the filters
   */
  const handClickResetList = () => {
    setChipData([]);
    setFilterList(filtersDefault);
  };
  /**
   * Arrow function to set time out to loader from page
   */
  const handleTimeOut = (response) => {
    setTimeout(() => {
      setBoxList(response?.data?.boxes ?? []);
      setPageList(response?.data?.numberPages ?? 0);
      setLoading(false);
    }, 100);
  };
  const previousPage = () => {
    navigate(-1);
  };

  const handleChange = () => {
    setChange(!change);
  };

  const handleOpenModalCart = () => {
    const root = ReactDOM.createRoot(document.getElementById("modal-cart"));
    return root.render(
      <ModalProductsCart
        sx={{ zIndex: "-20" }}
        isOpen={true}
        parentCallback={handleChange}
      />
    );
  };

  const handleAddCart = async (box) => {
    const boxesRequest = await boxRequestUseCase.getBoxes(
      box?.packing?.uuid ?? "",
      box?.number ?? ""
    );
    boxesRequest.boxes.map((item) => {
      if (!item.alreadyRequested) {
        const response = stockUseCases.addItemUseCase(item);
        if (response instanceof Error) {
          Swal.fire("Error", response.description, "warning");
          return;
        } else {
          setChangeWithoutLoading(!changeWithoutLoading);
          return Toast.fire({
            icon: "success",
            text: "Box added to cart",
          });
        }
      } else {
        Swal.fire({
          icon: "warning",
          title: "Error",
        });
      }
    });
  };
  const handleDeleteItem = (itemNumber) => {
    Swal.fire({
      title: "This item has already been added to the cart",
      text: "Would you like to remove it?",
      icon: "warning",
      showCancelButton: true,
      confirmButtonColor: "#032d307d",
      cancelButtonColor: "#8f948c61",
      confirmButtonText: "Remove",
    }).then((result) => {
      if (result.isConfirmed) {
        try {
          stockUseCases
            .deleteItemUseCases(itemNumber)
            .then(() => setChangeWithoutLoading(!changeWithoutLoading));
          return Swal.fire({
            title: "Removed!",
            text: "This item has been removed.",
            confirmButtonColor: "#032d307d",
          });
        } catch (error) {
          return Swal.fire({
            icon: "error",
            text: error.message,
          });
        }
      }
    });
  };

  const verifyReceiptItem = (item) => {
    if (item.alreadyRequested) {
      return (
        <Tooltip title="Item already ordered" placement="left">
          <IconButton
            onClick={() => {
              return Swal.fire({
                icon: "warning",
                title: "Item already ordered",
                confirmButtonText: "OK",
              });
            }}
          >
            <CheckIcon color="primary" />
          </IconButton>
        </Tooltip>
      );
    } else {
      if (!stockUseCases.verifyExistingItem(item)) {
        return (
          <Tooltip title="Add to cart" placement="left">
            <IconButton
              onClick={() => {
                handleAddCart(item);
              }}
            >
              <AddIcon color="action" />
            </IconButton>
          </Tooltip>
        );
      } else {
        return (
          <Tooltip title="Delete item from the cart" placement="left">
            <IconButton
              onClick={() => handleDeleteItem(item?.number ?? "")}
              size="medium"
            >
              <MdDelete />
            </IconButton>
          </Tooltip>
        );
      }
    }
  };

  const verifyItemRequest = (item) => {
    if (item.alreadyRequested) {
      return {
        display: "table-row",
        backgroundColor: "#D6EAF8 !important",
      };
    } else {
      return {
        display: "table-row",
        backgroundColor: !stockUseCases.verifyExistingItem(item)
          ? ""
          : "#D1F2EB !important",
      };
    }
  };

  useEffect(() => {
    document.title = "Lince Tech Micro ERP | Box request";
    // setLoading(true);
    const getBoxRequest = async () => {
      const response = await boxRequestUseCase.getBoxRequest(filterList, code);
      return response;
    };
    getBoxRequest().then((response) => {
      handleTimeOut(response);
    });
  }, [filterList, change, code]);

  return (
    <Box
      sx={{
        display: "flex",
        marginLeft: "3rem",
        marginTop: "3rem",
        marginRight: "2rem",
      }}
    >
      <input type="hidden" id="modal-cart" />
      <Box sx={{ width: "100%" }}>
        <Box
          sx={{
            display: "flex",
            alignItems: "center",
          }}
        >
          <Tooltip title="Previous page">
            <IconButton onClick={previousPage} sx={{ marginRight: "2vw" }}>
              <ArrowBackRoundedIcon fontSize="large" />
            </IconButton>
          </Tooltip>
          <Typography sx={{ fontSize: "26pt", fontWeight: "800" }}>
            Box request
          </Typography>
        </Box>
        <Box
          sx={{
            minWidth: "100%",
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
            marginTop: "0.5rem",
          }}
        >
          <Box sx={{ display: "flex", alignItems: "center" }}>
            <Box
              sx={{
                display: "flex",
                justifyContent: "center",
                flexWrap: "nowrap",
                listStyle: "none",
                p: 0,
                m: 0,
                border: "none",
                height: "4rem",
                alignItems: "center",
              }}
            >
              {chipData.map((data) => {
                return (
                  <Tooltip title={data.labelFilter} placement="top">
                    <Chip
                      sx={{
                        textOverFlow: "ellipsis",
                        overFlow: "hidden",
                        whiteSpace: "nowrap",
                        maxWidth: "145px",
                        marginRight: "1rem",
                      }}
                      color="primary"
                      variant="outlined"
                      label={data.valueFilter}
                      onDelete={handleDeleteChip(data)}
                    />
                  </Tooltip>
                );
              })}
            </Box>
            {chipData.length === 0 ? (
              <></>
            ) : (
              <Tooltip title="Clear all" placement="top">
                <Button sx={{ height: "3rem" }} onClick={handClickResetList}>
                  Clear All
                </Button>
              </Tooltip>
            )}
          </Box>
          <Box>
            <Tooltip title="Open cart">
              <IconButton onClick={() => handleOpenModalCart()}>
                <ShoppingCartCheckoutIcon fontSize="large" />
              </IconButton>
            </Tooltip>
          </Box>
        </Box>
        <Paper sx={{ width: "100%", overflow: "hidden", marginTop: "0.5rem" }}>
          {loading ? (
            <Box
              sx={{
                width: "100%",
                justifyContent: "center",
                display: "flex",
                padding: "2%",
              }}
            >
              <Box className="loader" />
            </Box>
          ) : (
            <TableContainer sx={{ maxHeight: "85vh" }}>
              <Table
                stickyHeader
                aria-label="sticky table"
                sx={{ minWidth: "800px" }}
              >
                <TableHead>
                  <StyledTableRow>
                    {columns.map((key, index) => (
                      <StyledTableCell
                        key={index}
                        align={key.align}
                        width={key.width}
                      >
                        <Grid
                          container
                          justifyContent={
                            key.align === "center" ? "center" : "space-between"
                          }
                          flexWrap={"nowrap"}
                          alignItems={"center"}
                        >
                          <Tooltip title={key.label} placement="top">
                            {key.isOrder === true ? (
                              <TableSortLabel
                                sx={styleTableSortLabel}
                                active={filterList.orderBy === key.value}
                                direction={filterList.sort}
                                onClick={() => handleOrderBy(key.value)}
                              >
                                {key.label}
                              </TableSortLabel>
                            ) : (
                              <Typography>{key.label}</Typography>
                            )}
                          </Tooltip>
                          {key.isFilter === true && (
                            <Tooltip
                              title={`Filter by ${key.label}`}
                              placement="top"
                            >
                              <FilterListRoundedIcon
                                variant="contained"
                                onClick={(evt) =>
                                  handleClickPopover(
                                    evt.currentTarget,
                                    key.label,
                                    key.value,
                                    key.type,
                                    key.maxLength,
                                    key.isNumber
                                  )
                                }
                                sx={{
                                  width: "18px",
                                  justifySelf: "end",
                                  cursor: "pointer",
                                }}
                              />
                            </Tooltip>
                          )}
                        </Grid>
                      </StyledTableCell>
                    ))}
                  </StyledTableRow>
                </TableHead>
                <TableBody>
                  {boxList.map((box, index) => (
                    <StyledTableRow key={index} sx={verifyItemRequest(box)}>
                      <StyledTableCell size="small">
                        {box?.packing?.comex ?? ""}
                      </StyledTableCell>
                      <StyledTableCell size="small">
                        {box?.number ?? ""}
                      </StyledTableCell>
                      <StyledTableCell size="small">
                        {box?.barCode ?? ""}
                      </StyledTableCell>
                      <StyledTableCell size="small">
                        {box?.packing?.warehouse?.description ?? ""}
                      </StyledTableCell>
                      <StyledTableCell size="small">
                        {box?.item?.variant?.product?.textCode ?? ""} -{" "}
                        {box?.item?.variant?.product?.description ?? ""}
                      </StyledTableCell>
                      <StyledTableCell size="small">
                        {box?.item?.variant?.color?.code ?? ""} -{" "}
                        {box?.item?.variant?.color?.description ?? ""}
                      </StyledTableCell>
                      <StyledTableCell size="small">
                        {box?.batch ?? ""}
                      </StyledTableCell>
                      <StyledTableCell size="small">
                        {box?.item?.unity ?? ""}
                      </StyledTableCell>
                      <StyledTableCell size="small">
                        {box?.item?.quantity ?? ""}
                      </StyledTableCell>
                      <StyledTableCell size="small">
                        {verifyReceiptItem(box)}
                      </StyledTableCell>
                    </StyledTableRow>
                  ))}
                </TableBody>
              </Table>
            </TableContainer>
          )}
        </Paper>
        <Box
          display={"flex"}
          justifyContent={"flex-end"}
          sx={{ marginTop: "2vh", alignItems: "center", gap: "1vw" }}
        >
          <Typography sx={{ align: "center", fontSize: "11pt" }}>
            Rows Per Page
          </Typography>
          <Tooltip title="Rows per page" placement="top">
            <Select
              sx={{ height: "4vh", align: "center" }}
              autoWidth
              value={filterList.rowsPerPage}
              onChange={handleChangeRowsPerPage}
            >
              <MenuItem value={5}>5</MenuItem>
              <MenuItem value={10}>10</MenuItem>
              <MenuItem value={15}>15</MenuItem>
            </Select>
          </Tooltip>
          <Stack spacing={2}>
            <Pagination
              count={pageList}
              page={filterList.page}
              onChange={handleChangePage}
            />
          </Stack>
        </Box>

        <Popover
          id={id}
          open={openPopover}
          anchorEl={anchorEl}
          onClose={handleClosePopover}
          anchorOrigin={{
            vertical: "bottom",
            horizontal: "left",
          }}
        >
          <Box
            sx={{
              display: "flex",
              alignContent: "center",
              alignItems: "center",
              p: 2,
              gap: 2,
            }}
          >
            <Typography>Filter</Typography>
            <TextField
              type={popover.type}
              inputProps={{ maxLength: popover.maxLength }}
              variant="outlined"
              placeholder={popover.label}
              size="small"
              onKeyDown={(evt) =>
                evt.keyCode === 13 ? handleConfirmPopover() : ""
              }
              onChange={(evt) => {
                if (popover.type === "number") {
                  evt.target.value = evt.target.value.replace(/[^0-9,]/g, "");
                }
                setPopover({
                  ...popover,
                  ["value"]: evt.target.value,
                });
              }}
            ></TextField>
            <Button variant="outlined" onClick={handleConfirmPopover}>
              Confirm
            </Button>
          </Box>
        </Popover>
      </Box>
    </Box>
  );
};

export default BoxRequestListing;
