import {
  Button,
  Divider,
  FormControl,
  InputLabel,
  MenuItem,
  Modal,
  Select,
  TextField,
  Typography,
} from "@mui/material";
import { Box } from "@mui/system";
import { DesktopDatePicker, LocalizationProvider } from "@mui/x-date-pickers";
import React, { useEffect } from "react";
import { AdapterDayjs } from "@mui/x-date-pickers/AdapterDayjs";
import { priceUseCase } from "../usecases/PriceUseCases";
import { Price } from "../entities/Entities";
import Swal from "sweetalert2";

const priceSituationOption = [
  {
    value: true,
    label: "Active",
  },
  {
    value: false,
    label: "Inactive",
  },
];

const Toast = Swal.mixin({
  toast: true,
  position: "top-end",
  showConfirmButton: false,
  timer: 3000,
  timerProgressBar: true,
  didOpen: (toast) => {
    toast.addEventListener("mouseenter", Swal.stopTimer);
    toast.addEventListener("mouseleave", Swal.resumeTimer);
  },
});

const PriceRegisterModal = ({ priceCode, isOpen, parentCallback }) => {
  const dayjs = require("dayjs");

  const [open, setOpen] = React.useState(isOpen);
  const [dateInitial, setDateInitial] = React.useState(dayjs());
  const [dateFinal, setDateFinal] = React.useState(dayjs());
  const [error, setError] = React.useState([]);
  const [loading, setLoading] = React.useState(false);
  const [priceObject, setPriceObject] = React.useState(
    new Price("", "", "", true, "", "")
  );

  const handleDateChangeInitial = (value) => {
    setDateInitial(value);
  };

  const handleDateChangeFinal = (value) => {
    setDateFinal(value);
  };

  const modalStyle = {
    position: "absolute",
    display: "flex",
    flexDirection: "column",
    top: "50%",
    left: "50%",
    transform: "translate(-50%, -50%)",
    width: "50vw",
    border: "none",
    backgroundColor: "#ffffff",
    boxShadow: 24,
    borderRadius: "10px",
    padding: "30px 30px",
  };

  const handleClose = () => {
    setOpen(!open);
  };

  const ITEM_HEIGHT = 60;
  const ITEM_PADDING_TOP = 10;
  const MenuProps = {
    PaperProps: {
      style: {
        maxHeight: ITEM_HEIGHT * 4.5 + ITEM_PADDING_TOP,
        width: 250,
      },
    },
  };

  const handleOnChange = (evt) => {
    const { name, value } = evt.target;
    setPriceObject({
      ...priceObject,
      [name]: value,
    });
  };

  React.useEffect(() => {
    if (priceCode !== undefined) {
      const getPriceInformation = async () => {
        const getPrice = await priceUseCase.getInformationPrice(priceCode);

        setPriceObject(
          new Price(
            getPrice.uuid,
            getPrice.code,
            getPrice.name,
            getPrice.isActive,
            getPrice.initial,
            getPrice.final
          )
        );
        setDateInitial(dayjs(getPrice.initial));
        setDateFinal(dayjs(getPrice.final));
      };
      getPriceInformation();
    }
  }, []);

  const handleRegisterPriceTable = async () => {
    let initial;
    let final;

    initial = dateInitial.format("YYYY-MM-DD");
    final = dateFinal.format("YYYY-MM-DD");

    const response = await priceUseCase.postPriceTable(
      new Price(
        priceCode !== undefined ? priceObject.uuid : null,
        priceObject.code,
        priceObject.name,
        priceObject.isActive,
        initial,
        final
      )
    );
    if (response.size) {
      const error = response.values();
      const errorKey = response.keys();
      setError(errorKey.next().value.key);
      return Swal.fire({
        icon: "warning",
        confirmButtonText: "OK",
        text: error.next().value,
      });
    }
    if (!response.status) {
      return Swal.fire({
        icon: "error",
        confirmButtonText: "OK",
        text: "Connection error",
      });
    }
    if (response.data.error !== null) {
      return Swal.fire({
        icon: "error",
        confirmButtonText: "OK",
        text: response.data.error.description,
      });
    } else {
      parentCallback(true);
      handleClose();
      return Toast.fire({
        icon: "success",
        text: "Successfully registered",
      });
    }
  };

  return (
    <div>
      <Modal
        open={open}
        onClose={handleClose}
        aria-labelledby="modal-modal-title"
        aria-describedby="modal-modal-description"
      >
        <Box sx={{ width: "100%" }}>
          <Box sx={modalStyle}>
            <Typography
              sx={{ fontSize: "1.5em", fontWeight: "700", color: "#363636" }}
              component="h2"
            >
              Pricing Table
              {priceObject.code !== undefined ? ": " + priceObject.code : ""}
            </Typography>
            <Divider />
            <Box>
              <Box
                sx={{
                  marginTop: "2rem",
                  width: "100%",
                  display: "flex",
                  justifyContent: "space-between",
                  // display: "grid",
                  // gridGap: "1rem",
                  // gridTemplateColumns:
                  //     "repeat(auto-fit, minmax(200px, 1fr) minmax(200px, 1fr))",
                }}
              >
                <TextField
                  label="Name"
                  variant="standard"
                  name="name"
                  sx={{ width: "55%" }}
                  inputProps={{ maxLength: 200 }}
                  value={priceObject.name}
                  onChange={(evt) => {
                    handleOnChange(evt);
                    setError([]);
                  }}
                  {...(error === "name" ? { error } : "")}
                ></TextField>
                <FormControl variant="standard" sx={{ width: "10%" }}>
                  <InputLabel id="id-situation-form-wharehouse">
                    Situation
                  </InputLabel>
                  <Select
                    labelId="id-situation-form-wharehouse"
                    label="Situation"
                    inputProps={
                      priceCode !== undefined
                        ? { maxLength: 20 }
                        : { maxLength: 20, readOnly: true }
                    }
                    value={priceObject.isActive}
                    name="isActive"
                    onChange={(evt) => {
                      handleOnChange(evt);
                      setError([]);
                    }}
                    {...(error === "isActive" ? { error } : "")}
                  >
                    {priceSituationOption.map((item, index) => (
                      <MenuItem key={index} value={item.value}>
                        {item.label}
                      </MenuItem>
                    ))}
                  </Select>
                </FormControl>
                <LocalizationProvider dateAdapter={AdapterDayjs}>
                  <DesktopDatePicker
                    label="Date initial"
                    inputFormat="MM/DD/YYYY"
                    value={dateInitial}
                    onChange={handleDateChangeInitial}
                    name="initial"
                    {...(error === "initial" ? { error } : "")}
                    renderInput={(params) => (
                      <TextField
                        sx={{ width: "15%" }}
                        variant="standard"
                        {...params}
                      />
                    )}
                  />
                </LocalizationProvider>
                <LocalizationProvider dateAdapter={AdapterDayjs}>
                  <DesktopDatePicker
                    label="Date final"
                    inputFormat="MM/DD/YYYY"
                    value={dateFinal}
                    name="final"
                    onChange={handleDateChangeFinal}
                    {...(error === "final" ? { error } : "")}
                    renderInput={(params) => (
                      <TextField
                        sx={{ width: "15%" }}
                        variant="standard"
                        {...params}
                      />
                    )}
                  />
                </LocalizationProvider>
              </Box>
            </Box>
            {loading ? (
              <Box
                sx={{
                  width: "95%",
                  display: "flex",
                  justifyContent: "flex-end",
                  flexWrap: "nowrap",
                  marginTop: "2rem",
                }}
              >
                <div className="loading" sx="height: 20px; width: 20px"></div>
              </Box>
            ) : (
              <Box
                sx={{
                  width: "100%",
                  display: "flex",
                  justifyContent: "flex-end",
                  flexWrap: "nowrap",
                  marginTop: "2rem",
                }}
              >
                <Button
                  variant="contained"
                  sx={{ m: 1, minWidth: "7vw", height: "4vh" }}
                  onClick={() => {
                    handleRegisterPriceTable();
                  }}
                >
                  Confirm
                </Button>
                <Button
                  variant="outlined"
                  sx={{ m: 1, minWidth: "7vw", height: "4vh" }}
                  onClick={() => handleClose()}
                  color="error"
                >
                  Cancel
                </Button>
              </Box>
            )}
          </Box>
        </Box>
      </Modal>
    </div>
  );
};

export default PriceRegisterModal;
