import { PagedUser } from "../entities/PagedUser";
import { Error } from "../../../shared/entities/Error";
import http from "../../../HttpHelper";
import { User } from "../entities/Entities";

class UserRepository {
  /**
   * @param page {int}
   * @param rowsPerPage {int}
   * @param orderBy {string}
   * @param sort {string}
   * @param chipData {chipData[]}
   * @param checked {boolean}
   * @param {Promise<PagedUser>}
   *
   */

  async getUsers(
    page,
    rowsPerPage,
    orderBy,
    sort,
    chipData,
    checked,
  ) {

    const filters = `${chipData.size === 0 ? '' : chipData.map((data) =>
      '&filter=(' + data.columnPopover + ':' + data.valueFilter + ')'
    )}`

    const response = await http.get(
      `/user?page=${page}&size=${rowsPerPage}&orderBy=${orderBy}&sortBy=${sort}${"&filter=(isActive:" + checked + ")"
      }${filters === '' ? '' : filters.replaceAll(",", "")}`
    );    
    return new PagedUser(response.data.users, response.data.numberPages);
  }

  async getUserByUuid(uuid) {
    const response = await http.get(`/user/${uuid}`);    
    return response.data.user;      
  }

  async getUserTypes() {
    const response = await http.get("/user/types");
    return response.data.userTypes;
  }

  async postUser(user) {    
    console.log(user)
    const response = await http.post("/user", {
      uuid: user.uuid,
      name: user.name,
      email: user.email,
      userType: user.type,
      authenticationRecord: user.authenticationRecord,
      contact: user.phone,
      isActive: user.situation,
      password: user.password
    });
    if (response.data.error)
      return new Error(
        response.data.error.code,
        response.data.error.description
      );

    return new User(
      response.data.user.uuid,
      response.data.user.name,
      response.data.user.email,
      response.data.user.userType,
      response.data.user.authenticationRecord,
      response.data.user.contact,
      response.data.user.isActive,
      response.data.user.password
    );
  }

  async generateNewPassword(authenticationRecord) {
    const response = await http.post(
      `user/new/password/${authenticationRecord}`
    );

    if (response.data.error)
      return new Error(
        response.data.error.code,
        response.data.error.description
      );
    return response.data.password;
  }
}

export const userRepository = new UserRepository();
