import { useEffect, useState } from "react";
import {
  Box,
  Paper,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
} from "@mui/material";
import { requestHistoryUseCases } from "../../usecases/RequestHistoryUseCases";
import * as React from "react";
import dayjs from "dayjs";

const columns = [
  {
    id: "modification",
    label: "Action",
    width: "30%",
  },
  {
    id: "modifiedAt",
    label: "Date",
    width: "30%",
  },
  {
    id: "modifiedBy",
    label: "User",
    width: "40%",
  },
];

const StockHistory = ({ stockUUID, stockTtransfer }) => {
  const [stockHistory, setStockHistory] = useState([]);
  const [loading, setLoading] = useState(false);

  const convertDate = (originalDate) => {
    if (originalDate !== "") {
      return dayjs(originalDate).format("MM/DD/YYYY HH:mm");
    }
  };

  const handleTimeOut = (response) => {
    setTimeout(() => {
      setStockHistory(response?.data?.stockTransferHistory ?? []);
      setLoading(false);
    }, 200);
  };

  useEffect(() => {
    setLoading(true);
    const getStockHistoric = async () => {
      const stockHistoric = await requestHistoryUseCases.getStockHistoric(
        stockUUID
      );
      return stockHistoric;
    };
    getStockHistoric().then((response) => handleTimeOut(response));
  }, []);

  return (
    <Paper sx={{ overflow: "hidden", margin: "auto" }}>
      {loading ? (
        <Box
          sx={{
            width: "100%",
            justifyContent: "center",
            display: "flex",
            padding: "2%",
          }}
        >
          <Box className="loader" />
        </Box>
      ) : (
        <TableContainer component={Paper}>
          <Table sx={{ minWidth: 920 }}>
            <TableHead>
              <TableRow>
                {columns.map((column, index) => (
                  <TableCell
                    key={index}
                    sx={{
                      width: column.width,
                      fontWeight: "700",
                      color: "black",
                      backgroundColor: "#ECF0F1",
                    }}
                  >
                    {column.label}
                  </TableCell>
                ))}
              </TableRow>
            </TableHead>
            <TableBody>
              {stockHistory.map((key, index) => (
                <TableRow hover role="checkbox" tabIndex={-1} key={index}>
                  <TableCell>{key?.modification ?? ""}</TableCell>
                  <TableCell>{convertDate(key?.modifiedAt ?? "")}</TableCell>
                  <TableCell>{key?.modifiedBy ?? ""}</TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>
      )}
    </Paper>
  );
};
export default StockHistory;
