import { BrowserRouter, Route, Routes } from "react-router-dom";
import ChangePassword from "./core/user/pages/changepassword/ChangePassword";
import UserListing from "./core/user/pages/UserListing";
import Login from "./core/user/pages/login/Login";
import ResetPassword from "./core/user/pages/resetpassword/ResetPassword";
import Product from "./internationalization/product/pages/Product";
import TechnicalInformation from "./internationalization/product/pages/TechnicalInformation";
import DefaultPage from "./shared/components/DefaultPage";
import Warehouse from "./internationalization/warehouse/pages/Warehouse";
import RequireAuth from "./core/user/components/RequireAuth";
import Packing from "./internationalization/packing/pages/Packing";
import Stock from "./internationalization/stock/pages/Stock";
import RequestHitory from "./internationalization/stock/pages/RequestHistory";
import BoxRequestListing from "./internationalization/stock/pages/BoxRequestListing";
import ProductDetail from "./internationalization/product/pages/ProductDetail";
import Price from "./internationalization/price/pages/PriceList"
import MainPage from "./shared/components/MainPage";
import Vendor from "./internationalization/vendor/pages/Vendor";
import BoxList from "./internationalization/box/page/BoxList";

if (process.env.NODE_ENV) {
  console.log("Running in development mode");
}

function App() {
  return (
    <BrowserRouter basename="/web">
      <Routes>
        <Route path="Login" element={<Login />} />
        <Route path="ResetPassword" element={<ResetPassword />} />
        <Route path="ChangePassword" element={<ChangePassword />} />
        <Route element={<RequireAuth />}>
          <Route path="/" element={<DefaultPage />}>
            <Route path="Home" element={<MainPage />} />
            <Route path="Product" element={<Product />} />
            <Route path="Stock" element={<Stock />} />
            <Route
              path="Product/:code/TechnicalInformation"
              element={<TechnicalInformation />}
            />
            <Route path="Packing" element={<Packing />} />
            <Route path="User" element={<UserListing />} />
            <Route path="Price" element={<Price />} />
            <Route path="BoxList" element={<BoxList />} />
            <Route path="Warehouse" element={<Warehouse />} />
            <Route path="RequestHistory" element={<RequestHitory />} />
            <Route path="BoxRequest" element={<BoxRequestListing />} />
            <Route
              path="Stock/:code/:warehouse/BoxRequestListing"
              element={<BoxRequestListing />}
            />
            <Route
              path="Stock/:code/BoxRequestListing"
              element={<BoxRequestListing />}
            />
            <Route
              path="Product/:code/ProductDetail"
              element={<ProductDetail />}
            />
            <Route path="Vendor" element={<Vendor />} />
          </Route>
        </Route>
      </Routes>
    </BrowserRouter>
  );
}

export default App;
