import http from "../../../HttpHelper";
import { FiltersList } from "../entities/FiltersPage";

class ProductRepository {
  /**
   * @param {FiltersList} filterList
   * @returns
   */
  async getProducts(filterList) {
    const parameters = `page=${filterList.page}&size=${
      filterList.rowsPerPage
    }&orderBy=${
      filterList.orderBy === "" ? "description" : filterList.orderBy
    }&sortBy=${filterList.sort}`;
    const filters = `${
      filterList.filters.length > 0
        ? filterList.filters.map(
            (filter) =>
              "&filter=(" +
              filter.columnPopover +
              ":" +
              filter.valueFilter +
              ")"
          )
        : ""
    }`;
    try {
      const response = await http.get(
        `/product?${parameters}${filters !== "" ? filters : ""}`
      );
      return response;
    } catch (error) {
      return error;
    }
  }
  async getProductsFromSessionStorage() {
    return sessionStorage.getItem("products_to_excel");
  }
  async getProductExcel(products, priceTable) {
    const getExcel = () => {
      return http.post(`/product/create/xlsx/${priceTable}`, products, {
        responseType: "arraybuffer",
      });
    };

    try {
      const response = await getExcel();

      const url = window.URL.createObjectURL(
        new Blob([response.data], {
          type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        })
      );

      const link = document.createElement("a");
      link.href = url;
      link.setAttribute("download", "Products.xls");
      document.body.appendChild(link);
      link.click();
    } catch (error) {
      const errors = new Map();
      return errors.set("error", "An error has ocurred.");
    }
  }
  async getPriceTable() {
    try {
      const response = await http.get("/priceTable?filter=(isActive:true)");
      return response;
    } catch (error) {
      const errors = new Map();
      return errors.set("error", "An error has ocurred.");
    }
  }
}

export const productRepository = new ProductRepository();
