import "./ChangePassword.css";
import AuthenticationRepository from '../../repositories/authentication_repository';
import {
  Box,
  Button,
  FormControl,
  Grid,
  Input,
  InputAdornment,
  InputLabel,
  Typography,
} from "@mui/material";

import IconButton from "@mui/material/IconButton";
import LockResetIcon from "@mui/icons-material/LockReset";
import VisibilityOff from "@mui/icons-material/VisibilityOff";
import Visibility from "@mui/icons-material/Visibility";
import Swal from "sweetalert2";

import React, { useState } from "react";
import { useLocation, useNavigate } from "react-router-dom";
import { useEffect } from "react";

function useQuery() {
  const { search } = useLocation();
  return React.useMemo(() => new URLSearchParams(search), [search]);
}

function ChangePassword() {
  const [currentPassword, setCurrentPassword] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const query = useQuery();
  const navigate = useNavigate();

  const [valuesCurrentPassword, setValuesCurrentPassword] = useState({
    currentPassword: "",
    showCurrentPassword: false,
  });

  const handleClickShowCurrentPassword = () => {
    setValuesCurrentPassword({
      ...valuesCurrentPassword,
      showCurrentPassword: !valuesCurrentPassword.showCurrentPassword,
    });
  };

  const [valuesNewPassword, setValuesNewPassword] = useState({
    newPassword: "",
    showNewPassword: false,
  });

  const handleClickShowNewPassword = () => {
    setValuesNewPassword({
      ...valuesNewPassword,
      showNewPassword: !valuesNewPassword.showNewPassword,
    });
  };

  const [valuesConfirmPassword, setValuesConfirmPassword] = useState({
    confirmPassword: "",
    showConfirmPassword: false,
  });

  const handleClickShowConfirmPassword = () => {
    setValuesConfirmPassword({
      ...valuesNewPassword,
      showConfirmPassword: !valuesConfirmPassword.showConfirmPassword,
    });
  };

  const handleMouseDownPassword = (event) => {
    event.preventDefault();
  };

  const submit = async (event) => {
    event.preventDefault();
    try {
      const requestID = query.get('requestID');

      const passwordInformed = newPassword === '' || confirmPassword === '' || currentPassword === '';
      const compareOldAndCurrentPassword = currentPassword === newPassword || currentPassword === confirmPassword;
      const compareNewPasswords = newPassword !== confirmPassword;
      const successChangePassword = passwordInformed && compareOldAndCurrentPassword && compareNewPasswords;

      if (passwordInformed && requestID === "") {
        Swal.fire({
          text: "Fill in all fields.",
          icon: "warning",
        });
      }

      if (compareOldAndCurrentPassword) {
        Swal.fire({
          text: "Your new password cannot be the same as your current password.",
          icon: "warning",
        });
      }

      if (compareNewPasswords) {
        Swal.fire({
          text: "Please make sure your passwords match.",
          icon: "error",
        });
      }

      if (!successChangePassword) {
        if (requestID) {
          await AuthenticationRepository.resetPassword(newPassword, confirmPassword, requestID);
          navigate('/');
        } else {
          await AuthenticationRepository.changePassword(currentPassword, newPassword, confirmPassword);
          Swal.fire({
            title: 'Password changed',
            text: "Your password has been changed successfully.",
            icon: 'success',
          });
          navigate('/Warehouse');
        }
      }
    } catch (e) {
    }
  };

  const previousPage = () => {
    navigate(-1)
  }

  useEffect(() => {
    document.title = 'Lince Tech Micro ERP | Change password'
  }, [])


  return (
    <Box className="change-password-view" backgroundColor="Background">
      <Box sx={{ textAlign: "center" }}>
        <LockResetIcon sx={{ fontSize: 100, textAlign: "center" }} />
        <Typography component="h1" variant="h4">
          Change Password
        </Typography>
        <Box component="form" noValidate sx={{ mt: 1 }} onSubmit={submit} >
          <fieldset className="fieldset">
            {!query.get('requestID') &&
              (
                <FormControl sx={{ m: 1, width: "40ch" }} variant="standard">
                  <InputLabel htmlFor="standard-adornment-current-password">
                    Current Password
                  </InputLabel>
                  <Input
                    id="standard-adornment-current-password"
                    type={
                      valuesCurrentPassword.showCurrentPassword
                        ? "text"
                        : "password"
                    }
                    value={currentPassword}
                    onChange={(event) => setCurrentPassword(event.target.value)}
                    endAdornment={
                      <InputAdornment position="end">
                        <IconButton
                          aria-label="toggle password visibility"
                          onClick={handleClickShowCurrentPassword}
                          onMouseDown={handleMouseDownPassword}
                        >
                          {valuesCurrentPassword.showCurrentPassword ? <VisibilityOff className="visibilityOff" /> : <Visibility className="visibility" />}
                        </IconButton>
                      </InputAdornment>
                    }
                  />
                </FormControl>
              )
            }

            <FormControl sx={{ m: 1, width: "40ch" }} variant="standard">

              <InputLabel htmlFor="standard-adornment-enter-new-password">
                Enter New Password
              </InputLabel>
              <Input
                id="standard-adornment-enter-new-password"
                type={valuesNewPassword.showNewPassword ? "text" : "password"}
                value={newPassword}
                onChange={(event) => setNewPassword(event.target.value)}
                endAdornment={
                  <InputAdornment position="end">
                    <IconButton
                      aria-label="toggle password visibility"
                      onClick={handleClickShowNewPassword}
                      onMouseDown={handleMouseDownPassword}
                    >
                      {valuesNewPassword.showNewPassword ? <VisibilityOff className="visibilityOff" /> : <Visibility className="visibility" />}
                    </IconButton>
                  </InputAdornment>
                }
              />
            </FormControl>

            <FormControl sx={{ m: 1, width: "40ch" }} variant="standard">
              <InputLabel htmlFor="standard-adornment-confirm-password">
                Confirm Password
              </InputLabel>
              <Input
                id="standard-adornment-confirm-password"
                type={
                  valuesConfirmPassword.showConfirmPassword
                    ? "text"
                    : "password"
                }
                value={confirmPassword}
                onChange={(event) => setConfirmPassword(event.target.value)}
                endAdornment={
                  <InputAdornment position="end">
                    <IconButton
                      aria-label="toggle password visibility"
                      onClick={handleClickShowConfirmPassword}
                      onMouseDown={handleMouseDownPassword}
                    >
                      {valuesConfirmPassword.showConfirmPassword ? <VisibilityOff className="visibilityOff" /> : <Visibility className="visibility" />}
                    </IconButton>
                  </InputAdornment>
                }
              />
            </FormControl>
            <Grid sx={{ display: "flex", justifyContent: "space-around" }}>
              <Button variant="contained" onClick={previousPage}>
                Back
              </Button>
              <Button
                variant="contained"
                color="primary"
                type="submit"
              >
                Apply Changes
              </Button>
            </Grid>


          </fieldset>
        </Box>
      </Box>
    </Box>
  );
}

export default ChangePassword;