import {
  Box,
  Button,
  Checkbox,
  Chip,
  FormControlLabel,
  Grid,
  Icon,
  IconButton,
  MenuItem,
  Pagination,
  Paper,
  Popover,
  Select,
  Stack,
  Switch,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  TableSortLabel,
  TextField,
  Tooltip,
  Typography,
  tableCellClasses,
} from "@mui/material";
import styled from "@emotion/styled";
import FilterListRoundedIcon from "@mui/icons-material/FilterListRounded";
import ListRoundedIcon from "@mui/icons-material/ListRounded";
import { useEffect } from "react";
import { useState } from "react";
import { productUseCase } from "../usecases/ProductUseCase";
import { FiltersList, PopoverClass } from "../entities/FiltersPage";
import { Link } from "react-router-dom";
import ReactDOM from "react-dom/client";
import ModalProductExcel from "../components/ModalProductExcel";
import { RiFileExcel2Fill } from "react-icons/ri";

const StyledTableCell = styled(TableCell)(() => ({
  [`&.${tableCellClasses.head}`]: {
    backgroundColor: "#15191C",
    color: "white",
  },
  [`&.${tableCellClasses.body}`]: {
    fontSize: 14,
  },
}));

const StyledTableRow = styled(TableRow)(() => ({
  "&:nth-of-type(odd)": {
    backgroundColor: "#f3f3f3",
  },
  "&:last-child td, &:last-child th": {
    border: 0,
  },
}));

const styleTableSortLabel = {
  "&.MuiTableSortLabel-root": {
    color: "white",
  },
  "&.MuiTableSortLabel-root:hover": {
    color: "white",
  },
  "&.Mui-active": {
    color: "white",
  },
  "& .MuiTableSortLabel-icon": {
    color: "white !important",
  },
};

const columns = [
  {
    value: "textCode",
    label: "Code",
    width: "5%",
    align: "right",
    isOrder: true,
    isFilter: true,
    isNumber: false,
    maxLength: 10,
    type: "number",
  },
  {
    value: "description",
    label: "Description",
    width: "30%",
    align: "left",
    isOrder: true,
    isFilter: true,
    isNumber: false,
    maxLength: 20,
    type: "text",
  },
  {
    value: "netValue",
    label: "Net Weight (lb)",
    width: "8%",
    align: "right",
    isOrder: true,
    isFilter: true,
    isNumber: false,
    maxLength: 10,
    type: "number",
  },
  {
    value: "grossValue",
    label: "Gross Weight (lb)",
    width: "8%",
    align: "right",
    isOrder: true,
    isFilter: true,
    isNumber: false,
    maxLength: 10,
    type: "number",
  },
  {
    value: "salesMultiple",
    label: "Sales multiple",
    width: "7%",
    align: "right",
    isOrder: true,
    isFilter: true,
    isNumber: false,
    maxLength: 10,
    type: "number",
  },
  {
    value: "unitOfMeasurement",
    label: "Unit of measurement",
    width: "10%",
    align: "left",
    isOrder: true,
    isFilter: true,
    isNumber: false,
    maxLength: 10,
    type: "text",
  },
  {
    value: "situation",
    label: "Situation",
    width: "5%",
    align: "left",
    isOrder: false,
    isFilter: false,
    isNumber: false,
    maxLength: 10,
    type: "text",
  },
  {
    value: "action",
    label: "Action",
    width: "5%",
    align: "center",
    isOrder: false,
    isFilter: false,
    isNumber: false,
    maxLength: 10,
    type: "text",
  },
];

const filtersDefault = new FiltersList(1, 10, "", "asc", []);

const popoverDefault = new PopoverClass("", "", "text", 10, false, "");

const Product = () => {
  const [productList, setProductList] = useState([]);
  const [pageList, setPageList] = useState(0);
  const [filterList, setFilterList] = useState(filtersDefault);

  const [anchorEl, setAnchorEl] = useState(null);
  const [popover, setPopover] = useState(popoverDefault);
  const [chipData, setChipData] = useState([]);

  const [change, setChange] = useState(true);

  const [selectedProducts, setSelectedProducts] = useState(new Map());

  const openPopover = Boolean(anchorEl);
  const id = openPopover ? "simple-popover" : undefined;

  /**
   * Arrow function to set the page filter
   * @param {Event} evt
   * @param {String} value
   */
  const handleChangePage = (evt, value) => {
    setFilterList({
      ...filterList,
      ["page"]: value,
      ["orderBy"]: "",
      ["sort"]: "asc",
    });
  };
  /**
   * Arrow function to set the rows per page filter
   * @param {Event} evt
   */
  const handleChangeRowsPerPage = (evt) => {
    setFilterList({
      ...filterList,
      ["rowsPerPage"]: evt.target.value,
      ["orderBy"]: "",
      ["sort"]: "asc",
    });
  };
  /**
   * Arrow funciton to set order by filter
   * @param {String} value
   */
  const handleOrderBy = (value) => {
    setFilterList({
      ...filterList,
      ["orderBy"]: value,
      ["sort"]: filterList.sort === "asc" ? "desc" : "asc",
    });
  };
  /**
   * Arrow function to open and set the default values popover
   */
  const handleClickPopover = (
    event,
    label,
    column,
    type,
    maxLength,
    number
  ) => {
    setAnchorEl(event);
    setPopover({
      label: label,
      column: column,
      type: type,
      maxLength: maxLength,
      isNumber: number,
    });
  };
  /**
   * Arrow function to close popover
   */
  const handleClosePopover = () => {
    setAnchorEl(null);
  };
  /**
   * Arrow function to confirm and set the filters to list
   */
  const handleConfirmPopover = () => {
    setAnchorEl(null);
    setChipData((chips) =>
      chips.filter((chip) => chip.labelFilter !== popover.label)
    );
    setChipData((prevState) => [
      ...prevState,
      {
        labelFilter: popover.label,
        columnPopover: popover.column,
        valueFilter: popover.value,
      },
    ]);
    setFilterList({
      ...filterList,
      ["page"]: 1,
      ["filters"]: [
        {
          labelFilter: popover.label,
          columnPopover: popover.column,
          valueFilter: popover.value,
        },
      ],
    });
  };
  /**
   * Arrow function to delete the chipData list and re-set the filter to reload the page
   * @param {[]} chipToDelete
   */
  const handleDeleteChip = (chipToDelete) => () => {
    setChipData((chips) =>
      chips.filter((chip) => chip.labelFilter !== chipToDelete.labelFilter)
    );
    setFilterList({
      ...filterList,
      ["filters"]: chipData.filter(
        (chip) => chip.labelFilter !== chipToDelete.labelFilter
      ),
    });
  };
  /**
   * Arrow function to reset the filters
   */
  const handClickResetList = () => {
    setChipData([]);
    setFilterList(filtersDefault);
  };
  /**
   * Arrow function to change the status code filter to list the inactivated products
   * @param {Event} event
   */
  const handleListInactive = (event) => {
    setFilterList({
      ...filterList,
      ["page"]: 1,
      ["orderby"]: "",
      ["sort"]: "asc",
      ["filters"]: [
        {
          columnPopover: "statusCode",
          valueFilter: event.target.checked ? 1 : 0,
        },
      ],
    });
  };
  /**
   * Arrow function to add an product to Map to create the excel
   * @param {String} productUUID
   * @param {String} productDescription
   */
  const handleAddProductToCreateExcel = (productUUID, productDescription) => {
    if (selectedProducts.get(productUUID) === productDescription) {
      selectedProducts.delete(productUUID);
      setSelectedProducts(new Map(selectedProducts));
    } else {
      setSelectedProducts(
        new Map(selectedProducts).set(productUUID, productDescription)
      );
    }
  };
  const handleAddAllProductToCreateExcel = (event) => {
    if (event.target.checked) {
      let assitanceMap = new Map(selectedProducts);
      productList.map((product) =>
        assitanceMap.set(product.uuid, product.description)
      );
      setSelectedProducts(assitanceMap);
    } else {
      setSelectedProducts(new Map());
    }
  };

  const handleOpenModalToExportExcel = () => {
    const root = ReactDOM.createRoot(
      document.getElementById("modal-export-excel-product")
    );
    return root.render(
      <ModalProductExcel
        isOpen={true}
        handleUpdateSetListProducts={handleUpdateSetListProducts}
        productsToExport={selectedProducts}
      />
    );
  };

  const handleUpdateSetListProducts = (value) => {
    selectedProducts.delete(value);
    setSelectedProducts(new Map(selectedProducts));
  };

  const handleUpdatePage = () => {
    setChange(!change);
  };

  useEffect(() => {
    document.title = "Lince Tech Micro ERP | Product management";

    if (sessionStorage.getItem("pre_filters") != null) {
      const rawUser = sessionStorage.getItem("pre_filters");
      setFilterList({
        ...filterList,
        ["filters"]: JSON.parse(rawUser),
      });
      setChipData(JSON.parse(rawUser));
      sessionStorage.removeItem("pre_filters");
    }

    const getProducts = async () => {
      const response = await productUseCase.getProducts(filterList);
      setProductList(response.data.product);
      setPageList(response.data.numberPages);
    };
    getProducts();
  }, [filterList, change]);

  return (
    <Box
      sx={{
        display: "flex",
        marginLeft: "3rem",
        marginTop: "3rem",
        marginRight: "2rem",
      }}
    >
      <input type="hidden" id="modal-export-excel-product" />
      <Box sx={{ width: "100%" }}>
        <Typography sx={{ fontSize: "26pt", fontWeight: "800" }}>
          Product
        </Typography>
        <Box
          sx={{
            minWidth: "100%",
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
            marginTop: "0.5rem",
          }}
        >
          <Box
            sx={{
              display: "flex",
              alignItems: "center",
              justifyContent: "space-between",
            }}
          >
            <Box
              sx={{
                display: "flex",
                justifyContent: "center",
                flexWrap: "nowrap",
                listStyle: "none",
                p: 0,
                m: 0,
                border: "none",
                height: "4rem",
                alignItems: "center",
              }}
            >
              {chipData.map((data) => {
                return (
                  <Tooltip title={data.labelFilter} placement="top">
                    <Chip
                      sx={{
                        textOverFlow: "ellipsis",
                        overFlow: "hidden",
                        whiteSpace: "nowrap",
                        maxWidth: "145px",
                        marginRight: "1rem",
                      }}
                      color="primary"
                      variant="outlined"
                      label={data.valueFilter}
                      onDelete={handleDeleteChip(data)}
                    />
                  </Tooltip>
                );
              })}
            </Box>
            {chipData.length === 0 ? (
              <></>
            ) : (
              <Tooltip title="Clear all" placement="top">
                <Button sx={{ height: "3rem" }} onClick={handClickResetList}>
                  Clear All
                </Button>
              </Tooltip>
            )}
          </Box>
          <Box>
            <Tooltip title="Export to excel">
              <IconButton onClick={() => handleOpenModalToExportExcel()} size="large">
                <RiFileExcel2Fill />
              </IconButton>
            </Tooltip>

            <FormControlLabel
              sx={{
                align: "right",
                fontSize: "11pt",
                marginLeft: "5px",
                marginRight: 0,
              }}
              control={
                <Tooltip
                  title="List only inactivated products"
                  placement="bottom"
                >
                  <Switch onChange={handleListInactive} />
                </Tooltip>
              }
              label="List only inactivated products"
            />
          </Box>
        </Box>
        <Paper sx={{ width: "100%", overflow: "hidden", marginTop: "0.5rem" }}>
          <TableContainer sx={{ maxHeight: "85vh" }}>
            <Table
              stickyHeader
              aria-label="sticky table"
              sx={{ minWidth: "100%" }}
            >
              <TableHead>
                <StyledTableRow>
                  <StyledTableCell width={"1%"}>
                    {/* <Tooltip title="Select all" placement="top">
                      <Checkbox
                        sx={{
                          p: 0,
                          color: grey[50],
                          "&.Mui-checked": {
                            color: grey[50],
                          },
                        }}
                        onClick={handleAddAllProductToCreateExcel}
                      />
                    </Tooltip> */}
                    &nbsp;
                  </StyledTableCell>
                  {columns.map((key, index) => (
                    <StyledTableCell
                      key={index}
                      align={key.align}
                      width={key.width}
                    >
                      <Grid
                        container
                        justifyContent={
                          key.align === "center" ? "center" : "space-between"
                        }
                        flexWrap={"nowrap"}
                        alignItems={"center"}
                      >
                        <Tooltip title={key.label} placement="top">
                          {key.isOrder === true ? (
                            <TableSortLabel
                              sx={styleTableSortLabel}
                              active={filterList.orderBy === key.value}
                              direction={filterList.sort}
                              onClick={() => handleOrderBy(key.value)}
                            >
                              {key.label}
                            </TableSortLabel>
                          ) : (
                            <Typography>{key.label}</Typography>
                          )}
                        </Tooltip>
                        {key.isFilter === true && (
                          <Tooltip
                            title={`Filter by ${key.label}`}
                            placement="top"
                          >
                            <FilterListRoundedIcon
                              variant="contained"
                              onClick={(evt) =>
                                handleClickPopover(
                                  evt.currentTarget,
                                  key.label,
                                  key.value,
                                  key.type,
                                  key.maxLength,
                                  key.isNumber
                                )
                              }
                              sx={{
                                width: "18px",
                                justifySelf: "end",
                                cursor: "pointer",
                              }}
                            />
                          </Tooltip>
                        )}
                      </Grid>
                    </StyledTableCell>
                  ))}
                </StyledTableRow>
              </TableHead>
              <TableBody>
                {productList.map((product, index) => (
                  <StyledTableRow key={index}>
                    <StyledTableCell size="small" width={"1%"}>
                      <Tooltip title="Select to generate excel" placement="left">
                        <IconButton size="medium">
                          <Checkbox
                            sx={{ p: 0 }}
                            onClick={() =>
                              handleAddProductToCreateExcel(
                                product.uuid,
                                product.description
                              )
                            }
                            checked={
                              selectedProducts.get(product.uuid) ===
                              product.description
                                ? true
                                : false
                            }
                          />
                        </IconButton>
                      </Tooltip>
                    </StyledTableCell>
                    <StyledTableCell size="small">
                      {product.textCode}
                    </StyledTableCell>
                    <StyledTableCell size="small">
                      {product.description}
                    </StyledTableCell>
                    <StyledTableCell size="small">
                      {product.netValue?.toFixed(2)}
                    </StyledTableCell>
                    <StyledTableCell size="small">
                      {product.grossValue?.toFixed(2)}
                    </StyledTableCell>
                    <StyledTableCell size="small">
                      {product.salesMultiple}
                    </StyledTableCell>
                    <StyledTableCell size="small">
                      {product.unitOfMeasurement}
                    </StyledTableCell>
                    <StyledTableCell size="small">
                      {product.statusCode === 9 ? "Inactive" : "Active"}
                    </StyledTableCell>
                    <StyledTableCell size="small" align="center">
                      <Link
                        to={`${product.textCode}/ProductDetail`}
                        onClick={() =>
                          sessionStorage.setItem(
                            "pre_filters",
                            JSON.stringify(chipData)
                          )
                        }
                      >
                        <Tooltip title="Detail" placement="left">
                          <IconButton>
                            <ListRoundedIcon
                              sx={{
                                cursor: "pointer",
                                "&:hover": { textDecoration: "none" },
                              }}
                              color="action"
                            />
                          </IconButton>
                        </Tooltip>
                      </Link>
                    </StyledTableCell>
                  </StyledTableRow>
                ))}
              </TableBody>
            </Table>
          </TableContainer>
        </Paper>
        <Box
          display={"flex"}
          justifyContent={"flex-end"}
          sx={{ marginTop: "2vh", alignItems: "center", gap: "1vw" }}
        >
          <Typography sx={{ align: "center", fontSize: "11pt" }}>
            Rows Per Page
          </Typography>
          <Tooltip title="Rows per page" placement="top">
            <Select
              sx={{ height: "4vh", align: "center" }}
              autoWidth
              value={filterList.rowsPerPage}
              onChange={handleChangeRowsPerPage}
            >
              <MenuItem value={5}>5</MenuItem>
              <MenuItem value={10}>10</MenuItem>
              <MenuItem value={15}>15</MenuItem>
            </Select>
          </Tooltip>
          <Stack spacing={2}>
            <Pagination
              count={pageList}
              page={filterList.page}
              onChange={handleChangePage}
            />
          </Stack>
        </Box>

        <Popover
          id={id}
          open={openPopover}
          anchorEl={anchorEl}
          onClose={handleClosePopover}
          anchorOrigin={{
            vertical: "bottom",
            horizontal: "left",
          }}
        >
          <Box
            sx={{
              display: "flex",
              alignContent: "center",
              alignItems: "center",
              p: 2,
              gap: 2,
            }}
          >
            <Typography>Filter</Typography>
            <TextField
              type={popover.type}
              inputProps={{ maxLength: popover.maxLength }}
              variant="outlined"
              placeholder={popover.label}
              size="small"
              onKeyDown={(evt) =>
                evt.keyCode === 13 ? handleConfirmPopover() : ""
              }
              onChange={(evt) => {
                if (popover.type === "number") {
                  evt.target.value = evt.target.value.replace(/[^0-9,]/g, "");
                }
                setPopover({
                  ...popover,
                  ["value"]: evt.target.value,
                });
              }}
            ></TextField>
            <Button variant="outlined" onClick={handleConfirmPopover}>
              Confirm
            </Button>
          </Box>
        </Popover>
      </Box>
    </Box>
  );
};

export default Product;
