import { useEffect, useState } from 'react';
import { packingUseCases } from '../usecases/PackingUseCases';

import Paper from '@mui/material/Paper';
import Table from '@mui/material/Table';
import TableBody from '@mui/material/TableBody';
import TableCell from '@mui/material/TableCell';
import TableContainer from '@mui/material/TableContainer';
import TableHead from '@mui/material/TableHead';
import TableRow from '@mui/material/TableRow';
import "./LoadingPacking.css"
import { Box } from '@mui/system';


const columns = [
  { id: 'BOXNO', label: 'BOX', minWidth: 70 },
  { id: 'GROSSWEIGHT', label: 'GROSS WEIGHT (lb)', minWidth: 100 },
  {
    id: 'NETWEIGHT',
    label: 'NET WEIGHT (lb)',
    minWidth: 70,
    // align: 'right',
    // format: (value) => value.toLocaleString('en-US'),
  },
  {
    id: 'QUANTITY',
    label: 'QUANTITY',
    minWidth: 70,
    /* align: 'right', */
    // format: (value) => value.toFixed(2),
  },
  {
    id: 'UNIT',
    label: 'UNIT',
    minWidth: 70,
    /* align: 'right', */
    // format: (value) => value.toFixed(2),
  },
  {
    id: 'ARTICLE',
    label: 'ARTICLE',
    minWidth: 70,
    /* align: 'right', */
    // format: (value) => value.toFixed(2),
  },
  {
    id: 'COLOR',
    label: 'COLOR',
    minWidth: 70,
    /* align: 'right', */
    // format: (value) => value.toFixed(2),
  },
  {
    id: 'LOT',
    label: 'LOT',
    minWidth: 70,
    /* align: 'right', */
    // format: (value) => value.toFixed(2),
  },
];

export default function Products(props) {
  const [detailingProduct, setDetailingProduct] = useState([])
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(10);
  const [loading, setLoading] = useState(true);
  const handleChangePage = (event, newPage) => {
    setPage(newPage);
  };

  const handleChangeRowsPerPage = (event) => {
    setRowsPerPage(+event.target.value);
    setPage(0);
  };



  useEffect(() => {
    setLoading(true)
    const getDetailingPackingProduct = async () => {
      const detailingPackingProduct = await packingUseCases.detailingPackingProduct(props.packingId);
      setDetailingProduct(detailingPackingProduct.packings.boxes);
    }
    getDetailingPackingProduct()
      .then(() => {
        timeOutSpinner()
        setLoading(false)
      })
  }, [])

  function timeOutSpinner() {
    setLoading(true);
    setTimeout(() => {
      setLoading(false);
    }, 8000);
  }


  return (
    <Paper sx={{ width: '100%', overflow: 'hidden' }}>
      <TableContainer>
        <Table stickyHeader aria-label="sticky table">
          <TableHead>
            <TableRow sx={{ fontWeight: 10000 }}>
              {columns.map((column) => (
                <TableCell
                  key={column.id}
                  align={column.align}
                  style={{ minWidth: column.minWidth, fontWeight: "700", backgroundColor: "#ECF0F1" }}
                >
                  {column.label}
                </TableCell>
              ))}
            </TableRow>
          </TableHead>
          <TableBody>
            {detailingProduct
              .map((key) => (
                // <TableRow hover role="checkbox" tabIndex={-1} key={index}>
                key.itens.map((item, index) => (
                  <TableRow hover role="checkbox" tabIndex={-1} key={index}>
                    <TableCell align={key.align}>{key.number}</TableCell>
                    <TableCell >{new Intl.NumberFormat('en-US', { style: 'decimal', unit: 'pound', minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(item.variant.product.grossValue * item.quantity)}</TableCell>
                    <TableCell >{new Intl.NumberFormat('en-US', { style: 'decimal', unit: 'pound', minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(item.variant.product.netValue * item.quantity)}</TableCell>
                    {/* <TableCell align={key.align}>{item.variant.product.grossValue}</TableCell>
                    <TableCell align={key.align}>{item.variant.product.netValue}</TableCell> */}
                    <TableCell align={key.align}>{item.quantity}</TableCell>
                    <TableCell align={key.align}>{item.unity}</TableCell>
                    <TableCell align={key.align}>{item.variant.product.description}</TableCell>
                    <TableCell align={key.align}>{item.variant.color.description}</TableCell>
                    <TableCell align={key.align}>{key.batch}</TableCell>
                  </TableRow>
                ))
              ))}
          </TableBody>
        </Table>
      </TableContainer>
      {loading ? <Box sx={{ width: '100%', height: '100%', display: 'flex', justifyContent: 'center', padding: '10%' }}><div className="loading-packing"></div></Box> : <></>}
    </Paper>
  )

}