export class Price {
  /**
  * @param {int} uuid 
  * @param {int} code 
  * @param {string} name 
  * @param {boolean} isActive 
  * @param {string} initial 
  * @param {string} final 
  */
  constructor(uuid, code, name, isActive, initial, final) {
    this.uuid = uuid;
    this.code = code;
    this.name = name;
    this.isActive = isActive;
    this.initial = initial;
    this.final = final;
  }
}

export class PagedPrice {
  /**
   * @param prices {Price[]}
   * @param numberOfPages {number}
   */
  constructor(prices, numberOfPages) {
    this.prices = prices
    this.numberOfPages = numberOfPages
  }
}