import * as React from "react";
import { useEffect, useState } from "react";
import Box from "@mui/material/Box";
import Typography from "@mui/material/Typography";
import ArrowBackRoundedIcon from "@mui/icons-material/ArrowBackRounded";
import Paper from "@mui/material/Paper";
import { styled } from "@mui/material/styles";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableCell, { tableCellClasses } from "@mui/material/TableCell";
import TableContainer from "@mui/material/TableContainer";
import TableHead from "@mui/material/TableHead";
import TableRow from "@mui/material/TableRow";
import { productDetailUseCase } from "../usecases/ProductDetailUseCases";
import EditRoundedIcon from '@mui/icons-material/EditRounded';
import ModalProductUpdate from "../components/ModalProductUpdate";
import { useNavigate, useParams } from "react-router-dom";
import { createRoot } from "react-dom/client";
import { IconButton, InputLabel, Tooltip } from "@mui/material";

//STYLES
const StyledTableCell = styled(TableCell)(({ theme }) => ({
  [`&.${tableCellClasses.head}`]: {
    backgroundColor: "#15191C",
    color: theme.palette.common.white,
  },
  [`&.${tableCellClasses.body}`]: {
    fontSize: 14,
  },
}));

const StyledTableRow = styled(TableRow)(({ theme }) => ({
  "&:nth-of-type(odd)": {
    backgroundColor: theme.palette.action.hover,
  },
  "&:last-child td, &:last-child th": {
    border: 0,
  },
}));

const ProductDetail = () => {
  const [variants, setVariant] = useState([]);

  const [code, setCode] = useState(useParams().code);
  const [productDetail, setProductDetail] = useState();
  const [product, setProduct] = useState();
  const [pageList, setPageList] = useState(0);
  const [page, setPage] = useState(1);
  const [rowsPerPage, setRowsPerPage] = useState(10);
  const [changed, setChanged] = useState("");

  const navigate = useNavigate();

  const handleChangeEdit = () => {
    setChanged(!changed);
  };

  const previousPage = () => {
    navigate(-1);
  };

  const handleProductUpdate = (evt, productUui) => {
    evt.preventDefault();
    const container = document.getElementById(`modal-product`);
    const root = createRoot(container);
    return root.render(
      <ModalProductUpdate isOpen={true} productUuid={productUui} productCode={code} parentCallback={handleChangeEdit} />
    );
  };

  useEffect(() => {
    const getProductDetail = async () => {
      const productDetailRequest = await productDetailUseCase.getProductDetail(
        code
      );
      setProductDetail(productDetailRequest);
      const pagedVariant = await productDetailUseCase.getVariants(
        productDetailRequest.uuid,
        page,
        rowsPerPage
      );
      setVariant(pagedVariant.variants);
      setPageList(pagedVariant.numberOfPages);
    };
    getProductDetail();

  }, [code, page, rowsPerPage, changed]);

  return (
    <Box sx={{ width: "100%", height: "100vh", padding: "2rem" }}>
      <input type="hidden" id="modal-product" />
      <Box
        sx={{
          display: "flex",
          justifyContent: "start",
          alignItems: "center",
        }}
      >
        <ArrowBackRoundedIcon
          titleAccess="Previous page"
          fontSize="large"
          sx={{
            cursor: "pointer",
            "&:hover": { color: "GrayText" },
          }}
          onClick={previousPage}
        />
        <Typography
          sx={{
            fontSize: "26pt",
            fontWeight: "800",
            marginLeft: "1rem",
          }}
        >
          Product Detail
        </Typography>
        <Tooltip title="Edit">
          <IconButton onClick={(evt) => handleProductUpdate(evt, productDetail.uuid)} sx={{ marginLeft: "1rem" }}>
            <EditRoundedIcon fontSize="large" />
          </IconButton>
        </Tooltip>
      </Box>
      <Box
        sx={{
          marginTop: "3rem",
          marginLeft: "2rem",
          width: "100%",
          display: "grid",
          gridGap: "1rem",
          gridTemplateColumns: "repeat(auto-fit, minmax(300px, 400px))",
          flexWrap: "wrap",
        }}
      >
        <Box sx={{ display: "flex", flexDirection: "column" }}>
          <Box sx={{ display: "flex", flexDirection: "row" }}>
            <InputLabel sx={{ width: "10rem", textAlign: "right" }}>
              Product code
            </InputLabel>
            <InputLabel
              sx={{ marginLeft: "1rem", fontWeight: "bold", width: "auto" }}
            >
              {productDetail != null ? productDetail.textCode : ""}
            </InputLabel>
          </Box>
          <Box sx={{ display: "flex", flexDirection: "row" }}>
            <InputLabel sx={{ width: "10rem", textAlign: "right" }}>
              Description
            </InputLabel>
            <InputLabel sx={{ marginLeft: "1rem", fontWeight: "bold" }}>
              {productDetail != null ? productDetail.description : ""}
            </InputLabel>
          </Box>
          <Box sx={{ display: "flex", flexDirection: "row" }}>
            <InputLabel sx={{ width: "10rem", textAlign: "right" }}>
              Gross value
            </InputLabel>
            <InputLabel
              sx={{ marginLeft: "1rem", fontWeight: "bold", width: "auto" }}
            >
              {productDetail?.grossValue?.toFixed(2) ?? ""}
            </InputLabel>
          </Box>
          <Box sx={{ display: "flex", flexDirection: "row" }}>
            <InputLabel sx={{ width: "10rem", textAlign: "right" }}>
              Net value
            </InputLabel>
            <InputLabel
              sx={{ marginLeft: "1rem", fontWeight: "bold", width: "auto" }}
            >
              {productDetail?.netValue?.toFixed(2) ?? ""}
            </InputLabel>
          </Box>
          <Box sx={{ display: "flex", flexDirection: "row" }}>
            <InputLabel sx={{ width: "10rem", textAlign: "right" }}>
              Width
            </InputLabel>
            <InputLabel
              sx={{ marginLeft: "1rem", fontWeight: "bold", width: "auto" }}
            >
              {productDetail?.width?.toFixed(2) ?? ""}
            </InputLabel>
          </Box>
          <Box sx={{ display: "flex", flexDirection: "row" }}>
            <InputLabel sx={{ width: "10rem", textAlign: "right" }}>
              Height
            </InputLabel>
            <InputLabel
              sx={{ marginLeft: "1rem", fontWeight: "bold", width: "auto" }}
            >
              {productDetail?.height?.toFixed(2) ?? ""}
            </InputLabel>
          </Box>
          <Box sx={{ display: "flex", flexDirection: "row" }}>
            <InputLabel sx={{ width: "10rem", textAlign: "right" }}>
              Instruction
            </InputLabel>
            <InputLabel
              sx={{ marginLeft: "1rem", fontWeight: "bold", width: "17rem" }}
            >
              {productDetail != null ? productDetail.instructions : ""}
            </InputLabel>
          </Box>
        </Box>
        <Box sx={{ display: "flex", flexDirection: "column" }}>
          <Box sx={{ display: "flex", flexDirection: "row" }}>
            <InputLabel
              sx={{
                width: "10rem",
                textAlign: "right",
              }}
            >
              Status
            </InputLabel>
            <InputLabel sx={{ fontWeight: "bold", marginLeft: "1rem" }}>
              {productDetail != null
                ? productDetail.statusCode == 9
                  ? "Inactive"
                  : "Active"
                : ""}
            </InputLabel>
          </Box>
          <Box sx={{ display: "flex", flexDirection: "row" }}>
            <InputLabel
              sx={{
                width: "10rem",
                textAlign: "right",
              }}
            >
              Unit of measurement
            </InputLabel>
            <InputLabel
              sx={{ marginLeft: "1rem", fontWeight: "bold", width: "5rem" }}
            >
              {productDetail != null ? productDetail.unitOfMeasurement : ""}
            </InputLabel>
          </Box>
          <Box sx={{ display: "flex", flexDirection: "row" }}>
            <InputLabel
              sx={{
                width: "10rem",
                textAlign: "right",
              }}
            >
              Sales multiple
            </InputLabel>
            <InputLabel
              sx={{ marginLeft: "1rem", fontWeight: "bold", width: "5rem" }}
            >
              {productDetail != null ? productDetail.salesMultiple : ""}
            </InputLabel>
          </Box>
          <Box sx={{ display: "flex", flexDirection: "row" }}>
            <InputLabel
              sx={{
                width: "10rem",
                textAlign: "right",
              }}
            >
              Volume
            </InputLabel>
            <InputLabel
              sx={{ marginLeft: "1rem", fontWeight: "bold", width: "5rem" }}
            >
              {productDetail?.volume?.toFixed(2) ?? ""}
            </InputLabel>
          </Box>
          <Box sx={{ display: "flex", flexDirection: "row" }}>
            <InputLabel
              sx={{
                width: "10rem",
                textAlign: "right",
              }}
            >
              Cube
            </InputLabel>
            <InputLabel
              sx={{ marginLeft: "1rem", fontWeight: "bold", width: "5rem" }}
            >
              {productDetail?.cube?.toFixed(3) ?? ""}
            </InputLabel>
          </Box>
          <Box sx={{ display: "flex", flexDirection: "row" }}>
            <InputLabel sx={{ width: "10rem", textAlign: "right" }}>
              DUN14
            </InputLabel>
            <InputLabel
              sx={{ marginLeft: "1rem", fontWeight: "bold", width: "auto" }}
            >
              {productDetail != null ? productDetail.dun14 : ""}
            </InputLabel>
          </Box>
          <Box sx={{ display: "flex", flexDirection: "row" }}>
            <InputLabel sx={{ width: "10rem", textAlign: "right" }}>
              Technical Description
            </InputLabel>
            <InputLabel
              sx={{ marginLeft: "1rem", fontWeight: "bold", width: "17rem" }}
            >
              {productDetail != null ? productDetail.technicalDescription : ""}
            </InputLabel>
          </Box>
        </Box>
      </Box>
      <Box sx={{ marginTop: "3rem" }}>
        <Paper
          sx={{
            justifyContent: "center",
          }}
        >
          <TableContainer component={Paper}>
            <Table aria-label="Product Colors Table" sx={{ width: "100%" }}>
              <TableHead>
                <TableRow>
                  <StyledTableCell sx={{ width: "20%" }} align={"right"}>
                    Code
                  </StyledTableCell>
                  <StyledTableCell sx={{ width: "50%" }} align={"left"}>
                    Description
                  </StyledTableCell>
                  <StyledTableCell sx={{ width: "20%" }} align={"right"}>
                    EAN13
                  </StyledTableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {variants.map((variant) => (
                  <StyledTableRow key={variant.uuid}>
                    <StyledTableCell align={"right"}>
                      {variant.color.code}
                    </StyledTableCell>
                    <StyledTableCell align={"left"}>
                      {variant.description == ""
                        ? variant.color.description
                        : variant.description}
                    </StyledTableCell>
                    <StyledTableCell align={"right"}>
                      {variant.color.ean13}
                    </StyledTableCell>
                  </StyledTableRow>
                ))}
              </TableBody>
            </Table>
          </TableContainer>
        </Paper>
      </Box>
    </Box>
  );
}

export default ProductDetail;
