import { warehouseRepository } from "../repositories/WarehouseRepositories";

class WarehouseUseCase {
  async postWarehouse(warehouse) {
    const errors = new Map();
    /**
     * - *English* Function called for email format validation
     * - *Português* Função chamada para validação de formato de email
     * - @param email
     */
    function isValidEmail(email) {
      return /\S+@\S+\.\S+/.test(email);
    }
    if (warehouse.uuid === null) {
      if (isNaN(warehouse.code) || warehouse.code === "") {
        const errorCode = { key: "code" };
        errors.set(errorCode, "Code is invalid");
      }
    }
    if (warehouse.phone.trim() !== "") {
      if (warehouse.phone.length < 13) {
        const errorCode = { key: "phone" };
        errors.set(errorCode, "Phone is Invalid");
      }
    }
    if (warehouse.description === "") {
      const errorCode = { key: "description" };
      errors.set(errorCode, "Description must not be empty");
    }
    if (warehouse.email === "") {
      const errorCode = { key: "email" };
      errors.set(errorCode, "E-mail must not be empty");
    }
    if (isNaN(warehouse.capacity)) {
      const errorCode = { key: "maxCapacity" };
      errors.set(errorCode, "Maxcapacity must be an numeric value");
    }
    if (warehouse.address === "") {
      const errorCode = { key: "address" };
      errors.set(errorCode, "Address must not be empty");
    }
    if (!isValidEmail(warehouse.email)) {
      const errorCode = { key: "email" };
      errors.set(errorCode, "Email is invalid");
    }
    if (errors.size > 0) {
      return errors;
    }
    try {
      return await warehouseRepository.postWarehouse(warehouse);
    } catch (error) {
      return error;
    }
  }

  /**
   * @param page {int}
   * @param rowsPerPage {int}
   * @param orderBy {string}
   * @param situation {string}
   * @param sort {string}
   * @param chipData {string}
   * @returns {Promise<PagedWarehouses>}
   */
  async listWarehouses(page, rowsPerPage, situation, orderBy, sort, chipData) {
    const response = await warehouseRepository.listWarehouses(
      page,
      rowsPerPage,
      orderBy,
      situation,
      sort,
      chipData
    );
    return response;
  }
  /**
   * @param warehousesId {Number}
   * @returns {Object}
   */
  async getInformationWarehouse(warehousesId) {
    const response = await warehouseRepository.getInfoWarehouse(warehousesId);
    return response;
  }
}

export const warehouseUseCase = new WarehouseUseCase();
