export class Filter {
    /**
     *
     * @param column {string}
     * @param value {string}
     */
    constructor(column, value) {
        this.column = column
        this.value = value
    }
}

/**
 *
 */
export class PackingClass {
    /**
     * 
     * @param uuid  {Number}
     * @param comex {Number}
     * @param buyer {string}
     * @param warehouse  {string}
     * @param receiveDate {Date}
     * @param sendDate {Date}
     * @param totalGrossWeight {Number}
     * @param totalNetWeight {Number}
     * @param boxTotalQuantity {Number}
     * @param totalCubeMeter {Number}
     */
    constructor(uuid, comex, buyer, warehouse, receiveDate, sendDate, totalGrossWeight, totalNetWeight, boxTotalQuantity, totalCubeMeter) {
        this.uuid = uuid
        this.comex = comex
        this.buyer = buyer
        this.warehouse = warehouse
        this.receiveDate = receiveDate
        this.sendDate = sendDate
        this.totalGrossWeight = totalGrossWeight
        this.totalNetWeight = totalNetWeight
        this.boxTotalQuantity = boxTotalQuantity
        this.totalCubeMeter = totalCubeMeter
    }
}


export class PagedPacking {
    /**
     *
     * @param packings {Packing[]}
     * @param numberPages {number}
     */
    constructor(packings, numberPages) {
        this.packings = packings
        this.numberPages = numberPages
    }
}
export class requestPacking {
    /**
     *
     * @param packings {Packing[]}
     */
    constructor(packings) {
        this.packings = packings
    }
}