export class FiltersList {
  /**
   * @param {Number} page
   * @param {Number} rowsPerPage
   * @param {String} orderBy
   * @param {String} sort
   * @param {Array} filters
   */
  constructor(page, rowsPerPage, orderBy, sort, filters) {
    this.page = page;
    this.rowsPerPage = rowsPerPage;
    this.orderBy = orderBy;
    this.sort = sort;
    this.filters = filters;
  }
}

export class PopoverClass{
  /**
   * @param {String} label 
   * @param {String} column 
   * @param {String} type 
   * @param {Number} maxLength 
   * @param {Boolean} isNumber 
   * @param {String} value 
   */
  constructor(label, column, type, maxLength, isNumber, value){
    this.label = label;
    this.column = column;
    this.type = type;
    this.maxLength = maxLength;
    this.isNumber = isNumber;
    this.value = value;
  }
}
