import * as React from "react";

import { useEffect, useState } from "react";
import Dialog from "@mui/material/Dialog";
import DialogActions from "@mui/material/DialogActions";
import DialogContent from "@mui/material/DialogContent";
import DialogTitle from "@mui/material/DialogTitle";
import { productDetailUseCase } from "../usecases/ProductDetailUseCases";
import { Box } from "@mui/system";
import { Button, TextField, Typography } from "@mui/material";
import Swal from "sweetalert2";

const Toast = Swal.mixin({
  toast: true,
  position: "top-end",
  showConfirmButton: false,
  timer: 3000,
  timerProgressBar: true,
  didOpen: (toast) => {
    toast.addEventListener("mouseenter", Swal.stopTimer);
    toast.addEventListener("mouseleave", Swal.resumeTimer);
  },
});

const ProductUpdate = ({
  isOpen,
  productUuid,
  productCode,
  parentCallback,
}) => {
  const [open, setOpen] = useState(isOpen);

  const [values, setValues] = useState({
    instructions: "",
    technicalDescription: "",
  });

  const handleChange = (event) => {
    const { name, value } = event.target;
    setValues({ ...values, [name]: value });
  };

  const handleClose = () => {
    setOpen(false);
  };

  const handleUpdateProduct = () => {
    productDetailUseCase
      .postProductInstruction(
        productUuid,
        values.instructions,
        values.technicalDescription
      )
      .then((response) => {
        if (response instanceof Error) {
          return Swal.fire({
            icon: "warning",
            title: "Error",
            text: response.message,
          });
        } else if (response?.data?.error !== null) {
          return Swal.fire({
            icon: "warning",
            title: "Error",
            text: response?.data?.error?.description ?? "",
          });
        } else {
          parentCallback();
          handleClose();
          return Toast.fire({
            icon: "success",
            text: "Successfully changed",
          });
        }
      });
  };

  useEffect(() => {
    const getProductDetail = async () => {
      const productDetailRequest = await productDetailUseCase.getProductDetail(
        productCode
      );
      return productDetailRequest;
    };
    getProductDetail().then((response) => {
      setValues({
        instructions: response?.instructions ?? "",
        technicalDescription: response?.technicalDescription ?? "",
      });
    });
  }, [open]);

  return (
    <Dialog
      open={open}
      onClose={handleClose}
      scroll={"body"}
      maxWidth="sm"
      fullWidth
    >
      <DialogTitle id="scroll-dialog-title">
        <Box sx={{ display: "flex", justifyContent: "space-between" }}>
          <Typography
            sx={{
              fontSize: "1.2em",
              fontWeight: "700",
              color: "#363636",
            }}
          >
            Product Update
          </Typography>
        </Box>
      </DialogTitle>
      <DialogContent sx={{ height: "40vh", display: "grid", gap: "2rem" }}>
        <TextField
          multiline
          rows={4}
          label="Instructions"
          name="instructions"
          sx={{ marginTop: "1rem" }}
          value={values.instructions}
          onChange={(event) => handleChange(event)}
        ></TextField>
        <TextField
          multiline
          rows={4}
          label="Technical Description"
          name="technicalDescription"
          value={values.technicalDescription}
          onChange={(event) => handleChange(event)}
        ></TextField>
      </DialogContent>
      <DialogActions>
        <Box
          sx={{
            display: "flex",
            justifyContent: "end",
            marginBottom: "15px",
            marginRight: "15px",
            gap: "20px",
          }}
        >
          <Button variant="contained" onClick={handleUpdateProduct}>
            Update
          </Button>
          <Button variant="outlined" onClick={handleClose}>
            Close
          </Button>
        </Box>
      </DialogActions>
    </Dialog>
  );
};

export default ProductUpdate;
