import {
  Box,
  Button,
  FormControl,
  InputLabel,
  MenuItem,
  Modal,
  Select,
  TextField,
  Typography,
} from "@mui/material";
import React from "react";
import ReactInputMask from "react-input-mask";
import { Warehouse } from "../entities/entities";
import AddHomeRoundedIcon from "@mui/icons-material/AddHomeRounded";
import { warehouseUseCase } from "../usecases/WarehouseUseCases";
import Swal from "sweetalert2";

const warehouseRegisterModalStyle = {
  position: "absolute",
  top: "50%",
  left: "50%",
  transform: "translate(-50%, -50%)",
  minWidth: "60%",
  backgroundColor: "#ffffff",
  borderRadius: "10px",
  boxShadow: 24,
  p: 4,
  display: "flex",
  flexDirection: "row",
  overflow: "hidden",
  outline: "none",
  flexWrap: "wrap",
};
const warehouseSituationOption = [
  {
    value: 0,
    label: "Active",
  },
  {
    value: 1,
    label: "Inactive",
  },
];
const warehouseSeparationOption = [
  {
    value: false,
    label: "No",
  },
  {
    value: true,
    label: "Yes",
  },
];
const Toast = Swal.mixin({
  toast: true,
  position: "top-end",
  showConfirmButton: false,
  timer: 3000,
  timerProgressBar: true,
  didOpen: (toast) => {
    toast.addEventListener("mouseenter", Swal.stopTimer);
    toast.addEventListener("mouseleave", Swal.resumeTimer);
  },
});

const ModalWarehouse = ({ warehouseCode, isOpen, parentCallback }) => {
  const [open, setOpen] = React.useState(isOpen);
  const [error, setError] = React.useState([]);
  const [warehouseObject, setWarehouseObject] = React.useState(
    new Warehouse("", "", "", "", "", "", "", "", "")
  );

  const handleOnChange = (evt) => {
    const { name, value } = evt.target;
    setWarehouseObject({
      ...warehouseObject,
      [name]:
        name === "phone"
          ? value
            .replace("+", "")
            .replace("-", " ")
            .replace("(", "")
            .replace(")", "")
            .replace(" ", "")
            .replace(/\s/g, "")
          : value,
    });
  };

  React.useEffect(() => {
    if (warehouseCode !== undefined) {
      const getWarehouseInformation = async () => {
        const getWarehouse = await warehouseUseCase.getInformationWarehouse(
          warehouseCode
        );
        for (const response of getWarehouse) {
          setWarehouseObject(
            new Warehouse(
              response.id,
              response.code,
              response.description,
              response.address,
              response.email,
              response.phone,
              response.statusCode,
              response.maxCapacity,
              response.separationIndicator
            )
          );
        }
      };
      getWarehouseInformation();
    }
  }, []);

  const handleCloseModal = () => {
    setOpen(!open);
    setWarehouseObject(new Warehouse("", "", "", "", "", "", "", "", ""));
  };

  const handleRegisterWarehouse = async () => {
    const response = await warehouseUseCase.postWarehouse(
      new Warehouse(
        warehouseCode !== undefined ? warehouseObject.uuid : null,
        warehouseObject.code,
        warehouseObject.description,
        warehouseObject.address,
        warehouseObject.email,
        warehouseObject.phone,
        warehouseObject.situation,
        warehouseObject.capacity,
        warehouseObject.separation
      )
    );
    if (response.size) {
      const error = response.values();
      const errorKey = response.keys();
      setError(errorKey.next().value.key);
      return Swal.fire({
        icon: "warning",
        confirmButtonText: "OK",
        text: error.next().value,
      });
    }
    if (!response.status) {
      return Swal.fire({
        icon: "error",
        confirmButtonText: "OK",
        text: "Connection error",
      });
    }
    if (response.data.error !== null) {
      return Swal.fire({
        icon: "error",
        confirmButtonText: "OK",
        text: response.data.error.description,
      });
    } else {
      parentCallback(true);
      handleCloseModal();
      return Toast.fire({
        icon: "success",
        text: "Successfully registered",
      });
    }
  };

  return (
    <Modal open={open} onClose={handleCloseModal}>
      <Box sx={warehouseRegisterModalStyle}>
        <Box
          sx={{
            display: "flex",
            justifyContent: "space-between",
            width: "100%",
          }}
        >
          <Typography
            sx={{ fontSize: "1.5rem", fontWeight: "700", color: "#363636" }}
            component="h2"
          >
            {warehouseCode !== undefined ? 'Edit' : 'Register'} Warehouse
          </Typography>
          <AddHomeRoundedIcon fontSize="large" />
        </Box>
        <Box
          sx={{
            marginTop: "1.5rem",
            width: "100%",
            display: "grid",
            gridGap: "1rem",
            gridTemplateColumns:
              "repeat(auto-fit, minmax(200px, 1fr) minmax(200px, 1fr))",
          }}
        >
          <TextField
            label="Code"
            variant="standard"
            name="code"
            inputProps={warehouseCode !== undefined ? { maxLength: 10, readOnly: true } : { maxLength: 10 }}
            value={warehouseObject.code}
            onChange={(evt) => {
              evt.target.value = evt.target.value.replace(/[^0-9,]/g, "");
              handleOnChange(evt);
              setError([]);
            }}
            required
            {...(error === "code" && { error })}
          />
          <TextField
            label="Capacity"
            variant="standard"
            name="capacity"
            inputProps={{ maxLength: 10 }}
            value={warehouseObject.capacity}
            onChange={(evt) => {
              evt.target.value = evt.target.value.replace(/[^0-9,]/g, "");
              handleOnChange(evt);
              setError([]);
            }}
          />
          <FormControl variant="standard">
            <InputLabel id="id-situation-form-wharehouse">Situation</InputLabel>
            <Select
              labelId="id-situation-form-wharehouse"
              label="Situation"
              value={warehouseObject.situation}
              name="situation"
              onChange={(evt) => {
                handleOnChange(evt);
                setError([]);
              }}
            >
              {warehouseSituationOption.map((item, index) => (
                <MenuItem key={index} value={item.value}>
                  {item.label}
                </MenuItem>
              ))}
            </Select>
          </FormControl>
          <FormControl variant="standard">
            <InputLabel id="id-separation-form-wharehouse">
              Separation
            </InputLabel>
            <Select
              labelId="id-separation-form-wharehouse"
              value={warehouseObject.separation}
              name="separation"
              onChange={(evt) => {
                handleOnChange(evt);
                setError([]);
              }}
            >
              {warehouseSeparationOption.map((item, index) => (
                <MenuItem key={index} value={item.value}>
                  {item.label}
                </MenuItem>
              ))}
            </Select>
          </FormControl>
        </Box>
        <Box sx={{ width: "100%", marginTop: "1rem" }}>
          <TextField
            label="Description"
            variant="standard"
            name="description"
            inputProps={{ maxLength: 60 }}
            value={warehouseObject.description}
            onChange={(evt) => {
              handleOnChange(evt);
              setError([]);
            }}
            fullWidth
            required
            {...(error === "description" && { error })}
          />
        </Box>
        <Box sx={{ width: "100%", marginTop: "1rem" }}>
          <TextField
            label="Address"
            variant="standard"
            name="address"
            inputProps={{ maxLength: 60 }}
            value={warehouseObject.address}
            onChange={(evt) => {
              handleOnChange(evt);
              setError([]);
            }}
            fullWidth
            required
            {...(error === "address" && { error })}
          />
        </Box>
        <Box
          sx={{
            width: "100%",
            display: "grid",
            gridGap: "1rem",
            gridTemplateColumns: "repeat(auto-fit, minmax(250px, 1fr) minmax(200px, 0.5fr))",
            marginTop: "1rem",
          }}
        >
          <TextField
            label="E-mail"
            variant="standard"
            name="email"
            inputProps={{ maxLength: 60 }}
            value={warehouseObject.email}
            onChange={(evt) => {
              handleOnChange(evt);
              setError([]);
            }}
            fullWidth
            required
            {...(error === "email" && { error })}
          />
          <ReactInputMask
            mask="+ (999) 9 99999-9999"
            maskChar=""
            onChange={(evt) => {
              handleOnChange(evt);
              setError([]);
            }}
            value={warehouseObject.phone}
          >
            {() => (
              <TextField
                label="Phone"
                variant="standard"
                name="phone"
                {...(error === "phone" && { error })}
              />
            )}
          </ReactInputMask>
        </Box>
        <Box
          sx={{
            width: "100%",
            marginTop: "1rem",
            display: "flex",
          }}
        >
          <Box
            sx={{
              marginTop: "1.5rem",
              width: "100%",
              display: "grid",
              gridGap: "1rem",
              gridTemplateColumns: "repeat(auto-fill, minmax(150px, 1fr))",
              direction: "rtl",
            }}
          >
            <Button
              onClick={() => {
                handleRegisterWarehouse();
              }}
              variant="contained"
            >
              Register
            </Button>
            <Button onClick={handleCloseModal} variant="outlined" color="error">
              Cancel
            </Button>
          </Box>
        </Box>
      </Box>
    </Modal>
  );
};

export default ModalWarehouse;
