import {
  AppBar,
  Button,
  Container,
  Divider,
  Toolbar,
  Typography,
} from "@mui/material";
import { Box } from "@mui/system";
import React from "react";
import WarehouseIcon from "@mui/icons-material/Warehouse";
import Inventory2Icon from "@mui/icons-material/Inventory2";
import User from "@mui/icons-material/Group";
import LocalOfferIcon from "@mui/icons-material/LocalOfferRounded";
import ReactDOM from "react-dom/client";
import ModalProductsCart from "../../internationalization/stock/components/ModalProductsCart";
import ShoppingCartCheckoutIcon from "@mui/icons-material/ShoppingCartCheckout";

const logoLinceBase64 = "data:image/png;base64,"

const MainPage = () => {
  const [userName, setUserName] = React.useState("");
  const user = JSON.parse(localStorage.getItem("user"));

  const handleOpenCart = () => {
    const root = ReactDOM.createRoot(document.getElementById("cart"));
    return root.render(
      <ModalProductsCart
        sx={{ zIndex: "-20" }}
        isOpen={true}
        parentCallback={() => {}}
      />
    );
  };

  React.useEffect(() => {
    setUserName(user.name);
    document.title = "Lince Tech Micro ERP";
  }, []);

  return (
    <Box
      sx={{
        width: "100%",
        height: "100%",
        display: "flex",
        flexDirection: "column",
      }}
    >
      <input type="hidden" id="cart" />
      <AppBar position="static" sx={{ backgroundColor: "#15191C", p: 2 }}>
        <Container maxWidth="xl">
          <Toolbar
            disableGutters
            sx={{ display: "flex", justifyContent: "space-between" }}
          >
            <Typography
              sx={{
                fontSize: "24pt",
                fontWeight: "800",
                color: "#FFF",
              }}
            >
              Lince Tech Micro ERP
            </Typography>
            <img
              src={logoLinceBase64}
              alt="Logo lince tech"
              width={"90rem"}
              style={{ marginRight: "1em" }}
            />
          </Toolbar>
        </Container>
      </AppBar>
      <Box sx={{m: 12}}>
        <Typography
          sx={{
            fontSize: "26pt",
            fontWeight: "800",
            p: 0,
            justifyContent: "space-between",
            display: "flex",
            width: "100%",
          }}
        >
          Hello, welcome back {userName}
        </Typography>
        <Box
          sx={{ p: 2, marginTop: "3rem" }}
          display={"flex"}
          flexDirection={"column"}
        >
          <Box>
            <Button color="inherit" onClick={() => handleOpenCart()}>
              <ShoppingCartCheckoutIcon fontSize="large" />
              <Typography sx={{ marginLeft: "1.5rem" }}>View cart</Typography>
            </Button>
          </Box>
          <Divider width={"20%"} />
          <Box marginTop={"2rem"}>
            <Button color="inherit" href="/web/warehouse">
              <WarehouseIcon fontSize="large" />
              <Typography sx={{ marginLeft: "1.5rem" }}>
                view warehouses
              </Typography>
            </Button>
          </Box>
          <Divider width={"20%"} />
          <Box marginTop={"2rem"}>
            <Button color="inherit" href="/web/Stock">
              <Inventory2Icon fontSize="large" />
              <Typography sx={{ marginLeft: "1.5rem" }}>
                view stock listing
              </Typography>
            </Button>
          </Box>
          <Divider width={"20%"} />
          <Box marginTop={"2rem"}>
            <Button color="inherit" href="/web/User">
              <User fontSize="large" />
              <Typography sx={{ marginLeft: "1.5rem" }}>
                view users listing
              </Typography>
            </Button>
          </Box>
          <Divider width={"20%"} />
          <Box marginTop={"2rem"}>
            <Button color="inherit" href="/web/Product">
              <LocalOfferIcon fontSize="large" />
              <Typography sx={{ marginLeft: "1.5rem" }}>
                view products listing
              </Typography>
            </Button>
          </Box>
        </Box>
      </Box>
    </Box>
  );
};

export default MainPage;
