export class Filter {
  /**
   *
   * @param column {string}
   * @param value {string}
   */
  constructor(column, value) {
    this.column = column;
    this.value = value;
  }
}

/**
 *
 */
export class RequestHistoryClass {
  /**
   *
   * @param uuid  {Number}
   * @param originWarehouse {Number}
   * @param destinyWarehouse {Number}
   * @param condition {Number}
   * @param statusCode {Number}
   * @param createdAt {Number}
   * @param modifiedAt {Number}
   */
  constructor(
    uuid,
    originWarehouse,
    destinyWarehouse,
    condition,
    statusCode,
    createdAt,
    modifiedAt
  ) {
    this.uuid = uuid;
    this.originWarehouse = originWarehouse;
    this.destinyWarehouse = destinyWarehouse;
    this.condition = condition;
    this.statusCode = statusCode;
    this.createdAt = createdAt;
    this.modifiedAt = modifiedAt;
  }
}

export class PagedRequestHistory {
  /**
   * @param requestHistory {Packing[]}
   * @param numberPages {number}
   */
  constructor(requestHistory, numberPages) {
    this.requestHistory = requestHistory;
    this.numberPages = numberPages;
  }
}

export class Product {
  /**
   *
   * @param warehouse {Warehouse}
   * @param product {Product}
   * @param totalQuantity {int}
   * @param availableQuantity {int}
   * @param requestedQuantity {int}
   */
  constructor(warehouse, product, totalQuantity, availableQuantity, requestedQuantity ) {
    this.warehouse = warehouse;
    this.product = product;
    this.totalQuantity = totalQuantity;
    this.availableQuantity = availableQuantity;
    this.requestedQuantity = requestedQuantity;
  }
}

export class BoxRequest {
  /**
   *
   * @param boxes {boxes}
   * @param color {Color}
   * @param product {Product}
   * @param barCode {string}
   * @param quantity {int}
   * @param unity {string}
   * @param batch {string}
   *
   * */

  constructor(boxes, color, product, barCode, quantity, unity, batch) {
    this.boxes = boxes;
    this.color = color;
    this.product = product;
    this.barCode = barCode;
    this.quantity = quantity;
    this.unity = unity;
    this.batch = batch;
  }
}

export class PagedStock {
  /**
   *
   * @param stock {Stock[]}
   * @param numberOfPages {number}
   */
  constructor(stock, numberOfPages) {
    this.stock = stock;
    this.numberOfPages = numberOfPages;
  }
}
export class PagedBoxRequest {
  /**
   *
   * @param boxRequest {BoxRequest[]}
   * @param numberOfPages {number}
   *
   */

  constructor(boxRequest, numberOfPages) {
    this.boxRequest = boxRequest;
    this.numberOfPages = numberOfPages;
  }
}
