import * as React from "react";
import { warehouseUseCase } from "../usecases/WarehouseUseCases";
import { useEffect, useState } from "react";
import { styled } from "@mui/material/styles";
import { createRoot } from "react-dom/client";
import {
  Box,
  TextField,
  Paper,
  Chip,
  Tooltip,
  Button,
  Typography,
  Table,
  TableBody,
  TableCell,
  tableCellClasses,
  TableContainer,
  TableHead,
  FormControlLabel,
  Switch,
  TableRow,
  Select,
  MenuItem,
  Pagination,
  Stack,
  TableSortLabel,
  Grid,
  Popover,
  FormControl,
} from "@mui/material";
import EditIcon from "@mui/icons-material/Edit";
import FilterListRoundedIcon from "@mui/icons-material/FilterListRounded";
import ModalWarehouse from "../components/ModalWarehouse";
import LibraryAddRoundedIcon from "@mui/icons-material/LibraryAddRounded";

/**
 *  @autor [Mateus Spengler]
 * - *English* Variables for component styling
 * - *Português* Variaveis para estilização de componentes
 */
const StyledTableCell = styled(TableCell)(({ theme }) => ({
  [`&.${tableCellClasses.head}`]: {
    backgroundColor: "#15191C",
    color: theme.palette.common.white,
  },
  [`&.${tableCellClasses.body}`]: {
    fontSize: 14,
  },
}));

const StyledTableRow = styled(TableRow)(({ theme }) => ({
  "&:nth-of-type(odd)": {
    backgroundColor: theme.palette.action.hover,
  },
  "&:last-child td, &:last-child th": {
    border: 0,
  },
}));

const ListItem = styled("li")(({ theme }) => ({
  margin: theme.spacing(0.5),
}));

/**
 * - *English* Object for header definition
 * - *Português* Objeto para definição do cabeçalho
 */
const columns = [
  {
    label: "Code",
    type: "text",
    value: "code",
    width: "8%",
    align: "left",
    isOrder: "true",
    isFilter: "true",
    isNumber: true,
    maxLength: "9",
  },
  {
    label: "Description",
    type: "text",
    value: "description",
    width: "22%",
    align: "left",
    isOrder: "true",
    isFilter: "true",
    isNumber: false,
    maxLength: "60",
  },
  {
    label: "Address",
    type: "text",
    value: "address",
    width: "22%",
    align: "left",
    isOrder: "true",
    isFilter: "true",
    isNumber: false,
    maxLength: "60",
  },
  {
    label: "E-mail",
    type: "text",
    value: "email",
    width: "22%",
    align: "left",
    isOrder: "true",
    isFilter: "true",
    isNumber: false,
    maxLength: "60",
  },
  {
    label: "Phone",
    type: "text",
    value: "phone",
    width: "8%",
    align: "left",
    isOrder: "true",
    isFilter: "true",
    isNumber: true,
    maxLength: "14",
  },
  {
    label: "Capacity",
    type: "text",
    value: "maxCapacity",
    width: "9%",
    align: "left",
    isOrder: "true",
    isFilter: "true",
    isNumber: true,
    maxLength: "10",
  },
  {
    label: "Situation",
    type: "text",
    value: "statusCode",
    width: "9%",
    align: "left",
    isOrder: "false",
    isFilter: "false",
    isNumber: false,
    maxLength: "",
  },
  {
    label: "Separation",
    type: "text",
    value: "separationIndicator",
    width: "9%",
    align: "left",
    isOrder: "false",
    isFilter: "false",
    isNumber: false,
    maxLength: "",
  },
  {
    label: "Action",
    type: "",
    value: "Action",
    width: "1%",
    align: "center",
    isOrder: "false",
    isFilter: "false",
    isNumber: false,
    maxLength: "",
  },
];

/**
 * - *English* General component for creating the warehouse list
 * - *Português* Componente geral para a criação da lista de armazém
 * - @return Warehouses list
 */
export default function Warehouse() {
  /**
   * - *English* Variable state control functions
   * - *Português* Funções de controle de estado das variaveis
   */
  // const [open, setOpen] = useState(false);
  const [warehouses, setwarehouses] = useState([]);
  const [labelPopover, setLabelPopover] = useState("");
  const [columnPopover, setColumnPopover] = useState("");
  const [valuePopover, setValuePopover] = useState("");
  const [labelFilter, setLabelFilter] = useState("");
  const [typePopover, setTypePopover] = useState("");
  const [orderBy, setOrderBy] = useState("");
  const [sort, setSort] = useState("asc");
  const [pageList, setPageList] = useState(1);
  const [page, setPage] = useState(1);
  const [changed, setChanged] = useState("");
  const [rowsPerPage, setRowsPerPage] = useState(10);
  const [situation, setSituation] = useState(0);
  const [anchorEl, setAnchorEl] = useState(null);
  const [maxLegthPopover, setMaxLegthPopover] = useState(60);
  const [isNumber, setIsNumber] = useState();
  // const [loading, setLoading] = useState();
  const [chipData, setChipData] = useState([]);



  /**
   * - *English* Variable to reset the filters
   * - *Português* Variável para resetar os filtros
   */

  const handClickResetList = () => {
    setChipData([]);
    setLabelFilter("");
    setValuePopover("");
    setPage(1);
    setSituation(0);
    setRowsPerPage(10);
    setOrderBy("");
  };

  /**
   * - *English* Variable to assign the Popover position
   * - *Português* Variável para atribuir a posição do Popover
   */
  const openPopover = Boolean(anchorEl);

  /**
   * - *English* Variable to assign to Popover style
   * - *Português* Variável para atribuir a estilo do Popover
   */
  const id = openPopover ? "simple-popover" : undefined;

  /**
   * - *English* Function to open and assign variables in Popover
   * - *Português* Função para abrir e atribuir variaveis no Popover
   * - @param event @param label @param column @param type
   */
  const handleClickPopover = (
    event,
    label,
    column,
    type,
    maxLength,
    number
  ) => {
    setAnchorEl(event);
    setLabelPopover(label);
    setColumnPopover(column);
    setTypePopover(type);
    setMaxLegthPopover(maxLength);
    setIsNumber(number);
  };

  /**
   * - *English* Function to assign the filter field to a state variable
   * - *Português* Função para atribuir o campo do filtro a uma variavel de estado
   * - @param event
   */
  const handleChangePopover = (event) => {
    setValuePopover(event.target.value);
  };

  const handleChangeNumberPopover = (event) => {
    event.target.value = event.target.value.replace(/[^0-9,]/g, "");
    setValuePopover(event.target.value);
  };
  /**
   * - *English* Function to assign the table column field to a state variable and close the Popover
   * - *Português* Função para atribuir o campo da columa da tabela a uma variavel de estado e fechar o Popover
   */
  const handleConfirmPopover = () => {
    setAnchorEl(null);
    setChipData((chips) =>
      chips.filter((chip) => chip.labelFilter !== labelPopover)
    );
    setChipData((prevState) => [
      ...prevState,
      {
        labelFilter: labelPopover,
        columnPopover: columnPopover,
        valueFilter: valuePopover,
      },
    ]);
    setPage(1);
    setChanged(!changed);
  };

  const keyPress = (e) => {
    if (e.keyCode === 13) {
      handleConfirmPopover();
    }
  };

  /**
   * - *English* Function to close the Popover
   * - *Português* Função para fechar o Popover
   */
  const handleClosePopover = () => {
    setAnchorEl(null);
  };

  /**
   * - *English* Function to delete chip itens
   * - *Português* Função para deletar itens no chip
   */
  const handleDelete = (chipToDelete) => () => {
    setChipData((chips) =>
      chips.filter((chip) => chip.labelFilter !== chipToDelete.labelFilter)
    );
  };

  /**
   * - *English* Function to list inactive/active
   * - *Português* Função para listar inativados/ativados
   * - @param event
   */
  const handleListInactive = (event) => {
    setSituation(event.target.checked ? 1 : 0);
    setPage(1);
    setOrderBy("");
    setSort("asc");
  };

  /**
   * - *English* Function to pagination
   * - *Português* Função para paginação
   * - @param event
   */
  const handleChangeRowsPerPage = (event) => {
    setRowsPerPage(+event.target.value);
    setPage(1);
    setOrderBy("");
    setSort("asc");
  };

  /**
   * - *English* Function to pagination
   * - *Português* Função para paginação
   * - @param event @param value
   */
  const handleChangePage = (event, value) => {
    setPage(value);
    setOrderBy("");
    setSort("asc");
  };

  /**
   * - *English* Function to sort in ascending/descending order
   * - *Português* Função para ordenar de forma crescente/decrecente
   * - @param event @param isOrder
   */
  const handleOrderBy = (value, isOrder) => {
    if (isOrder === "true") {
      if (orderBy === value) {
        setOrderBy(value);
        setSort(sort === "asc" ? "desc" : "asc");
      } else {
        setOrderBy(value);
        setSort("asc");
      }
    }
    setPage(1);
  };

  /**
   * - *English* Function to change the table
   * - *Português* Função para atualizar a tabela
   */
  const handleChangeEdit = () => {
    setChanged(!changed);
  };

  /**
   * - *English* This function is responsible for sending a JSON to the backend and will handle the response sent by it, through an asynchronous function.
   *    If this return is successful will return the bank information if not it will be empty.
   * - *Português* Esta função  tem a responsabilidade de enviar um JSON para o backend e tratará da resposta enviada por ele, por meio de uma função assíncrona. Se esse retorno for bem sucedido
   *    retornara as informação do banco se não ficará vazio
   */
  /**
   * - *English* This function is responsible for sending a JSON to the backend and will handle the response sent by it, through an asynchronous function.
   *    If this return is successful will return the bank information if not it will be empty.
   * - *Português* Esta função  tem a responsabilidade de enviar um JSON para o backend e tratará da resposta enviada por ele, por meio de uma função assíncrona. Se esse retorno for bem sucedido
   *    retornara as informação do banco se não ficará vazio
   */
  useEffect(() => {
    // setLoading(true);
    document.title = "Lince Tech Micro ERP | Warehouse management";
    const getWarehouses = async () => {
      const pagedWarehouse = await warehouseUseCase.listWarehouses(
        page,
        rowsPerPage,
        situation,
        orderBy,
        sort,
        chipData
      );
      return pagedWarehouse;
    };
    getWarehouses().then((response) => {
      setwarehouses(response.warehouses);
      setPageList(response.numberOfPages);
      // timeOutSpinner();
      // setLoading(false);
    });
  }, [
    page,
    rowsPerPage,
    changed,
    situation,
    orderBy,
    sort,
    labelFilter,
    chipData,
  ]);

  // function timeOutSpinner() {
  //   setLoading(true);
  //   setTimeout(() => {
  //     setLoading(false);
  //   }, 8000);
  // }

  const handleOpenModalWarehouse = (evt, warehouseCode) => {
    evt.preventDefault();
    const container = document.getElementById("modal-warehouse");
    const root = createRoot(container);
    return root.render(
      <ModalWarehouse
        warehouseCode={warehouseCode}
        isOpen={true}
        parentCallback={handleChangeEdit}
      />
    );
  };

  return (
    <Box sx={{ display: "flex" }}>
      <input type="hidden" id="modal-warehouse" />
      <Box sx={{ width: "100%", marginRight: "2rem" }}>
        <Typography
          sx={{
            fontSize: "26pt",
            fontWeight: "800",
            marginLeft: "3rem",
            marginTop: "3rem",
          }}
        >
          Warehouse
        </Typography>
        <Box
          display={"flex"}
          justifyContent={"space-between"}
          justifyItems={"center"}
          sx={{ marginLeft: "3rem", marginTop: "0.5rem" }}
        >
          <Box sx={{ display: "flex" }}>
            <Box
              sx={{
                display: "flex",
                justifyContent: "center",
                flexWrap: "wrap",
                listStyle: "none",
                p: 0,
                m: 0,
                border: "none",
              }}
              component="ul"
            >
              {chipData.map((data) => {
                return (
                  <ListItem key={data.valueFilter}>
                    <Tooltip title={data.labelFilter} placement="bottom" arrow>
                      <Chip
                        sx={{
                          textOverFlow: "ellipsis",
                          overFlow: "hidden",
                          whiteSpace: "nowrap",
                          maxWidth: "145px",
                        }}
                        color="primary"
                        variant="outlined"
                        label={data.valueFilter}
                        onDelete={handleDelete(data)}
                      />
                    </Tooltip>
                  </ListItem>
                );
              })}
            </Box>
            {chipData.length === 0 ? (
              <></>
            ) : (
              <Button onClick={handClickResetList}>Clear All</Button>
            )}
          </Box>

          <Box
            display={"flex"}
            justifyContent={"space-between"}
            justifyItems={"center"}
            sx={{ justifyContent: "end" }}
          >
            <FormControlLabel
              sx={{ align: "left", fontSize: "11pt" }}
              control={<Switch onChange={handleListInactive} />}
              label="List only inactivated warehouse"
            />

            <FormControlLabel
              sx={{ align: "left", fontSize: "11pt" }}
              control={
                <Button onClick={(evt) => handleOpenModalWarehouse(evt)}>
                  <LibraryAddRoundedIcon color="action" />
                </Button>
              }
            />
          </Box>
        </Box>
        <Paper
          sx={{
            justifyContent: "center",
            marginLeft: "3rem",
            marginTop: "0.5rem",
          }}
        >
          <TableContainer component={Paper}>
            <Table
              stickyHeader
              aria-label="Warehouse Table"
              sx={{ minWidth: 1500 }}
            >
              <TableHead>
                <StyledTableRow>
                  {columns.map((key) => (
                    <StyledTableCell key={key.value}>
                      <Grid
                        container
                        justifyContent={"space-between"}
                        flexWrap={"nowrap"}
                      >
                        {key.isOrder === "true" ? (
                          <TableSortLabel
                            sx={{
                              "&.MuiTableSortLabel-root": {
                                color: "white",
                              },
                              "&.MuiTableSortLabel-root:hover": {
                                color: "white",
                              },
                              "&.Mui-active": {
                                color: "white",
                              },
                              "& .MuiTableSortLabel-icon": {
                                color: "white !important",
                              },
                            }}
                            active={orderBy === key.value}
                            direction={sort}
                            onClick={() =>
                              handleOrderBy(key.value, key.isOrder)
                            }
                          >
                            {key.label}
                          </TableSortLabel>
                        ) : (
                          <>{key.label}</>
                        )}
                        {key.isFilter === "true" && (
                          <FilterListRoundedIcon
                            aria-describedby={id}
                            variant="contained"
                            onClick={(e) =>
                              handleClickPopover(
                                e.currentTarget,
                                key.label,
                                key.value,
                                key.type,
                                key.maxLength,
                                key.isNumber
                              )
                            }
                            sx={{
                              width: "18px",
                              justifySelf: "end",
                              cursor: "pointer",
                            }}
                          />
                        )}
                      </Grid>
                    </StyledTableCell>
                  ))}
                </StyledTableRow>
              </TableHead>
              <TableBody>
                {warehouses.map((key, index) => (
                  <StyledTableRow key={index}>
                    <StyledTableCell
                      sx={{
                        width: "8%",
                        overflow: "hidden",
                        flexWrap: "nowrap",
                      }}
                      align={"left"}
                    >
                      {key.code}
                    </StyledTableCell>
                    <StyledTableCell
                      sx={{
                        width: "22%",
                        overflow: "hidden",
                        flexWrap: "nowrap",
                      }}
                      align={"left"}
                    >
                      {key.description}
                    </StyledTableCell>
                    <StyledTableCell
                      sx={{
                        width: "22%",
                        overflow: "hidden",
                        flexWrap: "nowrap",
                      }}
                      align={"left"}
                    >
                      {key.address}
                    </StyledTableCell>
                    <StyledTableCell
                      sx={{
                        width: "22%",
                        overflow: "hidden",
                        flexWrap: "nowrap",
                      }}
                      align={"left"}
                    >
                      {key.email}
                    </StyledTableCell>
                    <StyledTableCell
                      sx={{
                        width: "13%",
                        overflow: "hidden",
                        flexWrap: "nowrap",
                      }}
                      align={"left"}
                    >
                      {key.phone === ""
                        ? ""
                        : "+ (" +
                        key.phone.substring(0, 3) +
                        ") " +
                        key.phone.substring(3, 4) +
                        " " +
                        key.phone.substring(4, 9) +
                        "-" +
                        key.phone.substring(9, 13)}
                    </StyledTableCell>
                    <StyledTableCell
                      sx={{
                        width: "9%",
                        overflow: "hidden",
                        flexWrap: "nowrap",
                      }}
                      align={"left"}
                    >
                      {new Intl.NumberFormat("en-US", {
                        minimumFractionDigits: 2,
                        maximumFractionDigits: 2,
                      }).format(key.maxCapacity)}
                    </StyledTableCell>
                    <StyledTableCell
                      sx={{
                        width: "9%",
                        overflow: "hidden",
                        flexWrap: "nowrap",
                      }}
                      align={"left"}
                    >
                      {key.statusCode === 0 ? "Active" : "Inative"}
                    </StyledTableCell>
                    <StyledTableCell
                      sx={{
                        width: "9%",
                        overflow: "hidden",
                        flexWrap: "nowrap",
                      }}
                      align={"left"}
                    >
                      {key.separationIndicator === false ? "No" : "Yes"}
                    </StyledTableCell>
                    <StyledTableCell sx={{ width: "1%" }} align={"center"}>
                      <Button
                        onClick={(evt) =>
                          handleOpenModalWarehouse(evt, key.code)
                        }
                      >
                        <EditIcon color="action" />
                      </Button>
                    </StyledTableCell>
                  </StyledTableRow>
                ))}
              </TableBody>
            </Table>
          </TableContainer>
          {/* {loading ? (
            <Box
              sx={{
                width: "100%",
                height: "30rem",
                display: "flex",
                justifyContent: "center",
                padding: "10%",
              }}
            >
              <div className="loading-packing"></div>
            </Box>
          ) : (
            <></>
          )} */}
        </Paper>
        <Box
          display={"flex"}
          justifyContent={"flex-end"}
          sx={{ marginTop: "2vh", alignItems: "center", gap: "1vw" }}
        >
          <Typography sx={{ align: "center", fontSize: "11pt" }}>
            Rows Per Page
          </Typography>

          <Select
            sx={{ height: "4vh", align: "center" }}
            autoWidth
            value={rowsPerPage}
            onChange={handleChangeRowsPerPage}
          >
            <MenuItem value={5}>5</MenuItem>
            <MenuItem value={10}>10</MenuItem>
            <MenuItem value={15}>15</MenuItem>
          </Select>

          <Stack spacing={2}>
            <Pagination
              count={pageList}
              page={page}
              onChange={handleChangePage}
            />
          </Stack>
        </Box>
      </Box>

      <Popover
        id={id}
        open={openPopover}
        anchorEl={anchorEl}
        onClose={handleClosePopover}
        anchorOrigin={{
          vertical: "bottom",
          horizontal: "left",
        }}
      >
        <Box
          sx={{
            display: "flex",
            alignContent: "center",
            alignItems: "center",
            p: 2,
            gap: 2,
          }}
        >
          <Typography>Filter</Typography>
          <TextField
            type={typePopover}
            inputProps={{ maxLength: maxLegthPopover }}
            variant="outlined"
            placeholder={labelPopover}
            onChange={
              isNumber
                ? handleChangeNumberPopover
                : isNumber
                  ? handleChangeNumberPopover
                  : handleChangePopover
            }
            size="small"
            onKeyDown={keyPress}
          ></TextField>
          <Button variant="outlined" onClick={handleConfirmPopover}>
            Confirm
          </Button>
        </Box>
      </Popover>
    </Box>
  );
}
