import { PagedRequestHistory } from "../entities/Entities";
import http from "../../../HttpHelper";

class RequestHistoryRepository {
  /**
   * @param page {int}
   * @param rowsPerPage {int}
   * @param orderBy {string}
   * @param situation {string}
   * @param sort {string}
   * @param chipData {string}
   * @returns {Promise<PagedRequestHistory>}
   */

  async listRequestHistory(filterList) {
    const parameters = `page=${filterList.page}&size=${
      filterList.rowsPerPage
    }&orderBy=${
      filterList.orderBy === "" ? "receivedAt" : filterList.orderBy
    }&sortBy=${filterList.sort}`;
    const filters = `${
      filterList.filters.length > 0
        ? filterList.filters.map(
            (filter) =>
              "&filter=(" +
              filter.columnPopover +
              ":" +
              filter.valueFilter +
              ")"
          )
        : ""
    }`;
    try {
      const response = await http.get(
        `/stock/transfer?${parameters}${filters !== "" ? filters : ""}`
      );
      return response;
    } catch (error) {
      return error;
    }
  }

  async getDetailingStock(requestUUID) {
    try {
      const response = await http.get(`/stock/${requestUUID}/detailed`);
      return response;
    } catch (error) {
      return error.response;
    }
  }

  async getStockHistoric(requestUUID) {
    try {
      const response = await http.get(`/stock/transfer/history/${requestUUID}`);
      return response;
      // return new PagedRequestHistory(response.data.stockTransferHistory);
    } catch (error) {
      return error.response;
    }
  }

  async confirmRequest(uuid) {
    const response = await http.post(`/stock/${uuid}`);
    return response.data;
  }

  async deleteRequest(uuid) {
    const response = await http.post(`/stock/cancel/${uuid}`);
    return response.data;
  }

  async cancelRequest(uuid) {
    const response = await http.post(`/stock/cancel/${uuid}`);
    return response.data;
  }

  async deleteBoxRequest(stockTransfer, boxlistUUID) {
    try {
      const response = await http.post(
        `/stock/transfer/delete/box/${stockTransfer}`,
        JSON.stringify(boxlistUUID)
      );      
      return response;
    } catch (error) {
      return error;
    }
  }
}

export const requestHistoryRepository = new RequestHistoryRepository();
