import { TextField } from "@mui/material";
import { useState } from "react";
import ReactInputMask from "react-input-mask";

const ContactTypesOptions = ({
    key,
    index,
    initialLabel,
    initialType,
    setVendorContact,
    error
  }) => {
    const [contactValue, setContactValue] = useState(initialLabel);
    const [change, setChange] = useState(0);
  
    const handleOnChangeContactValue = (evt) => {
      evt.preventDefault();      
      const { name, value } = evt.target;
      setChange(1);
      setContactValue(value);      
      setVendorContact({ index: index, contactType: name, label: value });      
    };
  
    if (initialType === "telephone") {
      return (
        <ReactInputMask
          mask="+ (999) 9 99999-9999"
          maskChar=""
          value={contactValue === "" && change === 0 ? initialLabel : contactValue}
          key={index}
          onChange={(evt) => {
            handleOnChangeContactValue(evt);
          }}
        >
          {() => (
            <TextField
              label="Phone"
              variant="standard"
              name={initialType}
              required={index === 0 ? true : false}
            />
          )}
        </ReactInputMask>
      );
    } else {
      return (
        <TextField
          key={index}
          label={
            initialType === "email"
              ? "E-mail"
              : initialType === "website" ? "Website" : "Select the type of contact"
          }
          variant="standard"
          name={initialType}
          inputProps={initialType === "" ? { maxLength: 60, readOnly: true } : { maxLength: 60, readOnly: false }}
          value={contactValue === "" && change === 0 ? initialLabel : contactValue}
          fullWidth
          required={index === 0 ? true : false}
          onChange={(evt) => {
            handleOnChangeContactValue(evt);
          }}
          {...(error === "contact" && index === 0 && {error})}
        />
      );
    }
  };

  export default ContactTypesOptions