import http from "../../../HttpHelper";

class BoxRepository {
  async getBoxes(filterList) {
    const parameters = `page=${filterList.page}&size=${filterList.rowsPerPage}&orderBy=${filterList.orderBy === "" ? "vendorIdentifier" : filterList.orderBy}&sortBy=${filterList.sort}`;
    const filters = `${filterList.filters.length > 0 ? filterList.filters.map((filter) =>"&filter=(" + filter.columnPopover + ":" + filter.valueFilter + ")"): ""}`;    
    try {
      const response = http.get(`/boxType?${parameters}${filters !== "" ? filters : ""}`);      
      return response;
    } catch (error) {
      return error;
    }
  }
}

export const boxRepository = new BoxRepository();
