export class Filter {
  /**
   *
   * @param column {string}
   * @param value {string}
   */
  constructor(column, value) {
    this.column = column
    this.value = value
  }
}

export class Warehouse {
  /**
  * @param uuid {Number}
  * @param code {Number}
  * @param description {string}
  * @param address  {string}
  * @param email {string}
  * @param phone {String}
  * @param statusCode {Number}
  * @param maxCapacity {Number}
  * @param separationIndicator {Number}
  */
  constructor(uuid, code, description, address, email, phone, situation, capacity, separation) {
    this.uuid = uuid;
    this.code = code;
    this.description = description;
    this.address = address;
    this.email = email;
    this.phone = phone;
    this.situation = situation;
    this.capacity = capacity;
    this.separation = separation;
  }
}

export class PagedWarehouses {
  /**
   *
   * @param warehouses {Warehouse[]}
   * @param numberOfPages {number}
   */
  constructor(warehouses, numberOfPages) {
    this.warehouses = warehouses
    this.numberOfPages = numberOfPages
  }
}