export default class AuthenticationRules {
  static loginIsInvalid(login) {
    if (!login || !login.trim()) {
      return {
        message: "Login cannot be empty.",
        code: "INVALID_LOGIN",
      };
    }
  }

  static emailIsInvalid(email) {
    if (!email || !email.trim()) {
      return {
        message: "Please enter an email.",
        code: "INVALID_EMAIL",
      };
    }

    if (
      !String(email)
        .toLowerCase()
        .match(/^\S+@\S+\S+\.\S+$/)
    ) {
      return {
        message: "Please enter a valid email address.",
        code: "INVALID_EMAIL",
      };
    }
  }

  static passwordIsInvalid(password) {
    if (!password || !password.trim()) {
      return {
        message: "Password cannot be empty.",
        code: "INVALID_PASSWORD",
      };
    }
  }

}
