import { Vendor } from "../entities/Vendor";
import { vendorRepository } from "../repositories/vendorRepository";

class VendorUseCases {
  /**
   * Register vendor
   * @param {Vendor} vendor
   * @returns
   */
  async postVendor(vendor) {
    const errors = new Map();
    console.log(vendor);

    const isValidEmail = (email) => {
      return /\S+@\S+\.\S+/.test(email);
    };

    if (vendor.identificator !== null) {
      if (vendor.identificator === "") {
        const errorCode = { key: "identificator" };
        errors.set(errorCode, "Identificator is invalid");
      }
    }

    if (vendor.name === "") {
      const errorCode = { key: "name" };
      errors.set(errorCode, "Name must not be empty");
    }

    if (vendor.address === "") {
      const errorCode = { key: "address" };
      errors.set(errorCode, "Address must not be empty");
    }

    if (vendor.contact.length === 0) {
      const errorCode = { key: "contact" };
      errors.set(errorCode, "You must provide one contact");
    }

    if (vendor.contact.length > 0) {
      vendor.contact.map((contact) => {
        if (contact.contactType === "51541554-b9de-11ed-afa1-0242ac120002") {          
          if (contact.label.replace("+", "").replace("-", " ").replace("(", "").replace(")", "").replace(" ", "").replace(/\s/g, "").length < 13) {
            const errorCode = { key: "phone" };
            errors.set(errorCode, "Phone is Invalid");
          }
        }
        if (contact.contactType === "23214896-b9de-11ed-afa1-0242ac120002") {
          if (!isValidEmail(contact.label)) {
            const errorCode = { key: "email" };
            errors.set(errorCode, "Email is invalid");
          }
        }
      });
    }

    if (errors.size > 0) {
      return errors;
    }
    try {
      return await vendorRepository.vendorPost(vendor);
    } catch (error) {
      return error;
    }
  }

  async getVendorContactType() {
    const response = await vendorRepository.getVendorContactType();
    if (typeof response === Error) {
      console.log('ERRO')
    } else {
      return response;
    }
  }

  async getVendorByIdentifier(vendorIdentifier) {
    const response = await vendorRepository.getVendorByIdentifier(
      vendorIdentifier
    );
    return response;
  }

  /**
   * @param {String} uuid
   * @param {String} identificator
   * @param {boolean} situation
   * @param {String} name
   * @param {String} email
   * @param {String} phone
   * @param {String} address
   */
  async vendorGet(page, rowsPerPage, orderBy, sort, chipData) {
    const response = await vendorRepository.vendorGet(
      page,
      rowsPerPage,
      orderBy,
      sort,
      chipData
    );

    return response;
  }
}

export const vendorUseCases = new VendorUseCases();
