import http from "../../../HttpHelper";

class BoxRequestRepository {
  async getBoxRequest(filterList, code) {
    const parameters = `page=${filterList.page}&size=${
      filterList.rowsPerPage
    }&orderBy=${
      filterList.orderBy === "" ? "description" : filterList.orderBy
    }&sortBy=${filterList.sort}`;
    const filters = `${
      filterList.filters.length > 0
        ? filterList.filters.map(
            (filter) =>
              "&filter=(" +
              (filter.columnPopover === "colorDescription" &&
              !isNaN(filter.valueFilter.replace(/[^\w\s]|_/g, "").trim())
                ? "colorCode"
                : filter.columnPopover) +
              ":" +
              filter.valueFilter.replace(/[^\w\s]|_/g, "").trim() +
              ")"
          )
        : ""
    }`;
    try {
      const response = await http.get(
        `/stock/list/${code}/detailed?${parameters}${
          filters !== "" ? filters : ""
        }`
      );
      return response;
    } catch (error) {
      return error;
    }
  }

  async getBoxes(packingUUID, boxNumber) {
    const response = await http.get(
      `/packing/${packingUUID}/boxes?filter=(number:${boxNumber})&filter=(packingUUID:${packingUUID})`
    );
    return response.data;
  }
}

export const boxRequestRepository = new BoxRequestRepository();
