import { boxRequestRepository } from "../repositories/BoxRequestRepository";

class BoxRequestUseCase {
  async getBoxRequest(filterList, code) {
    const response = await boxRequestRepository.getBoxRequest(filterList, code);
    return response;
  }

  async getBoxes(packingUUID, boxNumber) {
    return boxRequestRepository.getBoxes(packingUUID, boxNumber);
  }
}

export const boxRequestUseCase = new BoxRequestUseCase();
