import * as React from "react";
import { useEffect, useState } from "react";
import { priceUseCase } from "../usecases/PriceUseCases";
import { styled } from "@mui/material/styles";
import {
  Box,
  TextField,
  Paper,
  Chip,
  Tooltip,
  Button,
  Typography,
  Table,
  TableBody,
  TableCell,
  tableCellClasses,
  TableContainer,
  TableHead,
  FormControlLabel,
  Switch,
  TableRow,
  Select,
  MenuItem,
  Pagination,
  Stack,
  TableSortLabel,
  Grid,
  Popover,
} from "@mui/material";
import { createRoot } from "react-dom/client";
import IconButton from "@mui/material/IconButton";
import EditRoundedIcon from "@mui/icons-material/EditRounded";
import DeleteRoundedIcon from "@mui/icons-material/DeleteRounded";
import AddCircleRoundedIcon from "@mui/icons-material/AddCircleRounded";
import FilterListRoundedIcon from "@mui/icons-material/FilterListRounded";
import LibraryAddRoundedIcon from "@mui/icons-material/LibraryAddRounded";
import PriceRegisterModal from "../components/ModalPrice";
import ModalPriceDetail from "../components/ModalPriceDetail";
import CheckRoundedIcon from "@mui/icons-material/CheckRounded";
import Moment from "dayjs";
import Swal from "sweetalert2";

/**
 *  @autor [Mateus Spengler]
 * - *English* Variables for component styling
 * - *Português* Variaveis para estilização de componentes
 */
const StyledTableCell = styled(TableCell)(({ theme }) => ({
  [`&.${tableCellClasses.head}`]: {
    backgroundColor: "#15191C",
    color: theme.palette.common.white,
  },
  [`&.${tableCellClasses.body}`]: {
    fontSize: 14,
  },
}));

const StyledTableRow = styled(TableRow)(({ theme }) => ({
  "&:nth-of-type(odd)": {
    backgroundColor: theme.palette.action.hover,
  },
  "&:last-child td, &:last-child th": {
    border: 0,
  },
}));

const ListItem = styled("li")(({ theme }) => ({
  margin: theme.spacing(0.5),
}));

/**
 * - *English* Object for header definition
 * - *Português* Objeto para definição do cabeçalho
 */
const columns = [
  {
    label: "Code",
    type: "text",
    value: "code",
    width: "8%",
    align: "left",
    isOrder: "true",
    isFilter: "true",
    isNumber: true,
    maxLength: "10",
  },
  {
    label: "Name",
    type: "text",
    value: "name",
    width: "20%",
    align: "left",
    isOrder: "true",
    isFilter: "true",
    isNumber: false,
    maxLength: "200",
  },
  {
    label: "Initial",
    type: "text",
    value: "initial",
    width: "8%",
    align: "left",
    isOrder: "false",
    isFilter: "false",
    isNumber: false,
    maxLength: "10",
  },
  {
    label: "Final",
    type: "text",
    value: "final",
    width: "8%",
    align: "left",
    isOrder: "false",
    isFilter: "false",
    isNumber: false,
    maxLength: "10",
  },
  {
    label: "Active",
    type: "text",
    value: "active",
    width: "5%",
    align: "left",
    isOrder: "false",
    isFilter: "false",
    isNumber: false,
    maxLength: "10",
  },
  {
    label: "Action",
    type: "text",
    value: "action",
    width: "5%",
    align: "center",
    isOrder: "false",
    isFilter: "false",
    isNumber: false,
    maxLength: "10",
  },
];

const rows = [
  {
    number: "1",
    indentifier: "2021/2022",
    name: "Tabela internacional",
    initial: "12/01/2022",
    final: "12/01/2023",
    create: "11/28/2022",
    statusCode: 0,
  },
  {
    number: "2",
    indentifier: "2021/2022",
    name: "Tabela sem descontos",
    initial: "12/05/2021",
    final: "12/01/2022",
    create: "11/15/2021",
    statusCode: 1,
  },
];

/**
 * - *English* General component for creating the warehouse list
 * - *Português* Componente geral para a criação da lista de armazém
 * - @return Warehouses list
 */
export default function PriceTable() {
  /**
   * - *English* Variable state control functions
   * - *Português* Funções de controle de estado das variaveis
   */
  // const [open, setOpen] = useState(false);
  const [priceTables, setPriceTables] = useState([]);
  const [labelPopover, setLabelPopover] = useState("");
  const [columnPopover, setColumnPopover] = useState("");
  const [valuePopover, setValuePopover] = useState("");
  const [labelFilter, setLabelFilter] = useState("");
  const [typePopover, setTypePopover] = useState("");
  const [orderBy, setOrderBy] = useState("");
  const [sort, setSort] = useState("asc");
  const [pageList, setPageList] = useState(1);
  const [page, setPage] = useState(1);
  const [changed, setChanged] = useState("");
  const [rowsPerPage, setRowsPerPage] = useState(10);
  const [situation, setSituation] = useState(true);
  const [anchorEl, setAnchorEl] = useState(null);
  const [maxLegthPopover, setMaxLegthPopover] = useState(60);
  const [isNumber, setIsNumber] = useState();
  // const [loading, setLoading] = useState();
  const [chipData, setChipData] = useState([]);

  /**
   * - *English* Function to list inactive/active
   * - *Português* Função para listar inativados/ativados
   * - @param event
   */
  const handleListInactive = (event) => {
    setSituation(event.target.checked ? false : true);
    setPage(1);
    setOrderBy("");
    setSort("asc");
    setChanged(!changed);
  };

  /**
   * - *English* Variable to assign the Popover position
   * - *Português* Variável para atribuir a posição do Popover
   */
  const openPopover = Boolean(anchorEl);

  /**
   * - *English* Variable to assign to Popover style
   * - *Português* Variável para atribuir a estilo do Popover
   */
  const id = openPopover ? "simple-popover" : undefined;

  /**
   * - *English* Function to open and assign variables in Popover
   * - *Português* Função para abrir e atribuir variaveis no Popover
   * - @param event @param label @param column @param type
   */
  const handleClickPopover = (
    event,
    label,
    column,
    type,
    maxLength,
    number
  ) => {
    setAnchorEl(event);
    setLabelPopover(label);
    setColumnPopover(column);
    setTypePopover(type);
    setMaxLegthPopover(maxLength);
    setIsNumber(number);
  };

  /**
   * - *English* Function to assign the filter field to a state variable
   * - *Português* Função para atribuir o campo do filtro a uma variavel de estado
   * - @param event
   */
  const handleChangePopover = (event) => {
    setValuePopover(event.target.value);
  };

  const handleChangeNumberPopover = (event) => {
    event.target.value = event.target.value.replace(/[^0-9,]/g, "");
    setValuePopover(event.target.value);
  };
  /**
   * - *English* Function to assign the table column field to a state variable and close the Popover
   * - *Português* Função para atribuir o campo da columa da tabela a uma variavel de estado e fechar o Popover
   */
  const handleConfirmPopover = () => {
    setAnchorEl(null);
    setChipData((chips) =>
      chips.filter((chip) => chip.labelFilter !== labelPopover)
    );
    setChipData((prevState) => [
      ...prevState,
      {
        labelFilter: labelPopover,
        columnPopover: columnPopover,
        valueFilter: valuePopover,
      },
    ]);
    setPage(1);
    setChanged(!changed);
  };

  const keyPress = (e) => {
    if (e.keyCode === 13) {
      handleConfirmPopover();
    }
  };

  /**
   * - *English* Function to close the Popover
   * - *Português* Função para fechar o Popover
   */
  const handleClosePopover = () => {
    setAnchorEl(null);
  };

  /**
   * - *English* Function to delete chip itens
   * - *Português* Função para deletar itens no chip
   */
  const handleDelete = (chipToDelete) => () => {
    setChipData((chips) =>
      chips.filter((chip) => chip.labelFilter !== chipToDelete.labelFilter)
    );
  };

  /**
   * - *English* Function to pagination
   * - *Português* Função para paginação
   * - @param event
   */
  const handleChangeRowsPerPage = (event) => {
    setRowsPerPage(+event.target.value);
    setPage(1);
    setOrderBy("");
    setSort("asc");
  };

  /**
   * - *English* Variable to reset the filters
   * - *Português* Variável para resetar os filtros
   */

  const handClickResetList = () => {
    setChipData([]);
    setLabelFilter("");
    setValuePopover("");
    setPage(1);
    setSituation(true);
    setRowsPerPage(10);
    setOrderBy("");
  };

  /**
   * - *English* Function to pagination
   * - *Português* Função para paginação
   * - @param event @param value
   */
  const handleChangePage = (event, value) => {
    setPage(value);
    setOrderBy("");
    setSort("asc");
  };

  /**
   * - *English* Function to sort in ascending/descending order
   * - *Português* Função para ordenar de forma crescente/decrecente
   * - @param event @param isOrder
   */
  const handleOrderBy = (value, isOrder) => {
    if (isOrder === "true") {
      if (orderBy === value) {
        setOrderBy(value);
        setSort(sort === "asc" ? "desc" : "asc");
      } else {
        setOrderBy(value);
        setSort("asc");
      }
    }
    setPage(1);
  };

  /**
   * - *English* Function to change the table
   * - *Português* Função para atualizar a tabela
   */
  const handleChangeEdit = () => {
    setChanged(!changed);
  };

  const handleOpenModalPrice = (evt, priceCode) => {
    evt.preventDefault();
    const container = document.getElementById("modal-price");
    const root = createRoot(container);
    return root.render(
      <PriceRegisterModal
        priceCode={priceCode}
        isOpen={true}
        parentCallback={handleChangeEdit}
      />
    );
  };

  const handleOpenModalPriceDetail = (evt, priceCode, priceUuid) => {
    evt.preventDefault();
    const container = document.getElementById("modal-detail-price");
    const root = createRoot(container);
    return root.render(
      <ModalPriceDetail
        priceCode={priceCode}
        priceUuid={priceUuid}
        isOpen={true}
        parentCallback={handleChangeEdit}
      />
    );
  };

  const convertDate = (originalDate) => {
    if (originalDate != null) {
      return <> {Moment(originalDate).format("MM/DD/YYYY")} </>;
    }
  };

  const handleChangeStatusPriceTable = (priceTableUUID, situation) => {
    Swal.fire({
      title: "Change table?",
      text: "You will change the status of the table!",
      icon: "warning",
      showCancelButton: true,
      confirmButtonColor: "#3085d6",
      cancelButtonColor: "#d33",
      confirmButtonText: "Confirm",
    }).then((result) => {
      if (result.isConfirmed) {
        priceUseCase.postPriceTableInactive(priceTableUUID, situation);
        setChanged(!changed);
      }
    });
  };

  /**
   * - *English* This function is responsible for sending a JSON to the backend and will handle the response sent by it, through an asynchronous function.
   *    If this return is successful will return the bank information if not it will be empty.
   * - *Português* Esta função  tem a responsabilidade de enviar um JSON para o backend e tratará da resposta enviada por ele, por meio de uma função assíncrona. Se esse retorno for bem sucedido
   *    retornara as informação do banco se não ficará vazio
   */
  /**
   * - *English* This function is responsible for sending a JSON to the backend and will handle the response sent by it, through an asynchronous function.
   *    If this return is successful will return the bank information if not it will be empty.
   * - *Português* Esta função  tem a responsabilidade de enviar um JSON para o backend e tratará da resposta enviada por ele, por meio de uma função assíncrona. Se esse retorno for bem sucedido
   *    retornara as informação do banco se não ficará vazio
   */
  useEffect(() => {
    document.title = "Lince Tech Micro ERP | Price list";
    const getPriceTables = async () => {
      const pagedPriceTable = await priceUseCase.listPriceTables(
        page,
        rowsPerPage,
        situation,
        orderBy,
        sort,
        chipData
      );
      return pagedPriceTable;
    };
    getPriceTables().then((response) => {
      setPriceTables(response?.prices ?? []);
      setPageList(response?.numberOfPages ?? []);
      // timeOutSpinner();
      // setLoading(false);
    });
  }, [
    page,
    rowsPerPage,
    changed,
    situation,
    orderBy,
    sort,
    labelFilter,
    chipData,
  ]);

  return (
    <Box
      sx={{
        display: "flex",
        marginLeft: "3rem",
        marginTop: "3rem",
        marginRight: "2rem",
      }}
    >
      <input type="hidden" id="modal-price" />
      <input type="hidden" id="modal-detail-price" />
      <Box sx={{ width: "100%" }}>
        <Typography sx={{ fontSize: "26pt", fontWeight: "800" }}>
          Price List
        </Typography>
        <Box
          sx={{
            minWidth: "100%",
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
            marginTop: "0.5rem",
          }}
        >
          <Box sx={{ display: "flex" }}>
            <Box
              sx={{
                display: "flex",
                justifyContent: "center",
                flexWrap: "nowrap",
                listStyle: "none",
                p: 0,
                m: 0,
                border: "none",
                height: "4rem",
                alignItems: "center",
              }}
            >
              {chipData.map((data) => {
                return (
                  <ListItem key={data.valueFilter}>
                    <Tooltip title={data.labelFilter} placement="bottom" arrow>
                      <Chip
                        sx={{
                          textOverFlow: "ellipsis",
                          overFlow: "hidden",
                          whiteSpace: "nowrap",
                          maxWidth: "145px",
                        }}
                        color="primary"
                        variant="outlined"
                        label={data.valueFilter}
                        onDelete={handleDelete(data)}
                      />
                    </Tooltip>
                  </ListItem>
                );
              })}
            </Box>
            {chipData.length === 0 ? (
              <></>
            ) : (
              <Button onClick={handClickResetList}>Clear All</Button>
            )}
          </Box>
          <Box>
            <FormControlLabel
              sx={{ align: "left", fontSize: "11pt" }}
              control={<Switch onChange={handleListInactive} />}
              label="List only inactivated price table"
            />

            <Tooltip title="Create new price table">
              <IconButton
                size="large"
                onClick={(evt) => handleOpenModalPrice(evt)}
              >
                <LibraryAddRoundedIcon color="action" fontSize="medium" />
              </IconButton>
            </Tooltip>
          </Box>
        </Box>
        <Paper sx={{ width: "100%", overflow: "hidden", marginTop: "0.5rem" }}>
          <TableContainer component={Paper}>
            <Table
              stickyHeader
              aria-label="Price Table"
              sx={{ minWidth: 1500 }}
            >
              <TableHead>
                <TableRow>
                  {columns.map((key, index) => (
                    <StyledTableCell
                      colSpan={key.columnSpan}
                      sx={{
                        width: key.width,
                        columnSpan: key.columnSpan,
                        textAlign: key.align,
                      }}
                      key={index}
                    >
                      {key.isOrder === "true" && (
                        <Grid
                          container
                          justifyContent={"space-between"}
                          flexWrap={"nowrap"}
                        >
                          <TableSortLabel
                            sx={{
                              "&.MuiTableSortLabel-root": {
                                color: "white",
                              },
                              "&.MuiTableSortLabel-root:hover": {
                                color: "white",
                              },
                              "&.Mui-active": {
                                color: "white",
                              },
                              "& .MuiTableSortLabel-icon": {
                                color: "white !important",
                              },
                              textAlign: "center",
                            }}
                            active={orderBy === key.value}
                            direction={sort}
                            onClick={() =>
                              handleOrderBy(key.value, key.isOrder)
                            }
                          >
                            {key.label}
                          </TableSortLabel>
                          {key.isFilter === "true" && (
                            <FilterListRoundedIcon
                              aria-describedby={id}
                              variant="contained"
                              onClick={(e) =>
                                handleClickPopover(
                                  e.currentTarget,
                                  key.label,
                                  key.value,
                                  key.type,
                                  key.maxLength,
                                  key.isNumber
                                )
                              }
                              sx={{
                                width: "18px",
                                justifySelf: "end",
                                cursor: "pointer",
                              }}
                            />
                          )}
                        </Grid>
                      )}
                      {key.isOrder === "false" && <Box>{key.label}</Box>}
                    </StyledTableCell>
                  ))}
                </TableRow>
              </TableHead>
              <TableBody>
                {priceTables.map((price, index) => (
                  <StyledTableRow key={index}>
                    <StyledTableCell
                      sx={{
                        overflow: "hidden",
                        flexWrap: "nowrap",
                      }}
                    >
                      {price.code}
                    </StyledTableCell>
                    <StyledTableCell
                      sx={{
                        overflow: "hidden",
                        flexWrap: "nowrap",
                      }}
                    >
                      {price.name}
                    </StyledTableCell>
                    <StyledTableCell
                      sx={{
                        overflow: "hidden",
                        flexWrap: "nowrap",
                      }}
                    >
                      {convertDate(price.initial)}
                    </StyledTableCell>
                    <StyledTableCell
                      sx={{
                        overflow: "hidden",
                        flexWrap: "nowrap",
                      }}
                    >
                      {convertDate(price.final)}
                    </StyledTableCell>
                    <StyledTableCell
                      sx={{
                        overflow: "hidden",
                        flexWrap: "nowrap",
                      }}
                    >
                      {price.isActive === true ? "Active" : "Inactive"}
                    </StyledTableCell>
                    <StyledTableCell
                      sx={{
                        display: "flex",
                        justifyContent: "space-evenly",
                      }}
                    >
                      <Tooltip title="Edit price table" placement="left">
                        <IconButton
                          onClick={(evt) =>
                            handleOpenModalPrice(evt, price.priceTableUUID)
                          }
                        >
                          <EditRoundedIcon color="action" />
                        </IconButton>
                      </Tooltip>
                      <Tooltip title="Price table detail" placement="left">
                        <IconButton
                          onClick={(evt) =>
                            handleOpenModalPriceDetail(
                              evt,
                              price.code,
                              price.priceTableUUID
                            )
                          }
                        >
                          <AddCircleRoundedIcon color="action" />
                        </IconButton>
                      </Tooltip>
                      {price.isActive === true ? (
                        <Tooltip title="Disable price list" placement="left">
                          <IconButton
                            onClick={(evt) =>
                              handleChangeStatusPriceTable(
                                price.priceTableUUID,
                                false
                              )
                            }
                          >
                            <DeleteRoundedIcon color="action" />
                          </IconButton>
                        </Tooltip>
                      ) : (
                        <Tooltip title="Activate price list" placement="left">
                          <IconButton
                            onClick={(evt) =>
                              handleChangeStatusPriceTable(
                                price.priceTableUUID,
                                true
                              )
                            }
                          >
                            <CheckRoundedIcon color="action" />
                          </IconButton>
                        </Tooltip>
                      )}
                    </StyledTableCell>
                  </StyledTableRow>
                ))}
              </TableBody>
            </Table>
          </TableContainer>
        </Paper>
        <Box
          display={"flex"}
          justifyContent={"flex-end"}
          sx={{ marginTop: "2vh", alignItems: "center", gap: "1vw" }}
        >
          <Typography sx={{ align: "center", fontSize: "11pt" }}>
            Rows Per Page
          </Typography>

          <Select
            sx={{ height: "4vh", align: "center" }}
            autoWidth
            value={rowsPerPage}
            onChange={handleChangeRowsPerPage}
          >
            <MenuItem value={5}>5</MenuItem>
            <MenuItem value={10}>10</MenuItem>
            <MenuItem value={15}>15</MenuItem>
          </Select>

          <Stack spacing={2}>
            <Pagination
              count={pageList}
              page={page}
              onChange={handleChangePage}
            />
          </Stack>
        </Box>
      </Box>
      <Popover
        id={id}
        open={openPopover}
        anchorEl={anchorEl}
        onClose={handleClosePopover}
        anchorOrigin={{
          vertical: "bottom",
          horizontal: "left",
        }}
      >
        <Box
          sx={{
            display: "flex",
            alignContent: "center",
            alignItems: "center",
            p: 2,
            gap: 2,
          }}
        >
          <Typography>Filter</Typography>
          <TextField
            type={typePopover}
            inputProps={{ maxLength: maxLegthPopover }}
            variant="outlined"
            placeholder={labelPopover}
            onChange={
              isNumber
                ? handleChangeNumberPopover
                : isNumber
                ? handleChangeNumberPopover
                : handleChangePopover
            }
            size="small"
            onKeyDown={keyPress}
          ></TextField>
          <Button variant="outlined" onClick={handleConfirmPopover}>
            Confirm
          </Button>
        </Box>
      </Popover>
    </Box>
  );
}
