export class Vendor {
    /** 
     * @param {String} uuid 
     * @param {String} identificator 
     * @param {boolean} situation
     * @param {String} name 
     * @param {Array} contact
     * @param {String} address 
     */
    constructor(uuid, identificator, situation, name, contact, address){
        this.uuid = uuid;
        this.identificator = identificator;
        this.situation = situation;
        this.name = name;
        this.contact = contact;
        this.address = address;
    }
}

export class PagedVendor {
    /**
     *
     * @param vendor {Packing[]}
     * @param numberPages {number}
     */
    constructor(vendor, numberPages) {
        this.vendor = vendor
        this.numberPages = numberPages
    }
}