import * as React from "react";
import { styled } from "@mui/material/styles";
import Box from "@mui/material/Box";
import MuiDrawer from "@mui/material/Drawer";
import List from "@mui/material/List";
import CssBaseline from "@mui/material/CssBaseline";
import Typography from "@mui/material/Typography";
import Divider from "@mui/material/Divider";
import ListItem from "@mui/material/ListItem";
import ListItemButton from "@mui/material/ListItemButton";
import ListItemIcon from "@mui/material/ListItemIcon";
import ListItemText from "@mui/material/ListItemText";
import Warehouse from "@mui/icons-material/WarehouseRounded";
import LocalOfferIcon from "@mui/icons-material/LocalOfferRounded";
import { Link, useLocation, useNavigate } from "react-router-dom";
import IconButton from "@mui/material/IconButton";
import { Logout, Password } from "@mui/icons-material";
import ChevronLeftIcon from "@mui/icons-material/ChevronLeft";
import ChevronRightIcon from "@mui/icons-material/ChevronRight";
import User from "@mui/icons-material/Group";
import Authentication_usecase from "../../core/user/usecases/authentication_usecase";
import CompareArrowsRoundedIcon from "@mui/icons-material/CompareArrowsRounded";
import InventoryIcon from "@mui/icons-material/Inventory";
import DescriptionIcon from "@mui/icons-material/Description";
import AddBusinessIcon from "@mui/icons-material/AddBusiness";
import HomeIcon from "@mui/icons-material/Home";
import Price from "@mui/icons-material/RequestQuoteRounded";
import { Button, Collapse } from "@mui/material";
import ExpandLess from "@mui/icons-material/ExpandLess";
import ExpandMore from "@mui/icons-material/ExpandMore";
import { icons as Icons } from "../entities/Icons";

const drawerWidth = 240;

const modules = [
  {
    icon: <HomeIcon />,
    route: "/Home",
    label: "Home",
  },
  {
    icon: <InventoryIcon />,
    label: "Stock",
    expanded: false,
    routes: [
      {
        icon: <InventoryIcon />,
        route: "/Stock",
        label: "Stock",
      },
      {
        icon: <CompareArrowsRoundedIcon />,
        route: "/RequestHistory",
        label: "Request history",
      },
    ],
  },
  {
    icon: <LocalOfferIcon />,
    label: "Product",
    expanded: false,
    routes: [
      {
        icon: <LocalOfferIcon />,
        route: "/Product",
        label: "Product",
      },
      {
        icon: <Price />,
        route: "/Price",
        label: "Price table",
      },
    ],
  },
  {
    icon: <DescriptionIcon />,
    route: "/Packing",
    label: "Packing",
  },
  {
    icon: <Warehouse />,
    route: "/Warehouse",
    label: "Warehouse",
  },
  {
    icon: <AddBusinessIcon />,
    route: "/Vendor",
    label: "Vendor",
  },
  { icon: <Icons.boxIcon />, route: "/BoxList", label: "Box" },
  {
    icon: <User />,
    label: "Users",
    expanded: false,
    routes: [
      {
        icon: <User />,
        route: "/User",
        label: "Users",
      },
      {
        icon: <Password />,
        route: "/ChangePassword",
        label: "Change password",
      },
    ],
  },
];

const openedMixin = (theme) => ({
  width: drawerWidth,
  transition: theme.transitions.create("width", {
    easing: theme.transitions.easing.sharp,
    duration: theme.transitions.duration.enteringScreen,
  }),
  overflowX: "hidden",
});

const closedMixin = (theme) => ({
  transition: theme.transitions.create("width", {
    easing: theme.transitions.easing.sharp,
    duration: theme.transitions.duration.leavingScreen,
  }),
  overflowX: "hidden",
  width: `calc(${theme.spacing(7)} + 1px)`,
  [theme.breakpoints.up("sm")]: {
    width: `calc(${theme.spacing(8)} + 1px)`,
  },
});

const Drawer = styled(MuiDrawer, {
  shouldForwardProp: (prop) => prop !== "open",
})(({ theme, open }) => ({
  width: drawerWidth,
  flexShrink: 0,
  whiteSpace: "nowrap",
  boxSizing: "border-box",
  ...(open && {
    ...openedMixin(theme),
    "& .MuiDrawer-paper": openedMixin(theme),
  }),
  ...(!open && {
    ...closedMixin(theme),
    "& .MuiDrawer-paper": closedMixin(theme),
  }),
}));

const DrawerHeader = styled("div")(({ theme }) => ({
  display: "flex",
  alignItems: "center",
  justifyContent: "flex-end",
  padding: theme.spacing(0, 1),
  // necessary for content to be below app bar
  ...theme.mixins.toolbar,
}));

export default function ScreenSkeleton({ data }) {
  const location = useLocation().pathname;
  const drawerOpenKey = "drawerOpen";
  const defaultOpen = localStorage.getItem(drawerOpenKey) === "true";
  const [open, setOpen] = React.useState(defaultOpen);
  const [modulesSelect, setModulesSelect] = React.useState(modules);
  const [change, setChange] = React.useState();

  const openListSelect = (id) => {
    modulesSelect[id].expanded = !modulesSelect[id].expanded;
    setModulesSelect(modulesSelect);
    setChange(!change);
  };

  if (location === "/BoxList") {
    modules[6].icon = <Icons.boxIcon color={"white"} />;
  } else {
    modules[6].icon = <Icons.boxIcon color={""} />;
  }

  React.useEffect(() => {
    localStorage.setItem(drawerOpenKey, open);
  }, [open, change]);

  const handleDrawerOpen = () => {
    setOpen(true);
  };

  const handleDrawerClose = () => {
    setOpen(false);
  };

  const logout = async () => {
    await Authentication_usecase.logout();
    window.location.reload();
  };

  return (
    <Box sx={{ display: "flex" }}>
      <CssBaseline />
      <Drawer
        variant="permanent"
        open={open}
        PaperProps={{
          sx: {
            backgroundColor: "#15191C",
            color: "white",
          },
        }}
        sx={{
          "& .MuiDrawer-paper": {
            display: "grid",
            gridTemplateRows: "auto 1fr auto",
            gridTemplateAreas: "'header' 'main' 'footer'",
          },
        }}
      >
        <DrawerHeader
          sx={{
            gridArea: "header",
            display: "flex",
            justifyContent: "space-between",
          }}
        >
          {open ? (
            <Typography sx={{ marginLeft: "10px", fontSize: "15pt" }}>
              Lince Tech
            </Typography>
          ) : (
            ""
          )}
          <IconButton
            sx={{ color: "white" }}
            onClick={open ? handleDrawerClose : handleDrawerOpen}
          >
            {open ? <ChevronLeftIcon /> : <ChevronRightIcon />}
          </IconButton>
        </DrawerHeader>
        <Divider />
        <List sx={{ gridArea: "main" }}>
          {modulesSelect.map((module, index) => {
            if (module.routes === undefined) {
              return (
                <Link
                  key={index}
                  to={module.route}
                  style={{ textDecoration: "none" }}
                  title={module.label}
                >
                  <ListItem
                    key={module.route}
                    disablePadding
                    sx={{ display: "block" }}
                  >
                    <ListItemButton
                      sx={
                        location === module.route
                          ? {
                            color: "white",
                            minHeight: 48,
                            justifyContent: open ? "initial" : "center",
                            px: 2.5,
                          }
                          : {
                            color: "white",
                            minHeight: 48,
                            px: 2.5,
                          }
                      }
                      selected={location === module.route ? true : false}
                    >
                      <ListItemIcon
                        sx={
                          location === module.route
                            ? {
                              color: "white",
                              minWidth: 0,
                              mr: open ? 3 : "auto",
                              justifyContent: "center",
                            }
                            : {
                              color: "gray",
                              minWidth: 0,
                              mr: open ? 3 : "auto",
                              justifyContent: "center",
                            }
                        }
                      >
                        {module.icon}
                      </ListItemIcon>
                      <ListItemText
                        primary={module.label}
                        sx={{ opacity: open ? 1 : 0 }}
                      />
                    </ListItemButton>
                  </ListItem>
                </Link>
              );
            } else {
              return (
                <List key={index} sx={{ p: 0 }}>
                  <ListItemButton
                    onClick={() => openListSelect(index)}
                    sx={
                      location === module.route
                        ? {
                          color: "white",
                          minHeight: 48,
                          justifyContent: open ? "initial" : "center",
                          px: 2.5,
                          display: "flex",
                          flexDirection: open ? "row" : "column",
                          justifyContent: "center",
                          height: '4rem',
                        }
                        : {
                          color: "white",
                          minHeight: 48,
                          px: 2.5,
                          display: "flex",
                          flexDirection: open ? "row" : "column",
                          alignItems: open ? "center" : "start",
                          justifyContent: "center",
                          height: '4rem',
                        }
                    }
                  >
                    <ListItemIcon
                      sx={{
                        color: "gray",
                        minWidth: 0,
                        mr: open ? 3 : 0,
                      }}
                    >
                      {module.icon}
                    </ListItemIcon>
                    <ListItemText
                      primary={module.label}
                      sx={open ? { opacity: 1 } : { display: "none" }}
                    />
                    {module.expanded ? (
                      <ExpandLess sx={{ color: "gray" }} />
                    ) : (
                      <ExpandMore sx={{ color: "gray" }} />
                    )}
                  </ListItemButton>
                  <Collapse
                    in={module.expanded}
                    timeout="auto"
                    unmountOnExit
                    sx={{ backgroundColor: "#323F4991" }}
                  >
                    <List component="div" disablePadding>
                      {module.routes.map((route, index) => {
                        return (
                          <Link
                            key={index}
                            to={route.route}
                            style={{ textDecoration: "none", color: "#ffffff" }}
                            title={route.label}
                            onClick={() => setChange(!change)}
                          >
                            <ListItemButton
                              sx={
                                location === route.route
                                  ? {
                                    color: "white",
                                    minHeight: 48,
                                    justifyContent: open
                                      ? "initial"
                                      : "center",
                                    px: 2.5,
                                  }
                                  : {
                                    color: "white",
                                    minHeight: 48,
                                    px: 2.5,
                                  }
                              }
                              selected={location === route.route ? true : false}
                            >
                              <ListItemIcon
                                sx={
                                  location === route.route
                                    ? {
                                      color: "white",
                                      minWidth: 0,
                                      mr: open ? 3 : "auto",
                                      justifyContent: "center",
                                    }
                                    : {
                                      color: "#D3D3D3",
                                      minWidth: 0,
                                      mr: open ? 3 : "auto",
                                      justifyContent: "center",
                                    }
                                }
                              >
                                {route.icon}
                              </ListItemIcon>
                              <ListItemText
                                primary={route.label}
                                sx={{ opacity: open ? 1 : 0 }}
                              />
                            </ListItemButton>
                          </Link>
                        );
                      })}
                    </List>
                  </Collapse>
                </List>
              );
            }
          })}
        </List>
        {open ? (
          <ListItem key="logout" disablePadding sx={{ display: "block" }}>
            <ListItemButton
              onClick={logout}
              sx={{
                minHeight: 60,
                justifyContent: open ? "initial" : "center",
                px: 2.5,
                opacity: 0.9,
              }}
            >
              {/* TODO: Create a proper method that calls the logout usecase, then redirect the user back to the login page */}
              <ListItemIcon
                sx={{
                  color: "red",
                  minWidth: 0,
                  mr: open ? 3 : "auto",
                  justifyContent: "center",
                  opacity: 0.9,
                }}
              >
                <Logout />
              </ListItemIcon>

              <ListItemText primary={"Logout"} />
            </ListItemButton>
          </ListItem>
        ) : (
          <ListItem key="logout" disablePadding sx={{ display: "block" }}>
            <ListItemButton
              onClick={logout}
              sx={{
                color: "red",
                minHeight: 60,
                justifyContent: open ? "initial" : "center",
                px: 2.5,
                opacity: 0.9,
              }}
            >
              {/* TODO: Create a proper method that calls the logout usecase, then redirect the user back to the login page */}
              <ListItemIcon
                sx={{
                  color: "red",
                  minWidth: 0,
                  mr: open ? 3 : "auto",
                  justifyContent: "center",
                  opacity: 0.9,
                }}
              >
                <Logout />
              </ListItemIcon>
            </ListItemButton>
          </ListItem>
        )}
      </Drawer>
    </Box>
  );
}
