import AuthenticationUseCase from "../../usecases/authentication_usecase";

import { useState } from "react";

import TextField from "@mui/material/TextField";

import Button from "@mui/material/Button";

import Typography from "@mui/material/Typography";

import Box from "@mui/material/Box";

import Link from "@mui/material/Link";

import IconButton from "@mui/material/IconButton";

import InputAdornment from "@mui/material/InputAdornment";

import Visibility from "@mui/icons-material/Visibility";

import VisibilityOff from "@mui/icons-material/VisibilityOff";

import { useNavigate } from "react-router-dom";

import "./Login.css";
import { useEffect } from "react";

function Login() {
  const navigate = useNavigate();

  const [credentials, setCredentials] = useState({
    login: "",

    password: "",
  });

  const [loginError, setLoginError] = useState("");

  const [passwordError, setPasswordError] = useState("");

  const [apiError, setApiError] = useState("");

  const [isPasswordVisible, setIsPasswordVisible] = useState(false);

  const submit = async (event) => {
    event.preventDefault();

    try {
      const user = await AuthenticationUseCase.login(
        credentials.login,

        credentials.password
      );

      if (user.isPasswordExpired) {
        navigate("/changepassword");

        return;
      }

      navigate("/Home");
    } catch (e) {

      if (e.length) {
        e.forEach((error) => {
          if (error.code === "INVALID_LOGIN") {
            setLoginError(error.message);
          }

          if (error.code === "INVALID_PASSWORD") {
            setPasswordError(error.message);
          }
        });
      } else if (e.response.data) {
        setApiError(e.response.data.message);
      }
    }
  };

  const handleLoginInput = (event) => {
    setCredentials((credentials) => ({
      ...credentials,

      login: event.target.value,
    }));

    if (loginError) {
      setLoginError("");
    }

    if (apiError) {
      setApiError("");
    }
  };

  const handlePasswordInput = (event) => {
    setCredentials((credentials) => ({
      ...credentials,

      password: event.target.value,
    }));

    if (passwordError) {
      setPasswordError("");
    }

    if (apiError) {
      setApiError("");
    }
  };

  const togglePasswordVisibility = () => {
    setIsPasswordVisible(!isPasswordVisible);
  };

  useEffect(() => {
    document.title = 'Lince Tech Micro ERP | Login'
  }, [])

  return (
    <Box className="login-view" backgroundColor="Background">
      <Box>
        <Typography component="h1" variant="h4">
          Hello! Welcome back.
        </Typography>

        <Box component="form" onSubmit={submit} noValidate sx={{ mt: 1 }}>
          <fieldset className="fieldset">
            <Typography component="legend" marginBottom="1rem">
              Sign in to your account
            </Typography>

            {apiError && (
              <Box
                sx={{
                  background: "#ffdbdb",

                  padding: "0.5rem",
                }}
              >
                {apiError}
              </Box>
            )}

            <TextField
              name="login"
              type="text"
              label="Login"
              variant="standard"
              autoFocus
              required
              error={Boolean(loginError.length)}
              helperText={loginError}
              value={credentials.login}
              onInput={handleLoginInput}
            />

            <TextField
              name="password"
              type={isPasswordVisible ? "text" : "password"}
              label="Password"
              variant="standard"
              autoComplete="current-password"
              required
              error={Boolean(passwordError.length)}
              helperText={passwordError}
              value={credentials.password}
              onInput={handlePasswordInput}
              InputProps={{
                endAdornment: (
                  <InputAdornment position="end">
                    <IconButton
                      aria-label="Toggle password visibility"
                      onClick={togglePasswordVisibility}
                    >
                      {isPasswordVisible ? (
                        <Visibility sx={{ width: "20px", height: "20px" }} />
                      ) : (
                        <VisibilityOff sx={{ width: "20px", height: "20px" }} />
                      )}
                    </IconButton>
                  </InputAdornment>
                ),
              }}
            />

            <Button
              type="submit"
              id="contained-button"
              variant="contained"
              color="primary"
            >
              Login
            </Button>

            <Link href="/web/ResetPassword?step=1">Forgot password?</Link>
          </fieldset>
        </Box>
      </Box>
    </Box>
  );
}

export default Login;
