import * as React from "react";
import { useEffect, useState } from "react";
import Button from "@mui/material/Button";
import { styled } from "@mui/material/styles";
import Dialog from "@mui/material/Dialog";
import DialogActions from "@mui/material/DialogActions";
import DialogContent from "@mui/material/DialogContent";
import DialogContentText from "@mui/material/DialogContentText";
import DialogTitle from "@mui/material/DialogTitle";
import DeleteRoundedIcon from "@mui/icons-material/DeleteRounded";
import Typography from "@mui/material/Typography";
import Box from "@mui/material/Box";
import {
  FormControl,
  IconButton,
  InputLabel,
  MenuItem,
  Paper,
  Select,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  TextField,
  tableCellClasses,
} from "@mui/material";
import { priceUseCase } from "../usecases/PriceUseCases";
import { NumericFormat } from "react-number-format";
import Swal from "sweetalert2";
import PropTypes from "prop-types";

const Toast = Swal.mixin({
  toast: true,
  position: "top-end",
  showConfirmButton: false,
  timer: 3000,
  timerProgressBar: true,
  didOpen: (toast) => {
    toast.addEventListener("mouseenter", Swal.stopTimer);
    toast.addEventListener("mouseleave", Swal.resumeTimer);
  },
});

const columns = [
  { id: "productTextCode", label: "Product Code", minWidth: 10, align: "left" },
  { id: "productTextName", label: "Product Name", minWidth: 20, align: "left" },
  { id: "colorNumericCode", label: "Color", minWidth: 10, align: "left" },
  { id: "cost", label: "Cost", minWidth: 10, align: "left" },
  { id: "sale", label: "Sale", minWidth: 10, align: "left" },
  { id: "action", label: "Action", minWidth: 10, align: "center" },
];

const NumericFormatCustom = React.forwardRef(function NumericFormatCustom(
  props,
  ref
) {
  const { onChange, ...other } = props;

  return (
    <NumericFormat
      {...other}
      getInputRef={ref}
      onValueChange={(values) => {
        onChange({
          target: {
            name: props.name,
            value: values.value,
          },
        });
      }}
      thousandSeparator
      valueIsNumericString
      maxLength={12}
    />
  );
});

NumericFormatCustom.propTypes = {
  name: PropTypes.string.isRequired,
  onChange: PropTypes.func.isRequired,
};

export default function ModalPriceDetail({
  priceCode,
  priceUuid,
  isOpen,
  parentCallback,
}) {
  const [open, setOpen] = useState(isOpen);
  const [scroll, setScroll] = useState("body");
  const [changed, setChanged] = useState("");
  const [priceTableProduct, setPriceTableProduct] = useState([]);
  const [productList, setProductList] = useState([]);
  const [productColorList, setProductColorList] = useState([]);
  const [productCode, setProductCode] = useState("");
  const [colorCode, setColorCode] = useState("");
  const [values, setValues] = useState({ cost: "", sale: "" });
  const [error, setError] = useState([]);

  const handleClose = () => {
    setOpen(false);
  };

  const handleRemoveProduct = (priceTableUuid, productUuid) => {
    Swal.fire({
      title: "Delete product?",
      text: "You will delete this product!",
      icon: "warning",
      showCancelButton: true,
      confirmButtonColor: "#3085d6",
      cancelButtonColor: "#d33",
      confirmButtonText: "Confirm",
    }).then((result) => {
      if (result.isConfirmed) {
        priceUseCase.priceTableProductRemove(productUuid).then(() => {
          setChanged(!changed);
        });
        return Toast.fire({
          icon: "success",
          text: "Successfully deleted",
        });
      }
    });
  };

  const handleChangeProduct = (event) => {
    console.log(event.target.value);
    setProductCode(event.target.value);
    setError([]);
    setChanged(!changed);
  };

  const handleCreateProduct = () => {
    Swal.fire({
      title: "Do you want insert/update this product?",
      text: "Product: " + productCode + " Color: " + colorCode,
      icon: "warning",
      showCancelButton: true,
      confirmButtonColor: "#3085d6",
      cancelButtonColor: "#d33",
      confirmButtonText: "Confirm",
    }).then((result) => {
      if (result.isConfirmed) {
        createProduct();
      }
    });
  };

  const createProduct = async () => {
    const response = await priceUseCase.postPriceTableProduct(
      priceUuid,
      productCode,
      colorCode,
      values
    );
    if (response.size) {
      const error = response.values();
      const errorKey = response.keys();
      setError(errorKey.next().value.key);
      return Swal.fire({
        icon: "warning",
        confirmButtonText: "OK",
        text: error.next().value,
      });
    }
    if (response.data.error !== null) {
      return Swal.fire({
        icon: "error",
        confirmButtonText: "OK",
        text: response?.data?.error?.description ?? "",
      });
    } else {
      setChanged(!changed);
      setProductCode("");
      setColorCode("");
      values.cost = "";
      values.sale = "";
      return Toast.fire({
        icon: "success",
        text: "Successfully registered",
      });
    }
  };

  const handleChange = (event) => {
    setValues({
      ...values,
      [event.target.name]: event.target.value,
    });
  };

  useEffect(() => {
    const getPriceTableProduct = async () => {
      const getProduct = await priceUseCase.getInformationPrice(priceUuid);
      return getProduct;
    };
    getPriceTableProduct().then((response) => {
      setPriceTableProduct(response.priceTableProducts);
    });

    const getProductList = async () => {
      const getProductL = await priceUseCase.getProductList();
      return getProductL;
    };
    getProductList().then((response) => {
      setProductList(response?.data?.product ?? []);
    });

    if (productCode !== "") {
      const getProductColorLists = async () => {
        const getProductColor = await priceUseCase.getProductColorList(
          productCode
        );
        return getProductColor;
      };
      getProductColorLists().then((response) => {
        setProductColorList(response?.data?.colors ?? []);
      });
    }
  }, [changed]);

  return (
    <div>
      <Dialog
        open={open}
        onClose={handleClose}
        scroll={scroll}
        maxWidth="lg"
        fullWidth
      >
        <DialogTitle id="scroll-dialog-title">
          <Box sx={{ display: "flex", justifyContent: "space-between" }}>
            <Typography
              sx={{
                fontSize: "1.2em",
                fontWeight: "700",
                color: "#363636",
              }}
            >
              Products List: {priceCode}
            </Typography>
          </Box>
          <Box sx={{ borderBottom: 1, borderColor: "divider" }}></Box>
          <Box
            sx={{
              display: "flex",
              width: "100%",
              marginTop: "1.5rem",
              gap: "1.1rem",
            }}
          >
            <FormControl
              sx={{ width: "40%" }}
              {...(error === "product" && { error })}
            >
              <InputLabel id="select-product-label">Product</InputLabel>
              <Select
                labelId="select-product-label"
                value={productCode}
                label="product"
                onChange={handleChangeProduct}
              >
                {productList.map((key, index) => (
                  <MenuItem key={index} value={key.numericCode}>
                    {key.description}
                  </MenuItem>
                ))}
              </Select>
            </FormControl>
            <FormControl sx={{ width: "25%" }}>
              <InputLabel id="select-color-label">Color</InputLabel>
              <Select
                labelId="select-color-label"
                value={colorCode}
                label="color"
                onChange={(event) => setColorCode(event.target.value)}
              >
                <MenuItem value={""}>&nbsp;</MenuItem>
                {productColorList.map((key, index) => (
                  <MenuItem key={index} value={key.color.code}>
                    {key.color.code} - {key.color.description}
                  </MenuItem>
                ))}
              </Select>
            </FormControl>
            <TextField
              label="Coast"
              value={values.cost}
              onChange={(evt) => {
                handleChange(evt);
                setError([]);
              }}
              name="cost"
              sx={{ width: "10%" }}
              InputProps={{
                inputComponent: NumericFormatCustom,                
              }}
              variant="outlined"
              format="###.###,##"
              {...(error === "cost" && { error })}
            />
            <TextField
              label="Sale"
              value={values.sale}
              onChange={(evt) => {
                handleChange(evt);
                setError([]);
              }}
              name="sale"
              sx={{ width: "10%" }}
              InputProps={{
                inputComponent: NumericFormatCustom,
              }}
              variant="outlined"
              displayType={"number"}
              {...(error === "sale" && { error })}
            />
            <Button
              variant="contained"
              size="large"
              onClick={handleCreateProduct}
            >
              Create
            </Button>
          </Box>
        </DialogTitle>
        <DialogContent sx={{ height: "70vh" }}>
          <Box sx={{ width: "100%", marginTop: "0.5rem" }}>
            <TableContainer component={Paper}>
              <Table>
                <TableHead>
                  <TableRow>
                    {columns.map((column) => (
                      <TableCell
                        key={column.id}
                        width={"25%"}
                        height={"65px"}
                        style={{
                          align: column.align,
                          fontWeight: "700",
                          backgroundColor: "#ECF0F1",
                        }}
                      >
                        {column.label}
                      </TableCell>
                    ))}
                  </TableRow>
                </TableHead>
                <TableBody>
                  {priceTableProduct.map((product, index) => (
                    <TableRow hover role="checkbox" key={index}>
                      <TableCell>{product.product.textCode}</TableCell>
                      <TableCell>{product.product.description}</TableCell>
                      <TableCell>
                        {product.color.code === null
                          ? "All"
                          : product.color.code}
                      </TableCell>
                      <TableCell>{product.cost}</TableCell>
                      <TableCell>{product.sale}</TableCell>
                      <TableCell>
                        <IconButton
                          onClick={(evt) =>
                            handleRemoveProduct(priceUuid, product.uuid)
                          }
                        >
                          <DeleteRoundedIcon color="action" />
                        </IconButton>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </TableContainer>
          </Box>
        </DialogContent>
        <DialogActions>
          <Box
            sx={{
              display: "flex",
              justifyContent: "end",
              marginBottom: "15px",
              marginRight: "15px",
            }}
          >
            <Button variant="outlined" onClick={handleClose}>
              Close
            </Button>
          </Box>
        </DialogActions>
      </Dialog>
    </div>
  );
}
